const CORPUS_PAIRS = [
  { k:'mtpe_0081', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Politics, Otto Von Bismarck is supposed to have said, is the art of the possible.', mt:'', ref:'奥托·冯·俾斯麦 (Otto Von Bismarck) 似曾说过，政治是“将一切变为可能”的艺术。' },
  { k:'mtpe_0082', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'And one of the most depressing features of discussions about global warming is their tendency to take place in a fantasy land of the politically impossible.', mt:'', ref:'但是关于全球变暖的讨论却往往是政治上不可能实现的幻想，这也是相关讨论令人沮丧的一大特征。' },
  { k:'mtpe_0083', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Few people in those parts of the world made rich by carbon-dioxide-emitting enterprise are going to volunteer for a cut in living standards.', mt:'', ref:'在世界上因二氧化碳排放而过上富足生活的地区，很少有人会自愿降低生活质量。' },
  { k:'mtpe_0084', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'And it is hard to ask those from parts of the world that are not yet rich to sacrifice the chance to become so.', mt:'', ref:'要让那些还不富裕地区的人们放弃成为富人的机会也很难。' },
  { k:'mtpe_0085', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'That being the case, it makes sense to concentrate on doing things which affect neither the comforts of the former nor the aspirations of the latter.', mt:'', ref:'因此，集中精力做些实事，既不影响富人的舒适生活，也不打击不富裕的人们追求富裕生活的愿望，这样才有意义。' },
  { k:'mtpe_0086', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Technological change that shifts economies away from using fossil fuels as their principal energy sources may be able to achieve this in the long term.', mt:'', ref:'从长期来看，推动技术变革，促使经济不再依赖化石燃料作为主要能源，或许能够实现这一目标。' },
  { k:'mtpe_0087', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'But some sort of effective action is also needed now.', mt:'', ref:'但是，目前仍然有待采取一些有效的行动。' },
  { k:'mtpe_0088', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'A study published in Science in 2018 measured leaks from a third of America’s natural-gas supply chain and oil-production sites.', mt:'', ref:'幸运的是，目前的有些行动是行之有效的。' },
  { k:'mtpe_0089', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'For carbon dioxide is not the only cause of global warming.', mt:'', ref:'因为二氧化碳并非是全球变暖的唯一原因。' },
  { k:'mtpe_0090', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'About a quarter of the effect is a consequence of a different gas, methane.', mt:'', ref:'气候变暖的成因有四分之一在于另外一种气体——甲烷。' },
  { k:'mtpe_0091', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'And the methane problem looks a lot more tractable in the short term than does the carbon-dioxide one.', mt:'', ref:'短期来看，甲烷要比二氧化碳更容易对付。' },
  { k:'mtpe_0092', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'CO2 v CH4', mt:'', ref:'二氧化碳（CO2）对甲烷（CH4）' },
  { k:'mtpe_0093', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Going after methane, a compound of one carbon atom with four hydrogens, makes sense, for it is a potent greenhouse agent.', mt:'', ref:'致力于解决甲烷的问题是有道理的，因为这种由一个碳原子和四个氢原子组成的化合物是一种强效温室气体。' },
  { k:'mtpe_0094', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Over the 20 years subsequent to its emission a tonne of methane causes 86 times more warming than does a tonne of CO2.', mt:'', ref:'有一项研究对甲烷进行了20多年的跟踪，研究结果发现，一吨甲烷所造成的全球变暖效果是一吨二氧化碳的86倍。' },
  { k:'mtpe_0095', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Also, it does not hang around.', mt:'', ref:'此外，甲烷不会长久停留在大气中。' },
  { k:'mtpe_0096', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'It has a half-life in the atmosphere of about a decade, so what is released soon vanishes.', mt:'', ref:'甲烷在大气中的半衰期大约为十年，因此，甲烷一释放出来不久就会消失。' },
  { k:'mtpe_0097', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'By contrast, CO2 lingers for hundreds, or even thousands, of years.', mt:'', ref:'相比之下，二氧化碳会在大气中存在几百年甚至几千年。' },
  { k:'mtpe_0098', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The Climate and Clean Air Coalition, a collaboration of governments and environmental lobby groups, therefore reckons that halving anthropogenic methane emissions over the next 30 years could shave 0.18°C off the average global temperature in 2050.', mt:'', ref:'气候和清洁空气联盟（Climate and Clean Air Coalition）是由各国政府和环保组织共同组建的环保组织，该联盟认为，如果未来30年间人为甲烷排放量减半，到2050年就可能使全球平均温度降低0.18摄氏度。' },
  { k:'mtpe_0099', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'That may not sound much, but it is between 20% and 45% of the gap between current temperatures and the goal, agreed on in Paris in 2015 by most of the world’s countries, of stabilising temperatures between 1.5°C and 2°C above pre-industrial averages.', mt:'', ref:'这个降幅似乎并不多，但已相当于当前气温和2015年巴黎气候大会上大多数国家达成一致的目标之间差值的20%-45%；巴黎气候大会确定的目标是将气温稳定在比工业化前平均气温高1.5-2摄氏度之间。' },
  { k:'mtpe_0100', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Moreover, in many cases the cost of stopping emissions of methane can be offset against the fact that, unlike carbon dioxide, it is a valuable commodity.', mt:'', ref:'此外，在许多情况下，停止甲烷排放的成本可被抵消，因为它与二氧化碳不同，是一种有价值的商品。' },
  { k:'mtpe_0101', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The International Energy Agency (IEA, an intergovernmental organisation based in Paris) estimates that 75% of emissions from the oil and gas sector—some 16.5% of total human emissions—could be avoided with technologies available today, and that 40% (9% of total human emissions) could be eliminated at no net cost.', mt:'', ref:'据国际能源署（IEA，一家总部位于巴黎的政府间组织）估计，油气行业75%的甲烷排放（约占人类总排放量的16.5%）可以利用现有的技术消除，40%的排放（占人类总排放量的9%）可以采用净成本为零的方式消除。' },
  { k:'mtpe_0102', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The importance of tackling methane has become more apparent in the past decade and a half.', mt:'', ref:'十五年来，解决甲烷问题的重要性逐渐显现。' },
  { k:'mtpe_0103', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'After a plateau which began in 1999, concentrations of the gas in the atmosphere started rising again in 2007, a trend that continues to this day.', mt:'', ref:'大气中的甲烷浓度自1999年起一直保持稳定，从2007年开始上升，一直延续至今。' },
  { k:'mtpe_0104', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'At the moment, more than 300 million tonnes are emitted every year as a consequence of human activity, and that rate is growing.', mt:'', ref:'目前，每年人类活动会排放3亿吨甲烷，而且这一数量还在不断增长。' },
  { k:'mtpe_0105', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'As a result, methane concentrations are now more than two-and-a-half times what they were before the Industrial Revolution, and are rising faster than allowed for in all but the most pessimistic climate projections for the 21st century.', mt:'', ref:'因此，当今的甲烷浓度已经是工业革命前的2.5倍以上，而且增长速度接近对21世纪气候变化最悲观的估测。' },
  { k:'mtpe_0106', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The rise after 2007 prompted a rush to understand methane’s sources and how it degrades in the atmosphere.', mt:'', ref:'2007年后的甲烷排放上升趋势，迫使人们亟需尽快了解甲烷的源头及其在大气中的降解方式等问题。' },
  { k:'mtpe_0107', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'That rise was originally seen as an anomaly, says Marielle Saunois of France’s Climate and Environmental Sciences Laboratory, “but now that it has been going on for 13 or 14 years, we see the plateau as the anomaly”.', mt:'', ref:'法国气候与环境科学实验室的玛丽埃勒·索诺伊斯（Marielle Saunois ）表示，“甲烷排放量的上升最初被当成了反常现象，但是，至今这种上升趋势已经持续了十三、四年了，我们认为2007年以前的稳定期才是反常现象。”' },
  { k:'mtpe_0108', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Both ground-based and aerial studies show that leaky natural-gas pipes are one culprit.', mt:'', ref:'地面及空中的监测研究均表明，天然气管道泄漏是罪魁祸首之一。' },
  { k:'mtpe_0109', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'In 2018, for example, instruments mounted on planes flying downwind of Washington, Baltimore, Philadelphia, New York and Boston found that 850,000 tonnes of methane a year was wafting from these cities.', mt:'', ref:'例如，2018年，在华盛顿、巴尔的摩、费城、纽约和波士顿下风向飞行的飞机上的检测仪器显示，每年会有85万吨的甲烷从这些城市逸出。' },
  { k:'mtpe_0110', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'That is roughly ten times the official estimate of the American government’s Environment Protection Agency (EPA).', mt:'', ref:'这大约是美国环境保护局（EPA）官方估测的十倍。' },
  { k:'mtpe_0111', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'A bigger source of emissions, though, is further up the fossil-fuel supply chain—at the points where natural gas, oil and coal are extracted from Earth’s crust, processed and moved around the globe.', mt:'', ref:'更大的排放源可以追溯到化石燃料供应链的上游：从地壳中开采天然气、石油、煤，经过加工后运输到世界各地。' },
  { k:'mtpe_0112', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'A study published in Science in 2018 measured leaks from a third of America’s natural-gas supply chain and oil-production sites.', mt:'', ref:'2018年发表在《科学》杂志的一项研究监测了美国三分之一的天然气供应链以及石油生产场所的泄漏情况。' },
  { k:'mtpe_0113', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Extrapolating from this sample, the team involved estimated that some 13 million tonnes of methane escaped from these facilities each year, approximately 60% more than the EPA’s official figures.', mt:'', ref:'该研究团队根据采样分析推测，这些设施每年大约泄漏1300万吨的甲烷，约比美国环境保护局的官方数值高60%。' },
  { k:'mtpe_0114', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The IEA, meanwhile, estimates that each year the world’s coal mines liberate roughly 40 million tonnes of methane that was once trapped in the coal being extracted.', mt:'', ref:'同时，国际能源署估计，全球煤矿每年大约释放出4000万吨甲烷，而这些气体原本存储在煤矿之中，挖矿时会释放出来。' },
  { k:'mtpe_0115', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'As a source of power, coal is on its way out, but not fast enough.', mt:'', ref:'燃煤发电正在逐渐被淘汰，但速度还不够快。' },
  { k:'mtpe_0116', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'It maintains a stronghold in Asia, and in China in particular, where it could stymie efforts to stabilise the climate.', mt:'', ref:'亚洲，尤其是中国，仍然大量采用燃煤发电，这会妨碍稳定气候变化的努力。' },
  { k:'mtpe_0117', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Researchers at Global Energy Monitor, an environmental lobby group that maintains a log of coal-related operations around the world, estimate that planned new mines will emit a further 13.5 million tonnes a year.', mt:'', ref:'全球能源监测组织（Global Energy Monitor)是一个监测全球煤炭产业日常运营的环保组织，该组织的研究人员预测，每年计划新建煤矿的排放量将达1350万吨。' },
  { k:'mtpe_0118', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Their report, published in March, surveyed 432 mining projects, more than 100 of which are already under construction in China.', mt:'', ref:'该组织在三月份发布的报告调查了432个采矿项目，其中，100多个项目已经在中国开工建设。' },
  { k:'mtpe_0119', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'As soon as a seam is opened it starts to emit methane.', mt:'', ref:'只要打开煤层，就会开始排放甲烷。' },
  { k:'mtpe_0120', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'While a mine is active its methane is vented deliberately into the atmosphere to avoid explosions.', mt:'', ref:'一旦开始生产，为避免爆炸，煤矿就要有意地把甲烷排放到大气中。' },
  { k:'mtpe_0121', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'But even once it has been closed it can carry on leaking the gas for decades.', mt:'', ref:'即使煤矿关停之后，仍会继续泄漏甲烷几十年。' },
  { k:'mtpe_0122', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The task of putting together all the data on sources of methane has fallen to an international collaboration called the Global Methane Budget, led by Dr Saunois.', mt:'', ref:'由索诺伊斯博士领导的国际合作组织项目全球甲烷预算（Global Methane Budget)承担收集甲烷源头数据的任务。' },
  { k:'mtpe_0123', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'This seeks to understand what might be called the methane cycle, by tracing how much CH4 makes its way into and out of the atmosphere every year, and developing a model that describes this.', mt:'', ref:'通过跟踪每年进出大气的甲烷量，该项目开发了描述所谓“甲烷循环”过程的模型。' },
  { k:'mtpe_0124', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Gas pains', mt:'', ref:'甲烷之伤' },
  { k:'mtpe_0125', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Besides leaky wells and pipelines, and gassy coal mines, methane is also emitted by belching cattle, rice paddies, forest fires, slash-and-burn agriculture, rubbish dumps, wastewater-treatment plants, cars and lorries, and natural ecosystems such as swamps, rivers and lakes.', mt:'', ref:'除了矿井、管道、瓦斯煤矿会泄漏甲烷，牲畜、稻田、林火、刀耕火种、垃圾堆场、污水处理、汽车卡车以及诸如湿地、河湖等自然生态系统都会释放甲烷。' },
  { k:'mtpe_0126', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'A perfect inventory would require knowledge of the size, nature and locations of all such sources around the globe—currently an impossible undertaking.', mt:'', ref:'厘清上述源头的全球性规模、性质以及位置，才能获得一份堪称完美的源头清单，但目前这是一项无法完成的任务。' },
  { k:'mtpe_0127', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Instead, researchers at the Global Methane Budget combine two methods, one bottom-up, the other top-down, to arrive at the best estimate they can.', mt:'', ref:'因此，全球甲烷预算（Global Methane Budget)项目研究人员采用了自下而上和自上而下相结合的方法，以求达到最精准的估值。' },
  { k:'mtpe_0128', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The bottom-up approach is to scrape national and international sets of data for information on all possible sources of the gas, and then combine this with estimates of how much methane each type of source emits.', mt:'', ref:'自下而上的方法，就是收集所有国家和国际甲烷来源数据，然后将这些数据与每种来源的甲烷排放量估值相结合。' },
  { k:'mtpe_0129', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The top-down approach employs direct satellite and ground-based measurements of methane concentrations.', mt:'', ref:'自上而下的方法，就是直接采用卫星及地面监测装置收集甲烷浓度信息。' },
  { k:'mtpe_0130', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The two are reconciled by plugging the list of sources into a computer model intended to simulate the flow of methane from its sources and the way it is broken down in the atmosphere.', mt:'', ref:'这两种方法得出的数据相结合，制成源头清单并录入计算机模型，模仿甲烷从源头释放的情况及其在大气中的降解方式。' },
  { k:'mtpe_0131', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'This produces hypothetical atmospheric concentrations which can be checked against the real measurements.', mt:'', ref:'这样就可以得出假设的甲烷浓度，可与真实测量数据进行比对。' },
  { k:'mtpe_0132', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Mismatches are reduced by adjusting the modelled flows to arrive at a best estimate of what is actually happening.', mt:'', ref:'通过调整释出数据，可得出接近真实情况的最精准估值，因此估值同实际数值不符的情况就会减少。' },
  { k:'mtpe_0133', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Dr Saunois’s team published their first results in July 2020.', mt:'', ref:'2020年7月，索诺伊斯博士团队发布了他们的第一阶段研究成果。' },
  { k:'mtpe_0134', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'They found that between 550 million and 880 million tonnes of methane per year were emitted between 2008 and 2017—roughly 9% more than the average between 2000 and 2006.', mt:'', ref:'他们发现，2008年至2017年，每年的甲烷排放量在5.5亿到8.8亿吨之间，比2000年到2006年间的均值高出9%。' },
  { k:'mtpe_0135', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Between 50% and 60% of this came from human activities, depending on whether the bottom-up or top-down method was used.', mt:'', ref:'其中的50%-60%来自人类活动，区间的波动在于自下而上和自上而下两种研究方法的差别。' },
  { k:'mtpe_0136', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Of these, roughly speaking, fossil fuels and agriculture each account for a third, with the remainder coming from a combination of emissions from things like cars, fires, landfills and waste-water processing.', mt:'', ref:'在化石燃料和农业排放大约各占三分之一，剩余部分来自汽车、明火、垃圾堆场以及废水处理等环节的排放。' },
  { k:'mtpe_0137', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The post-2007 uptick in methane levels, the team found, was caused by extra human emissions, though there may also be some diminution in the atmosphere’s ability to destroy the gas.', mt:'', ref:'该团队发现，2007年后甲烷浓度的上升主要是由额外的人类排放所致，而大气分解甲烷的能力可能也有所减弱。' },
  { k:'mtpe_0138', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Thankfully, there was little sign of increased release of methane from Arctic tundra, which some fear may happen as the tundra warms.', mt:'', ref:'有人担心，北极苔原带变暖会释放出更多的甲烷，但幸运的是，目前还没有这个迹象。' },
  { k:'mtpe_0139', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Fossil-fuel emissions increased a lot in China over the decade that followed 2007, and to a lesser extent in other Asian countries, America, Africa and the Middle East.', mt:'', ref:'在2007年后的十年间，中国的化石燃料排放量大幅增加，其他亚洲国家、美洲、非洲以及中东地区也有增加，只是增幅较小。' },
  { k:'mtpe_0140', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'China, indeed, is the world’s largest methane emitter, an accolade it owes partly to its continued exploitation of coal.', mt:'', ref:'实际上，中国是世界上甲烷排放量最大的国家，该国持续不断地开采煤矿是部分原因。' },
  { k:'mtpe_0141', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'In spite of regulations brought in to encourage mine operators to use methane from their mines for such purposes as power generation, rather than venting it into the atmosphere, a study published in Nature, in 2019, found that the sector’s activities were still driving China’s methane emissions up.', mt:'', ref:'虽然中国出台了相关规定，鼓励煤矿经营者回收矿井中的甲烷发电，而不是直接将甲烷排放到大气中，但2019年发表在《自然》杂志的一项研究发现，煤炭产业的活动仍在推高中国的甲烷排放量。' },
  { k:'mtpe_0142', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Europe was the only region to achieve a drop in emissions, in part thanks to policies to reduce the amount of biodegradable waste that is sent to landfill.', mt:'', ref:'欧洲是唯一实现甲烷排放量下降的地区，部分得益于欧洲出台了减少送往垃圾堆场的可降解废弃物数量的政策。' },
  { k:'mtpe_0143', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The largest increases in agricultural emissions came from Asia, Africa and the Middle East—and agricultural sources, specifically livestock and rice paddies, are the most difficult of all to deal with.', mt:'', ref:'农业排放增幅最大的地区分别为亚洲、非洲和中东地区，农业排放源头是最难解决的，尤其是牲畜和稻田。' },
  { k:'mtpe_0144', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'In both cases, the gas is produced by methanogenic microbes that live, respectively, in the animals’ guts and decomposing excrement, and in oxygen-poor waterlogged soil.', mt:'', ref:'牲畜和稻田排放的甲烷气体都源自于产甲烷微生物，而在动物的内脏、腐烂的排泄物或缺氧的渍水土壤中都含有这种微生物。' },
  { k:'mtpe_0145', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Paddies account for 8% of man-made methane emissions.', mt:'', ref:'稻田甲烷排放占人为排放总量的8%。' },
  { k:'mtpe_0146', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Varieties of rice that yield more grain for the same amount of methane could help reduce this, but a technologically simpler approach would be to switch to irrigating paddies for less time, which comes with the added bonus of saving water too.', mt:'', ref:'种植甲烷排放量相同而产量更高的水稻品种，有助于降低这一占比，更简单易行的技术方法则是减少稻田的灌溉时间，这样还可以节约用水。' },
  { k:'mtpe_0147', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The lion’s share of agricultural methane, though, comes from ruminant livestock—cows and sheep, mainly.', mt:'', ref:'大部分的农业甲烷源自于反刍牲畜，主要是牛和羊。' },
  { k:'mtpe_0148', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Such husbandry generates 79% of the sector’s contribution.', mt:'', ref:'牲畜养殖业占农业甲烷排放量的79%，' },
  { k:'mtpe_0149', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'That amounts to 30% of all anthropogenic emissions.', mt:'', ref:'占人为排放总量的30%。' },
  { k:'mtpe_0150', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Asking people to eat less meat and drink less milk, while fashionable at the moment in rich countries, probably goes against the Bismarckian principle of realism in the wider, middle-income world where discretionary spending is rising and diets are improving.', mt:'', ref:'少吃肉、少喝奶，虽然在富裕国家已成为时尚潮流，但可支配支出持续增长、饮食条件不断改善的中等收入国家，这可能违背了俾斯麦式的现实主义原则。' },
  { k:'mtpe_0151', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'But another option is to attack the methanogens themselves.', mt:'', ref:'消灭产甲烷菌则是另外一个选择。' },
  { k:'mtpe_0152', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'This is now being investigated experimentally, to see if changing what the animals eat can damp down methanogenic activity.', mt:'', ref:'目前有实验研究正在求证是否可以通过改变动物饲料来抑制产甲烷菌的活性。' },
  { k:'mtpe_0153', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Though it is probably not a practical solution at scale, some studies suggest a diet rich in certain seaweeds can decrease an animal’s methane emissions by as much as 80%.', mt:'', ref:'这也许不是一种可以大规模适用的解决方案，但有研究表明，采用富含某些海藻的饲料可以将动物甲烷排放减少80%。' },
  { k:'mtpe_0154', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'A compound called bromoform, abundant in these algae, inhibits the chemical reactions that produce methane inside the animals’ rumens.', mt:'', ref:'这些藻类含有大量名为三溴甲烷的化合物，它会抑制动物瘤胃中产生甲烷的化学反应。' },
  { k:'mtpe_0155', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Unfortunately, cattle fed enough seaweed to experience the 80% cut produce less meat or milk than they otherwise would.', mt:'', ref:'很不幸的是，给牛喂食足够量的此类海藻，甲烷排量可下降80%，但产肉量、产奶量均有所下降。' },
  { k:'mtpe_0156', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'But another, more benign, dietary change does seem to help without side-effects.', mt:'', ref:'另一种更为良性的新饲喂方式似乎更胜一筹，而且没有副作用。' },
  { k:'mtpe_0157', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'This is to add vegetable oils to ruminants’ diets.', mt:'', ref:'就是在反刍动物的饲料中添加植物油。' },
  { k:'mtpe_0158', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'These are calorie-rich, but do not ferment in the rumen and therefore do not encourage methanogens.', mt:'', ref:'植物油富含卡路里，但不会在瘤胃中发酵，因此不会促进产甲烷菌的生长。' },
  { k:'mtpe_0159', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'This approach can cut emissions by 11-18%.', mt:'', ref:'这一方法可以减少11-18%的甲烷排放量。' },
  { k:'mtpe_0160', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'More radically, methanogen activity can be disrupted by adding synthetic chemicals to animals’ diets.', mt:'', ref:'此外，在动物饲料中添加合成化学物质可以破坏产甲烷菌的活性。' },
  { k:'mtpe_0161', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'One such is 3-nitrooxypropanol, which gums up an enzyme the bugs use to generate methane.', mt:'', ref:'上述合成化学物质之一是3-硝基氧基丙醇，它可以和菌群用以合成甲烷的酶相结合。' },
  { k:'mtpe_0162', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'DSM, a Dutch firm, has turned this into a product, now awaiting approval for use in Europe, which it claims can reduce the amount a cow emits by 27-40%.', mt:'', ref:'荷兰帝斯曼公司（DSM）已开发了3-硝基氧基丙醇产品，目前正在欧洲等待批准使用，该公司称可将奶牛的甲烷排放量减少27%-40%。' },
  { k:'mtpe_0163', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Just do it', mt:'', ref:'说做就做' },
  { k:'mtpe_0164', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'That methane emissions are a prime target for reduction is an idea which has caught on with politicians, at least in rich countries.', mt:'', ref:'减少甲烷排放是减排的主要目标之一，这已成政治家们的共识，至少在富裕国家是这样。' },
  { k:'mtpe_0165', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'In October, the European Commission adopted a “European methane strategy”, the implementation of which will be thrashed out this year.', mt:'', ref:'今年十月，欧盟委员会发布“欧洲甲烷战略”，具体实施办法将在年内出台。' },
  { k:'mtpe_0166', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The previous plan had been to cut the EU’s emissions in 2030 to a level 29% below those of 2005.', mt:'', ref:'此前，欧盟计划到2030年将甲烷排放量降至比2005年低29%的水准。' },
  { k:'mtpe_0167', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'That target has now been increased to 35-37%.', mt:'', ref:'新计划的减排目标提高到35%-37%。' },
  { k:'mtpe_0168', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'In 2020 Donald Trump, who was then the president, repealed regulations on monitoring and plugging methane leaks introduced by his predecessor, Barack Obama.', mt:'', ref:'2020年，时任美国总统唐纳德·特朗普（Donald Trump）废除了其前任巴拉克·奥巴马（Barack Obama）颁布的监测和堵塞甲烷泄漏的相关法规。' },
  { k:'mtpe_0169', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Mr Trump’s successor, Joe Biden, says he will reverse this reversal, but is also under pressure from environmental lobby groups to go further, by setting a target of reducing emissions by as much as 65% by 2025.', mt:'', ref:'特朗普先生的继任者乔·拜登（Joe Biden）表示，他将恢复该项已被撤销的法规，即便如此，环保团体仍然在不断向他施压，要求他更进一步，设定到2025年减排65%的目标。' },
  { k:'mtpe_0170', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Such lofty goals are worth little, though, if their consequences are not measured.', mt:'', ref:'但是，如果结果得不到衡量，设定远大的目标就毫无意义可言。' },
  { k:'mtpe_0171', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Fossil-fuel companies naturally gather their own data privately.', mt:'', ref:'化石燃料公司自然会收集各自的数据。' },
  { k:'mtpe_0172', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'And several environmental organisations hunt for leaks in pipelines and so on using instruments mounted on cars and planes.', mt:'', ref:'一些环境组织会利用安装在汽车或飞机上的设备，搜寻管道上的泄漏点。' },
  { k:'mtpe_0173', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Their goal is to shine a light on the issue, but their data are also frequently fed back to oil and gas operators, to help them patch up their pipelines.', mt:'', ref:'他们的目标是曝光问题，他们的数据通常也会反馈给油气运营商，帮助他们及时修补管道。' },
  { k:'mtpe_0174', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The Environmental Defence Fund says responses vary, but many firms are grateful for the additional feedback.', mt:'', ref:'美国环保协会（Environmental Defence Fund）表示，油气公司对此的反应不尽相同，但许多公司对这种反馈充满感激。' },
  { k:'mtpe_0175', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'The Oil and Gas Methane Partnership (OGMP), a UN-led project, standardises methods for measuring and reporting methane emissions in the fossil-fuel industry.', mt:'', ref:'由联合国主导的油气甲烷伙伴关系（OGMP）项目提供标准化的方法监测和报告化石燃料行业的甲烷排放情况。' },
  { k:'mtpe_0176', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'At the last count, it had recruited 66 companies which, collectively, produce 30% of the world’s oil and gas.', mt:'', ref:'最新数据显示，该项目已招募了66家油气企业，这些公司的石油和天然气产量总和占世界产量的30%。' },
  { k:'mtpe_0177', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'Data collected through the OGMP will be fed into a new International Methane Emissions Observatory being cooked up by the UN Environment Programme and the European Commission.', mt:'', ref:'油气甲烷伙伴关系项目收集的数据会提供给国际甲烷排放观测项目，该项目是联合国环境规划署同欧盟委员会共同策划成立的新机构。' },
  { k:'mtpe_0178', ed:'4', stage:'决赛', dir:'英译汉', eng:'火山翻译', src:'This will combine them with other measurements, including from the growing number of satellites that measure methane sources from above, to verify national and corporate accounting.', mt:'', ref:'该项目将联合其他监测手段，包括监测上文所述甲烷源头的日益增多的卫星，核实国家及公司的相关统计数据。' },
  { k:'mtpe_0001', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Work Imitates Life', mt:'', ref:'工作生活两不误' },
  { k:'mtpe_0002', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Few companies could announce a new office in the messianic way that Google did last February.', mt:'', ref:'很少有公司发布过像谷歌去年2月发布的那种雄心勃勃的新办公园区建设计划。' },
  { k:'mtpe_0003', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Then again, few companies have ever built this sort of office.', mt:'', ref:'同样，很少有公司建设过那样的办公园区。' },
  { k:'mtpe_0004', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'‘Google’s presence in Mountain View is simply so strong that it can’t be the fortress that shuts away… the neighbours. It really needs to become a neighbourhood in Mountain View,’ intones the lead architect Bjarke Ingels of the Danish firm Bjarke Ingels Group (BIG) in the introductory video.', mt:'', ref:'丹麦比亚克•英厄尔斯集团 (Bjarke Ingels Group) 的首席建筑师比亚克•英厄尔斯 (Bjarke Ingels) 在视频陈述中表示：“谷歌在山景城的范围实在太大，不可能成为隔绝外人的孤堡。谷歌想要在山景城打造一个社区。”' },
  { k:'mtpe_0005', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The camera sweeps high over an edenic Mountain View in the San Francisco Bay Area.', mt:'', ref:'高空摄像机扫过旧金山湾区伊甸园般的山景城。' },
  { k:'mtpe_0006', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'It pulls back to reveal Google’s proposed new office: a neighbourhood nested beneath glittering glass domes.', mt:'', ref:'然后，镜头切到谷歌即将兴建的新办公园区，那是一个坐落在金碧辉煌的玻璃穹顶之下的社区。' },
  { k:'mtpe_0007', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'On approximately 3.5 million square feet of commercial land, Google intended to build a campus office that might best be described as a new part of town.', mt:'', ref:'谷歌计划在一块大约350万平方英尺的商业用地上建造办公园区，与其说是办公园区，倒不如说是山景城的一个新城区。' },
  { k:'mtpe_0008', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Beneath the glass canopies, a thriving neighbourhood hosts stores, bike paths and modular office spaces.', mt:'', ref:'玻璃穹顶的下面是一个繁华的社区，有商店，有自行车道，还有模块化办公空间。' },
  { k:'mtpe_0009', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In building this new neighbourhood, Google hoped to expand their working space while accommodating the Mountain View population inclined to view them as a ‘fortress’.', mt:'', ref:'通过建设这个新社区，谷歌意在扩大工作空间，同时纳入一向将谷歌视为“孤堡”的山景城人。' },
  { k:'mtpe_0010', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The utopian campus was meant to assuage fears that spiking numbers of Google employees would create a Google voting bloc, according to The New York Times.', mt:'', ref:'据《纽约时报》分析，之所以建设这个乌托邦式的办公园区，是为了缓解人们的担忧，人们担心谷歌员工数量激增，最终会形成一个选票集团。' },
  { k:'mtpe_0011', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Such fears are understandable.', mt:'', ref:'这种担忧是可以理解的。' },
  { k:'mtpe_0012', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'As of 2013, the company employed roughly 10 per cent of Mountain View’s workforce and owned approximately the same proportion of taxable property.', mt:'', ref:'截至2013年，谷歌的员工占山景城职工总数的约10%，并拥有约同等比例的应税财产。' },
  { k:'mtpe_0013', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Despite promises that the campus would be open to all, in May 2015 the Mountain View City Council denied Google the majority of the land they’d requested.', mt:'', ref:'尽管谷歌承诺办公园区将对所有人开放，但在2015年5月，山景城议会拒绝了谷歌的大部分土地申请。' },
  { k:'mtpe_0014', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google submitted a similar but smaller plan to the city later that month.', mt:'', ref:'当月晚些时候，谷歌向山景城提交了一份类似但占地规模较小的新计划。' },
  { k:'mtpe_0015', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'This one proposes to treat its own water supply and expand the suite of amenities that, anecdotally, have enabled at least a few Google employees to forgo private housing – sometimes by sleeping in trucks and vans while otherwise living on campus.', mt:'', ref:'在新计划中，谷歌提出自行解决供水问题，并扩大配套设施，有了这些设施，某些谷歌员工就不需要私有住宅，有时可以住在园区里，有时甚至可以睡在卡车或货车里。' },
  { k:'mtpe_0016', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'It’s a life many want.', mt:'', ref:'这是许多人想要的生活。' },
  { k:'mtpe_0017', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google boasts more than 2 million job applicants a year.', mt:'', ref:'谷歌每年有200多万名求职者。' },
  { k:'mtpe_0018', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'National media hailed its office plans as a ‘glass utopia’.', mt:'', ref:'有美国媒体将这个园区开发计划称为“玻璃穹顶下的乌托邦”。' },
  { k:'mtpe_0019', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'There are hosts of articles for businesspeople on how to make their offices more like Google’s workplace.', mt:'', ref:'随后涌现了大量面向商界人士的文章，向他们讲述如何将办公场所打造得像谷歌一样。' },
  { k:'mtpe_0020', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'A 2015 CNN Money survey of business students around the world showed Google as their most desired employer.', mt:'', ref:'2015年，美国有线电视新闻网财经频道 (CNN Money)面向世界各地的商科学生做了一项调查，调查结果表明谷歌是商科学生最愿意效力的雇主。' },
  { k:'mtpe_0021', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Its campus is a cultural symbol of that desirability.', mt:'', ref:'谷歌的办公园区便是这种吸引力的文化象征。' },
  { k:'mtpe_0022', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The specifics of Google’s proposed Mountain View office are unprecedented, but the scope of the campus is part of an emerging trend across the tech world.', mt:'', ref:'谷歌的办公园区计划世所罕见，但建设大型园区已经成为整个科技界的一股新潮流。' },
  { k:'mtpe_0023', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Alongside Google’s neighbourhood is a recent Facebook open office on their campus that, as the largest open office in the world, parallels the platform’s massive online community.', mt:'', ref:'除了谷歌园区，脸书 (Facebook) 也在自己的园区新建了开放式办公空间，这是世界上面积最大的开放型办公空间，与其庞大的在线社区相匹配。' },
  { k:'mtpe_0024', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Both offices seem modest next to the ambitious and fraught effort of Tony Hsieh, CEO of the online fashion retailer Zappos, to revitalise the downtown Las Vegas area around Zappos’ office in the old City Hall.', mt:'', ref:'在线时尚零售商美捷步 (Zappos) 首席执行官谢家华也发布了一项雄心勃勃的计划，旨在重建美捷步拉斯维加斯办公楼附近的老城区，与此相比，谷歌和脸书的园区开发计划就相形见绌了。' },
  { k:'mtpe_0025', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Such offices symbolise not just the future of work in the public mind, but also a new, utopian age with aspirations beyond the workplace.', mt:'', ref:'这些办公园区计划不仅代表公众对于未来工作的期待，也象征着一个乌托邦式的新时代的来临，工作场所不仅仅是工作的场所。' },
  { k:'mtpe_0026', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The dream is a place at once comfortable and entrepreneurial, where personal growth aligns with profit growth, and where work looks like play.', mt:'', ref:'人们畅想，办公场所应是一个既舒服又有利于开创事业的地方，在这里，个人成长与企业盈利增长目标相一致，工作轻松愉快。' },
  { k:'mtpe_0027', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Yet though these tech campuses seem unprecedented, they echo movements of the past.', mt:'', ref:'不过，这样的科技园区看似前所未有，但并非没有先例。' },
  { k:'mtpe_0028', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In an era of civic wariness and economic fragility, the ‘total’ office heralds the rise of a new technocracy.', mt:'', ref:'在一个全民紧张、经济脆弱的时代，“整体式”的办公园区预示着技术力量的重新崛起。' },
  { k:'mtpe_0029', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In a time when terrorism from abroad provokes our fears, this heavily-planned workplace harks back to the isolationist values of the academic campus and even the social planning of the company town.', mt:'', ref:'在这个来自国外的恐怖主义引发国内恐慌的年代，精心打造的工作场所难免会让人联想到孤立主义的价值观，这种价值观不仅存在于大学校园里，还体现在建设“公司城”的社会规划之中。' },
  { k:'mtpe_0030', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'As physical offices, they’re exceptional places to work – but while we increasingly uphold these places as utopic models for community, we make questionable assumptions about the best version of our shared life and values.', mt:'', ref:'作为实体办公场所，企业社区确实无可挑剔，是卓越的工作空间，但是，如果我们逐渐将这些场所视为社区的乌托邦模板，我们对于共享生活和价值观的假想就值得商榷了。' },
  { k:'mtpe_0031', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Just as Google sought to build a new neighbourhood in Mountain View, so did Thomas Jefferson in 1819 intend to make the campus of the University of Virginia an ‘academical village’.', mt:'', ref:'和谷歌计划在山景城建设新办公园区一样，1819年，托马斯•杰斐逊 (Thomas Jefferson) 也曾打算将弗吉尼亚大学的校园打造成为一个“学术村”。' },
  { k:'mtpe_0032', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The famed architect Le Corbusier once described the US college campus as ‘a world in itself’, and it’s these cloistered worlds that launched our technological ideals.', mt:'', ref:'著名建筑师勒•柯布西耶 (Le Corbusier) 曾将美国大学校园描述为“一个独立的世界”，正是这些与世隔绝的世界触发了美国的科技梦。' },
  { k:'mtpe_0033', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Tony Hsieh of Zappos had a formative business experience manning a dormitory diner in Quincy House at Harvard College; David Fincher’s film The Social Network (2010) would have you believe that Mark Zuckerberg’s empire – which earned $12.47 billion in 2014 alone – is still, at its core, a vengeful dorm-room enterprise.', mt:'', ref:'美捷步的CEO谢家华在哈佛学院昆西之家 (Quincy House) 管理宿舍餐厅时的经历奠定他商业传奇的基础，大卫•芬奇 (David Fincher) 的电影《社交网络》(The Social Network, 2010) 会让你相信马克•扎克伯格 (Mark Zuckerberg) 的商业帝国（仅在2014年就赚了124.7亿美元）本质上还是一个小心眼的宿舍企业。' },
  { k:'mtpe_0034', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Tech campuses and college campuses seem ideologically aligned.', mt:'', ref:'在意识形态上，科技企业园区和大学校园似乎是一致的。' },
  { k:'mtpe_0035', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Once, those college campuses held as much sway in the US mind as our tech campuses do now.', mt:'', ref:'在美国人心目中的影响力，过去的大学校园和当今的科技园区相差无几。' },
  { k:'mtpe_0036', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'According to the architectural historian Paul V Turner’s Campus: An American Planning Tradition (1984), the US college campus was ‘an experiment in urbanism’ – a more open follow-up to European universities such as Oxford, whose individual residential colleges emerged in the 13th century and came to prominence in the 15th as a means of organising the college experience, keeping out the townies, and controlling students prone to whoring.', mt:'', ref:'建筑历史学家保罗•V•特纳 (Paul V Turner) 在《校园：美国规划传统》(Campus: An American Planning Tradition, 1984) 一书中指出，美国大学校园是“城市主义的试验田”，因循了牛津等欧洲大学的先例，只不过是更加开放。牛津大学的独立寄宿学院出现于13世纪，并在15世纪声名鹊起，成为了组织校园体验、隔绝闲杂人员和管控学生嫖娼的一种手段。' },
  { k:'mtpe_0037', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'These urban experiments became a vision of US utopia.', mt:'', ref:'后来，这些城市主义的试验成了美国对于乌托邦的愿景。' },
  { k:'mtpe_0038', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Campuses are worlds apart; places that address the whole of the student in order to nurture the whole of the student.', mt:'', ref:'校园是独立的世界，注重学生全面发展，培养学生的整体素质。' },
  { k:'mtpe_0039', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Early college campuses were one of the first major architectural undertakings of the new world, and they mapped US values and aspirations.', mt:'', ref:'早期的大学校园是新世界的首批重大建筑工程，反映了美国的价值观和抱负。' },
  { k:'mtpe_0040', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'They were the first of our cities on a hill.', mt:'', ref:'它们是美国的首批“山上之城”。' },
  { k:'mtpe_0041', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'These offices are seen as utopian partly because ‘they’re more thought-out than most American offices,’ explained Saval.', mt:'', ref:'萨瓦尔 (Saval) 解释说，这些办公园区之所以被称为乌托邦，部分原因在于“与大多数美国办公场所相比，它们的开发计划更加深思熟虑。' },
  { k:'mtpe_0042', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'‘The reason they’re more thought-out is that those companies are in some ways obliged to care in a way that other American corporations in other industries aren’t.’', mt:'', ref:'之所以要深思熟虑，是因为这些公司希望表明他们对员工的关心高于其他行业的其他公司。”' },
  { k:'mtpe_0043', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'That’s because workers with tech skills are in demand.', mt:'', ref:'这是因为技术人才很抢手。' },
  { k:'mtpe_0044', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'As members of a leading cultural and economic paradigm, they have a kind of economic security that those in many other fields now lack.', mt:'', ref:'作为先进文化和自由经济范式的代表，他们具备其他领域的人所不具备的经济安全感。' },
  { k:'mtpe_0045', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Their offices, then, cater to their needs in a rare way.', mt:'', ref:'因此，他们的办公场所必须别具一格，才能满足他们的需求。' },
  { k:'mtpe_0046', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'As the architectural critic Alexandra Lange points out in The Dot-Com City (2012), these places keep the surrounding world at bay – often at a cost to the local economy – to keep employees on campus longer.', mt:'', ref:'建筑评论家亚历山德拉•兰格 (Alexandra Lange) 在《网络城市》(The Dot-Com City, 2012)一书中指出，这些场所与周围的世界格格不入，这样才能延长员工待在园区的时间，但通常是以牺牲当地经济为代价的。' },
  { k:'mtpe_0047', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Ultimately, school campuses seek to shape rounded and informed citizens.', mt:'', ref:'归根结底，大学校园旨在塑造全面发展、学识渊博的公民，' },
  { k:'mtpe_0048', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'On corporate campuses, workers are still workers.', mt:'', ref:'而在企业园区里，员工终究还是员工。' },
  { k:'mtpe_0049', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'But in both environments, people are encouraged to bring their whole selves to their work.', mt:'', ref:'但是，无论是哪种环境，都鼓励人们全身心投入。' },
  { k:'mtpe_0050', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'So the campus culture that seeks to serve, shape and employ the whole worker has as its corollary a boom in positive psychology – management principles centred on things such as mindfulness, perceived autonomy, and the feeling of being part of something bigger than yourself.', mt:'', ref:'因此，要打造一种园区文化，积极服务、塑造、雇佣全面发展的员工，就必然用到积极心理学，即注重培养员工的正念、自主感和使命感。' },
  { k:'mtpe_0051', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The insight gelled with the burgeoning new field of positive psychology, which, Hsieh felt, confirmed ‘that the combination of physical synchrony with other humans… leads to a greater sense of happiness.’', mt:'', ref:'谢家华认为，这种管理原则与积极心理学这个蓬勃发展的新领域相契合，证明“保持与他人行动的一致性，能够带来更大的幸福感。”' },
  { k:'mtpe_0052', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In his book, he sketched out his vision for ‘a path to profits, passion, and purpose. ’', mt:'', ref:'在自己的书中，他勾勒出了“通往利润、热爱和目标的道路”。' },
  { k:'mtpe_0053', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Soon he had spun off a happiness consultancy called Delivering Happiness, which offered coaching and talks delivered by VHPs (Very Happy Persons) along with a Happy Business Index survey to help companies optimise workforce happiness.', mt:'', ref:'很快，他创立了一家名为“传递幸福”的幸福咨询公司，由“非常幸福的人”来做辅导和演讲，同时开展了一项幸福企业指数调查，帮助企业增强员工的幸福感。' },
  { k:'mtpe_0054', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'That’s been the mission at Zappos, too, through core values such as ‘Deliver WOW Through Service’ and ‘Create Fun and a Little Weirdness’.', mt:'', ref:'这也正是美捷步的使命，而践行使命的途径是推行“用服务给客户带来惊喜”和“创造乐趣和一点意外”等核心价值观。' },
  { k:'mtpe_0055', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'And on a 60-acre patch of land in downtown Las Vegas, not far from the Strip over in Paradise, Nevada, it’s become the guiding vision of a new sort of town – an alchemical effort to revitalise Vegas’ downtrodden downtown by making it a start-up utopia.', mt:'', ref:'位于拉斯维加斯市中心、距内华达州天堂城赌城大道不远的一片60英亩的土地，已经成为建设新型城镇的范例，通过打造初创企业的乌托邦，振兴拉斯维加斯没落的老城区。' },
  { k:'mtpe_0056', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The Downtown Project is a sandbox for start-ups, an umbrella organisation that funds, supports, owns and co-owns around 300 businesses that, according to their website, together employ more than 900 people.', mt:'', ref:'这个老城振兴项目是一个初创企业孵化项目，也是一家伞式组织，该组织控有或持有大约300家初创企业的股份，为这些初创企业提供资金和支持。这些企业的网站资料显示，它们总共有900多名员工。' },
  { k:'mtpe_0057', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Though not technically constituting the Zappos campus, the Zappos company sits at the heart of things in the old City Hall.', mt:'', ref:'从严格意义上讲，这个项目并不等同于美捷步的企业园区，但公司正好是位于城市的老城区，市政厅所在地。' },
  { k:'mtpe_0058', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'At the Downtown Project, according to a special report by Nellie Bowles for the website Re/code, a preschool trains children in the skills they need for the start-up of life.', mt:'', ref:'而根据内莉•鲍尔斯 (Nellie Bowles) 为Re/code网站撰写的一份特别报告，这个老城振兴项目就像学前班教会孩子们基本生活技能一样帮助初创企业成长。' },
  { k:'mtpe_0059', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'A Downtown Project-funded hospitality-cum-security force called ‘The Rangers’ aims someday to monitor interactions between workers in a search for the coveted innovation-producing encounter.', mt:'', ref:'项目资助了一个名为“游侠”的酒店安保团队，团队的目标是能够不定时监控员工之间的互动，寻找可遇不可求的创新机会。' },
  { k:'mtpe_0060', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'According to Joe Schoenmann of the Las Vegas Weekly, they play ukuleles and hope to create a ‘smile pandemic’ in the city.', mt:'', ref:'《拉斯维加斯周刊》(Las Vegas Weekly) 的乔•舍曼 (Joe Schoenmann) 称，他们通过演奏尤克里里，希望在这座城市制造一场“微笑大流行”。' },
  { k:'mtpe_0061', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Yet for all the positivity of the Downtown Project, its surrounding casinos have become an unfortunately fitting landscape.', mt:'', ref:'然而，尽管该项目有诸多积极的方面，但周围赌场林立，多少显得有些不协调。' },
  { k:'mtpe_0062', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The Project’s combination of high-stress entrepreneurship, a surface emphasis on positivity, and the isolation attendant in an office away from some employees’ homes was a gamble, and the house has often seemed set against them.', mt:'', ref:'而且，面临巨大的创业压力，强调积极乐观却浮于表面，有些员工需要孤身离家前往工作……这一切都使得这一项目宛如一场赌博，而且“庄家”似乎总是跟他们作对。' },
  { k:'mtpe_0063', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Since 2013, the Project has seen major layoffs, a series of suicides, and the loss of faith among many, serving as a cautionary tale.', mt:'', ref:'自2013年以来，该项目出现了大规模的裁员和一系列自杀事件，许多人失去了信心，这些都是对项目发出的警示。' },
  { k:'mtpe_0064', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Hsieh’s impulse has historical precedent.', mt:'', ref:'但是，谢家华并非第一次这样冲动。' },
  { k:'mtpe_0065', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In the past, company towns realised a life in line not only with profits but also with certain value systems, and a model of corporate control.', mt:'', ref:'过去，公司城的建设不仅是为了追求利润，还要契合某些价值体系和企业控制模式。' },
  { k:'mtpe_0066', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In the early to mid-19th century at the Lowell Mills in Massachusetts, you could both enjoy a refined intellectual community and be fired for drinking or attending dance classes, notes Hardy Green, a former BusinessWeek associate editor, in his book The Company Town (2010).', mt:'', ref:'《商业周刊》(Business Week) 的前副主编哈迪•格林 (Hardy Green) 在他的《公司城》(The Company Town, 2010) 一书中指出，在19世纪早期至中期马萨诸塞州洛威尔的工厂里，你既可以和高雅的知识分子为伍，也可能因为喝酒或参加舞蹈课而遭到解雇。' },
  { k:'mtpe_0067', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Later on, towns such as Hershey, Pennsylvania, built by the chocolate maven Milton S Hershey, combined some of the best living amenities of the early 20th century – a school for orphans, electricity, a free zoo – with the precarious lack of elected government and the chance to have Hershey himself as your mayor.', mt:'', ref:'后来，有一些城镇，比如巧克力专家米尔顿•S•赫尔希(Milton S Hershey) 建造的宾夕法尼亚州好时镇，配备了20世纪初最好的一些生活设施，包括孤儿学校、电力设施、免费动物园等，但好时镇缺少民选政府，这给了赫尔希本人担任镇长的机会。' },
  { k:'mtpe_0068', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Like other such towns, Hershey had a ‘moral police’ that would enforce clean living by noting homes that weren’t kept up and employees who were alcoholic.', mt:'', ref:'跟其他公司城一样，好时镇有“道德警察”，时刻留意各家各户的保洁情况以及是否有员工酗酒，强制推行清洁生活。' },
  { k:'mtpe_0069', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The risk of the company town, of course, is the dependence of a neighbourhood on the originating corporation – one reason that Mountain View rejected Google’s proposal.', mt:'', ref:'当然，公司城的风险在于，它会造成整个社区对创始公司的依赖，这正是山景城拒绝谷歌办公园区开发的一个原因。' },
  { k:'mtpe_0070', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In part, the company town was an attempt to remake the world in the industrialist’s image, and often stemmed from a separatist urge.', mt:'', ref:'在某种程度上，公司城是在按照实业家的形象重塑世界，而这往往源于分离主义思想。' },
  { k:'mtpe_0071', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'No one embodied the dynamics of those places better than Henry Ford, the poster child of US technology and entrepreneurship.', mt:'', ref:'没有谁比美国科技和企业家精神的代表人物亨利•福特 (Henry Ford) 更了解公司城的发展历程了。' },
  { k:'mtpe_0072', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Ford might have made the modern world with the Model T, but he made many smaller worlds with his model towns.', mt:'', ref:'如果说福特是用T型车开启了现代世界，那么，他建造的那些模范公司城相当于开辟了许多小世界。' },
  { k:'mtpe_0073', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In the 1920s, according to the historian Greg Grandin, Ford even proposed a ribbon-shaped city in Muscle Shoals, Alabama, that would be five and a half times as long as Manhattan.', mt:'', ref:'根据历史学家格雷格•格兰丁 (Greg Grandin) 的说法，在1920年代，福特甚至提议在阿拉巴马州的马斯尔肖尔斯市 ( Muscle Shoals) 建造一座带状城市，长度是曼哈顿的5.5倍。' },
  { k:'mtpe_0074', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'There, he sought to build a culture of ‘farmer-mechanics’ – industrial workers who spent their summers tending the land – which Ford, a farmboy-turned-mechanic, saw as the industrial future of the US.', mt:'', ref:'他想在那里建立一种“机械师兼农民”的文化，到了夏季，产业工人要去打理土地。由于福特的出身是一名农家男孩，后来才成长为机械师，因此，他把这种文化视为美国工业的未来。' },
  { k:'mtpe_0075', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'It wasn’t until years later and miles away that he’d succeed at scale.', mt:'', ref:'直到多年后，他才在千里之外获得成功。' },
  { k:'mtpe_0076', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In 1927, on a roughly 2.5 million-acre land grant from the state of Pará in Brazil, Ford began to build a rubber plantation.', mt:'', ref:'1927年，福特在巴西的帕拉州 (Parrá, Brazil) 获批一块大约250万英亩的土地，开始建造一座橡胶种植园。' },
  { k:'mtpe_0077', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'It was a new city on the fresh breast of the verdant Amazon: Fordlandia.', mt:'', ref:'这就是后来的福特兰迪亚镇 (Fordlandia)，位于绿树掩映下的亚马逊河畔。' },
  { k:'mtpe_0078', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Throughout his detailed 2009 account of Fordlandia’s halting rise from overrun jungle to town with a Main Street, bakery and perfume store, Grandin highlights how the economic and organisational obstacles of the project turned it into less a business proposition than an ideological battle ground for Ford’s vision of US life versus the primal jungle.', mt:'', ref:'在2009年出版的书中，格兰丁 (Grandin)详细讲述了福特兰迪亚镇如何从一片荒芜的丛林一步一步发展成为拥有一条主街、面包店和香水店的小镇，他一直在强调，福特兰迪亚镇项目所遭遇的经济和组织障碍，让它超越了商业项目的范畴，成为了福特的美国生活愿景与原始丛林进行意识形态较量的战场。' },
  { k:'mtpe_0079', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In 1941, Walt Disney visited Ford’s city, and in 1955, aged 53, he started Disneyland.', mt:'', ref:'1941年，沃尔特•迪斯尼 (Walt Disney) 访问福特兰迪亚镇。1955年，53岁的他创办了迪斯尼乐园。' },
  { k:'mtpe_0080', ed:'4', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'A half-century after that, Disney designers visited Facebook to consult on the company’s campus design, the new world begetting a small world, after all.', mt:'', ref:'半个世纪后，迪斯尼的设计师造访脸书公司，为脸书园区设计提供咨询，毕竟那是孕育小世界的新世界。' },
  { k:'seg_5_决赛_1', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'静安寺弄堂走走游', mt:'', ref:'Strolling through the Longtang of Jing’an' },
  { k:'seg_5_决赛_2', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'说起上海的市井生活，就不能不提上海的弄堂。', mt:'', ref:'One uniquely Shanghainese cultural element is the longtang, or the straight lanes between buildings in a residential quarter.' },
  { k:'seg_5_决赛_3', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'从建筑学上说，它本身就是上海中西文化交汇运动的产物，连北京的著名建筑家梁思成先生都称赞上海老弄堂是最优越于其他城市的地方性建筑。', mt:'', ref:'As a cultural fusion of east and west, it is crowned by Liang Sicheng, the “Father of Modern Chinese Architecture”, as the best of architecture in all of China.' },
  { k:'seg_5_决赛_4', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'同时，作为上海人主要的生活空间，小弄堂也成为大上海的缩影。', mt:'', ref:'The Shanghainese used to spend most of their time here. The small alley has also become the epitome of Greater Shanghai.' },
  { k:'seg_5_决赛_5', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'解放初期，弄堂式建筑约占上海居住建筑总面积的65%，占人口70%多的上海人居住于此，上海的习俗、方言、气质和都市性格的形成都与之息息相关。', mt:'', ref:'In the late 1940s, longtang style houses represented about 65% of Shanghai’s total residences, accommodating more than 70% of the local population. Their tiny living space almost epitomizes everything Shanghainese - traditions, dialects, qualities, and urban cultures.' },
  { k:'seg_5_决赛_6', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'通过弄堂这个横切面来了解上海，了解上海的历史和上海人，无疑是一个有趣且很好的角度。', mt:'', ref:'Therefore, it is fair to say whatever’s left of them today offers a glimpse into the history of Shanghai as well as the characteristics of the Shanghainese.' },
  { k:'seg_5_决赛_7', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'静安区的静安寺街道不仅保存着上海仅有的较大规模的成片弄堂，而且这里的邨、坊、里、弄历史风貌保护区很好地保留了原生态的生活气息，海派韵味悠远，是老上海风情难得的历史遗存。', mt:'', ref:'Today, the only well-preserved large-scale longtang cluster is located in Jing’an. In this place, you may find lane, alley or village level protection area that best reflects the original life style of Shanghai. It is a rare historical relic of old Shanghai style.' },
  { k:'seg_5_决赛_8', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'据悉，静安区将在静安寺周边打造10条老上海风情弄堂，与上海市文联联手，推出特色弄堂游，静安区旅游节还将推出“弄堂风情游”特色项目。', mt:'', ref:'The district government plans to build 10 Shanghai-style Longtang around Jing’an Temple and to create “Special Longtang Tourism” in cooperation with the Shanghai Federation of literary and Art Circles. The Jing\'an District Tourism Festival will also launch a special project of "Longtang Style Tour".' },
  { k:'seg_5_决赛_9', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'笔者选取了周边两条有故事的特色老弄堂做一番介绍，让大家先睹为快。', mt:'', ref:'What I\'m about to tell you is the stories of two most exciting Longtang sites, just for a sneak peek.' },
  { k:'seg_5_决赛_10', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'文化名人的摇篮——愚园路361弄（愚谷邨）', mt:'', ref:'A Magnet for Scholars and Artists: Longtang 361, Yuyuan Road (Yugucun)' },
  { k:'seg_5_决赛_11', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'清光绪十六年（1890年），在千年古刹静安寺的东北，四明张氏在今愚园路常德路创建了私人花园——愚园。', mt:'', ref:'In the sixteenth year of Guangxu in the Qing Dynasty (1890), in the northeast of Jing\'an Temple, the Zhang family from Siming (Ningbo) built a private garden called Yuyuan near the intersection of Changde Road and Yuyuan Road.' },
  { k:'seg_5_决赛_12', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'1899年，愚园路由此得名。', mt:'', ref:'And in 1899, Yuyuan Road was officially named after this garden.' },
  { k:'seg_5_决赛_13', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'1934年，由广东潮阳人陈楚南先生投资开发，华信建筑设计师事务所杨润玉、杨元麟采用中西合璧的设计构思，在这里建起了煤卫齐全的新式里弄，名曰愚谷邨。', mt:'', ref:'In 1934, an investor from Chaoyang, Guangdong called Chen Chunan commissioned two architects, Yang Runyu and Yang Yuanlin, of Huaxin Architectural Design Studio to build a neighborhood here. Combining Chinese and Western style, it is a modern neighborhood equipped with proper gas supply and sanitation, and is called "愚谷邨" (Yugucun).' },
  { k:'seg_5_决赛_14', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'“邨”是“村”的异体字，含有城市里的乡村之意，也有乡村城市化的寓意。', mt:'', ref:'In Chinese characters, "邨"(cun) is a variant of "村", which contains both the meaning of "countryside in the city" and "rural urbanization".' },
  { k:'seg_5_决赛_15', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'“愚谷”二字出自中华优秀传统文化，即“大智若愚”（北宋·苏轼）和“虚怀若谷”（战国·《老子》），意指聪明人表面上好像愚笨，而大度的胸怀谦虚得像山谷一样能容纳百川。', mt:'', ref:'The word "愚谷"(Yugu) comes from the Chinese classics, namely "Great wisdom is like foolishness" (by Su Shi in the Northern Song Dynasty) and "Receptive as an echoing canyon" (by Lao Tzu in the Warring States Period), which indicates that although educated individuals initially appear to be foolish, their generous minds are so modest that they can accept a hundred rivers like a valley.' },
  { k:'seg_5_决赛_16', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'愚谷邨小区位于静安寺、百乐门西面，在愚园路，乌鲁木齐北路，南京路西端，永源浜路和镇宁路的区域内。', mt:'', ref:'Yugucun is located to the west of Jing\'an Temple and Paramount Gate, to the west of Yuyuan Road, North Urumqi Road and Nanjing Road, and within the intersected area of Yongyuanbang Road and Zhenning Road.' },
  { k:'seg_5_决赛_17', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'自东向西依次有愚谷邨、涌泉坊、十样景、牛奶棚，愚园坊、中实新村以及蝶村，其间镶嵌着不少花园洋房别墅。', mt:'', ref:'Several neighborhoods like Yugucun, Yongquanfang, Shiyangjing, Niunaipeng, Yuyuanfang, Zhongshixincun and Diecun, gather here from east to west. There are many garden villas inside these neighborhoods.' },
  { k:'seg_5_决赛_18', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'愚谷邨饱经沧桑，沉淀着上海历史文化的风貌， 1994年被上海市政府列为优秀历史建筑。', mt:'', ref:'The history of Yugucun is so long that it witnesses the development of this city. In 1994, Yugucun was designated by the Shanghai Municipal Government as a heritage site.' },
  { k:'seg_5_决赛_19', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'在愚谷邨曾居住过许多文化名人，65号先后住过的著名作家就有魏金枝、唐克新、茹志鹃和王啸平夫妇及王安忆；37号曾住过海派著名画家应野平；二十年代影星黎明晖夫妇、著名电影表演艺术家沙莉和凌之浩夫妇、奚美娟、著名口琴演奏家王庆隆也曾在这里居住过。', mt:'', ref:'Many renowned Chinese scholars and artists chose to make their home in Yugucun, including writers Wei Jinzhi, Tang Kexin, Ru Zhijuan, Wang Xiaoping, and Wang Anyi (in Building No. 65); the famous Shanghai-style painter Ying Yeping(in Building No. 37); and movie stars of the 1920s Li Minghui and her husband, famous film artists Sha Li and Ling Zhihao, Xi Meijuan, and famous harmonica player Wang Qinglong also lived here.' },
  { k:'seg_5_决赛_20', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'还有中国最早的两栖明星周璇，1936年与严华结合之初就定居于此。', mt:'', ref:'There is also Zhou Xuan, China\'s earliest movie and singing star, who settled here at the beginning of her marriage with Yan Hua in 1936.' },
  { k:'seg_5_决赛_21', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'沙莉夫妇曾住在121号，她住二楼亭子间。', mt:'', ref:'Sha Li and her husband used to live at No. 121, and she lived in the tingzijian, a small room on the second floor under the roof- deck.' },
  { k:'seg_5_决赛_22', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'在121号有一段足以拍成电视剧的故事，当时一、二楼正房间曾是上海地下党的一个秘密机关，对外以进化药厂做掩护。', mt:'', ref:'Some of the residents even left legendary stories, like the one in Building No. 121. The bedroom on the first and second floors was once a secret agency of the Shanghai Underground Party, and the Evolution Pharmaceutical Factory was used as a cover.' },
  { k:'seg_5_决赛_23', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'而令人想不到的是，住在三楼的竟是当时的76号特务，姓陈（解放后被枪毙），敌对阵营同住在这里，居然相安无事，可称奇景。', mt:'', ref:'Surprisingly, the person who lived on the third floor was actually Kuomingtang\'s Agent 76, surnamed Chen (who was shot after China\'s liberation). Two enemies lived here together, and they were at peace with each other, it was truly a spectacle.' },
  { k:'seg_5_决赛_24', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'称为胡同的弄堂——华山路229-285弄（大胜胡同）', mt:'', ref:'A Longtang Called Hutong: Longtang 229-285, Huashan Road (Da-sheng Hutong)' },
  { k:'seg_5_决赛_25', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'在上海近万条弄堂中，鲜有被称之为“胡同”的，而华山路上却有一组，它位于华山路229—285弄，名为大胜胡同。', mt:'', ref:'There are thousands of Longtangs in Shanghai, few are called "Hutong", a designation for Beijing’s traditional houses. However, there is one unique Longtang on Huashan Road called "Hutong", which is located in Lane 229-285 of Huashan Road. Their full name is Da-sheng Hutong.' },
  { k:'seg_5_决赛_26', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'大胜胡同原是天主教会的普爱堂投资经营的产业之一，普爱堂看中了这块邻近静安寺的地方，遂投资，由神父德拉蒙德负责建造了这组规模较大的新式里弄。', mt:'', ref:'Da-sheng Hutong was originally one of the real estates invested and operated by the Catholic Church\'s Pu\'ai Church. The Church chose this place adjacent to Jing\'an Temple and bought it. It was designed as a large modern Longtang by Drummond.' },
  { k:'seg_5_决赛_27', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'神父德拉蒙德来自北京，故他将正在建造的民居称之为胡同。', mt:'', ref:'The name was given by its builder Drummond, a priest who had lived in Beijing.' },
  { k:'seg_5_决赛_28', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'大胜胡同建于1912年至1936年间，占地52.47亩，建筑面积共22706平方米，为新式里弄住宅，有三层砖木结构房屋116幢，呈行列式排列，另有汽车间21间集中设置，建筑呈现装饰艺术派风格，水泥拉毛外墙，清水红砖饰边。', mt:'', ref:'Da-sheng Hutong began construction in 1912 and finished in 1936, covering an area of 52.47 mu with a construction area of 22,706 square meters. It comprises 116 three-storey brick-and- wood buildings arranged in rows and 21 private garages. The building presents an Art Deco style, with cement brushed exterior walls and red brick trim.' },
  { k:'seg_5_决赛_29', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'整个胡同的建筑风格与北京胡同的四合院风格截然不同，它的结构属于法式新式里弄住宅，造型别致，装饰细腻，建筑风格既受到中国传统建筑影响，又糅合了西方巴洛克建筑风格。', mt:'', ref:'The architectural style is part French and part Chinese with a hint of Baroque influences. All houses come with delicate decorations, making them distinct from Beijing’s Hutong. The architectural style is not only influenced by traditional Chinese architecture, but also combined with Western Baroque architectural style.' },
  { k:'seg_5_决赛_30', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'而大胜胡同263弄6号上海市农场管理局使用的一幢办公楼，原是胡同建设者神父德拉蒙德的私人住宅。', mt:'', ref:'Today, in Da-sheng Hutong, the No. 6 Building, Lane 263 is used by the Shanghai Farm Administration as an office building. It was originally the private residence of Mr. Drummond.' },
  { k:'seg_5_决赛_31', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'这是一幢英国古典式花园住宅，建于1930年，假三层楼，造型别致，装饰细腻，宅前有大花园。', mt:'', ref:'This is a quasi three-story, British classical garden house, built in 1930, with a unique shape and delicate decorations. There is a large garden in front of the house.' },
  { k:'seg_5_决赛_32', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'建筑为双坡复式折线型屋顶，上覆红色平瓦。', mt:'', ref:'The rooftop has a double-pitch duplex folded design covered with red flat tiles.' },
  { k:'seg_5_决赛_33', ed:'5', stage:'决赛', dir:'汉译英', eng:'火山翻译', src:'这位神父是一位迷恋中国传统文化的人，他不但把中国传统装饰的重要构件融入住宅的室内装饰之中，而且花园的造型也颇有中国园林的神韵。', mt:'', ref:'Drummond was passionate about traditional Chinese culture. Not only did he integrate the core components of traditional Chinese decoration into the interior design of the house, but it was also infused with the concept and the charm of Chinese gardens.' },
  { k:'seg_5_东部_1', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“There Are No Pianos to Be Had Here”', mt:'', ref:'“岛上无琴”' },
  { k:'seg_5_东部_2', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'It was an odd time to visit Majorca.', mt:'', ref:'此时造访马略卡岛，正值多事之秋。' },
  { k:'seg_5_东部_3', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Civil war had flashed throughout Spain since the death five years earlier of King Ferdinand VII, which ignited familial disagreement over whether his successor would be his brother, Carlos, or his infant daughter, Isabella, whose interests were looked after by her mother, Maria Christina, Ferdinand’s widow and regent of Spain.', mt:'', ref:'五年前，国王费尔南多七世去世，谁来继承大统，让王族陷入分歧，是他的弟弟卡洛斯？还是年幼的女儿伊莎贝拉？站在伊莎贝拉背后的，是她的母亲玛丽亚·克里斯蒂娜——国王的遗孀、西班牙的摄政王后。很快，内战在西班牙各地爆发。' },
  { k:'seg_5_东部_4', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Refugees and émigrés descended on the island seeking sanctuary, finding instead Carlists and Christinos as partisan there as they were on the mainland.', mt:'', ref:'登岛的难民和迁徙来此的移民都是逃避战祸的，但他们来了才发现，岛上的人们和本土一样，两派对立，有支持卡洛斯的，有支持克里斯蒂娜的。' },
  { k:'seg_5_东部_5', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The commander-in-chief issued a dramatic order just three days before Frédéric Chopin and George Sand’s arrival:', mt:'', ref:'就在肖邦和乔治·桑抵岛前三天，总司令突然颁布一项紧急命令：' },
  { k:'seg_5_东部_6', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The district of the island of Majorca is declared to be in a state of war.', mt:'', ref:'马略卡岛地区被宣布为战争状态。' },
  { k:'seg_5_东部_7', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Henceforth everybody will be subject to military authority, without prejudice to other constituted authorities who will continue in the legal exercise of their respective functions, albeit with the obligations of obeying and complying with whatever may be required of them in the interest of public security.', mt:'', ref:'即日起，任何人都将受军事当局的管辖，其他非军事部门不能例外，这些部门在履行义务服从和遵守出于公共安全考虑而可能对他们提出的任何要求的条件下，将继续合法行使各自的职能。' },
  { k:'seg_5_东部_8', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In Palma they took the only habitable accommodation available, semi- furnished rooms in a former military barracks on Calle de la Marina, close to the old Arab Quarter.', mt:'', ref:'在帕尔马，他们找到了唯一可住的空房，这套空房做过基础装修，位于靠近旧阿拉伯区的海军大街的一个先前用作军营的地方。' },
  { k:'seg_5_东部_9', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'A modern plaque—high up on the stone, its names and dates in perfect order—verifies the street’s most famous inhabitants: THE POLISH MUSICIAN FRÉDÉRIC CHOPIN AND THE FRENCH WRITER GEORGE SAND LODGED IN THIS STREET ON 8 NOVEMBER 1838, THE DAY THEY ARRIVED IN MALLORCA, A VISIT TO THE ISLAND THAT ENDED ON 13 FEBRUARY 1839.', mt:'', ref:'如果今天走到那儿，就会看到一块高悬在石头上的牌匾，上面工整地刻着曾经的两位大名鼎鼎的住客——“波兰音乐家弗雷德里克·肖邦和法国作家乔治·桑于1838年11月8日登马略卡岛，住在这条街上，并于1839年 2月13日离岛。”' },
  { k:'seg_5_东部_10', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Chopin’s health and mood in these initial days were promising.', mt:'', ref:'头几天，肖邦的健康状况和心情都有所好转。' },
  { k:'seg_5_东部_11', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'To his Polish friend and copyist Julian Fontana in Paris he wrote of turquoise skies and lapis lazuli seas, emerald mountains and clear, clean air, palms and cedars, olive and orange trees, figs and pomegranates—everything to be found in the hothouses of Paris’ Jardin des Plantes.', mt:'', ref:'在写给巴黎的波兰朋友、乐谱抄写员朱利安·丰塔纳的信中，他提到了碧绿的天空和青金石色的海洋、翠绿的山脉和清澈洁净的空气、棕榈树和雪松、橄榄树和橘子树、无花果和石榴——应有尽有的景色，就像身临巴黎植物园的温室。' },
  { k:'seg_5_东部_12', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'He described the sunshine and moderate temperatures, the summer clothes worn by the townsfolk, the guitars at night playing for hours at a time.', mt:'', ref:'他还写到日落、适宜的气温、小镇居民的夏装，还有夏夜那些一弹就是好几个小时的吉他手。' },
  { k:'seg_5_东部_13', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“Oh, my dear fellow, I am really beginning to live.', mt:'', ref:'“哦，亲爱的朋友，我过上像样的日子了。' },
  { k:'seg_5_东部_14', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'I am close to all that is most beautiful.', mt:'', ref:'周围遍布着美丽事物，' },
  { k:'seg_5_东部_15', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'I am a better man.”', mt:'', ref:'我的心绪也好转了。”' },
  { k:'seg_5_东部_16', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Sand thought the climate as warm as a French June, perfect for exploring the port’s mix of High Gothic splendor and Moorish remnants: ramparts and stone peasant houses; thermal baths; unfamiliar street names; carved lintels and arabesque scrolls; tall windows divided by slender pillars; ornamental staircases leading up to enormous dark, bare rooms; and, beyond the city, the Jardines de Alfabia, nestled into terraced hills and irrigated by waterwheels.', mt:'', ref:'乔治·桑认为，这里的气候像法国六月一样温暖，非常适合探索这个融合了哥特辉煌和摩尔遗迹的港口：城墙和石头农舍、温泉浴场、陌生的街道名称、雕刻的门楣和阿拉伯式卷轴、细长柱子隔开的高窗、通向宽敞而黑暗的空房的饰纹楼梯，还有那坐落在城外，用水车灌溉的一格格梯田上的阿尔法比亚花园。' },
  { k:'seg_5_东部_17', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“I dream of music,”', mt:'', ref:'“我渴望音乐，”' },
  { k:'seg_5_东部_18', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Chopin wrote to Camille Pleyel, his French publisher, soon after arriving, “but I can’t write any because there are no pianos to be had here—in that respect it is a barbarous country.”', mt:'', ref:'登岛后不久，肖邦写信给他的法国出版人卡米尔·普莱耶尔，“但我无法创作，因为这里找不到钢琴——就这点而言，可以说是到了穷乡僻壤了。”' },
  { k:'seg_5_东部_19', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'It was the complaint of an artist thrown from his routine, a composer who habitually wrote his exceptionally original works at the piano and who now found himself without the one tool he needed.', mt:'', ref:'这就是一位艺术大师在工作节奏被全盘打乱后的抱怨，曾经那些杰出的作品都是在钢琴旁一笔笔写下的，但现在，他却找不到趁手的工具。' },
  { k:'seg_5_东部_20', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'So after a week of industry at full tilt belowstairs but little of it above, Chopin, Sand, her children, and the maid moved to a house in Establiments, off the Palma road, a small enclave northwest of the port, a property found for them by the French consul, Monsieur Fleury.', mt:'', ref:'他在楼下开足马力忙活了一周，但收获寥寥，于是，他带上乔治·桑和她的两个孩子还有女佣，搬到了港口西北的艾斯塔布里芒的房子里。房子还是法国领事弗勒里先生找来的。' },
  { k:'seg_5_东部_21', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Son Vent—the summer house in Establiments, which translates from Mallorquí as House of the Wind—cost Chopin and Sand fifty francs a month and was kitted out with wooden camp beds padded with paper-thin mattresses, straw-bottomed chairs, and rough-cut wooden tables.', mt:'', ref:'这房子是艾斯塔布里芒的避暑别墅，它有个名字叫Son Vent，在马略卡方言里是“风之屋”的意思。屋里布置的是木制行军床，床上垫着薄如纸片的床垫，椅子是稻草底的，木桌则做工粗糙。肖邦和乔治·桑一个月得为它支付50法郎。' },
  { k:'seg_5_东部_22', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'There were glazed windows in most rooms, though there were neither fireplaces nor chimneys, just a small brazier that filled the house with noxious fumes but little heat, and left the occupants with dry throats and charcoal-smoked eyes.', mt:'', ref:'屋里虽然没有壁炉也没有烟囱，但大多数房间都有玻璃窗。只有一个小火盆在屋里释放有害烟雾，却不放热。住在里面，感觉喉咙干燥，眼圈也被木炭熏黑。' },
  { k:'seg_5_东部_23', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Chopin, weakened by the stench and suffocating effect of the charcoal smoke, was by no means well in Establiments.', mt:'', ref:'终日面对难闻而令人窒息的炭烟，肖邦变得虚弱不堪，艾斯塔布里芒的日子一点也不好过。' },
  { k:'seg_5_东部_24', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'And despite temperatures of sixty-four degrees and air outside scented with roses, oranges, and figs, he caught a feverish cold.', mt:'', ref:'当地的气温在18度，室外的空气充满了玫瑰、橙子和无花果的香味，他却感冒发烧了。' },
  { k:'seg_5_东部_25', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'A succession of doctors (the grandest charging forty-five francs for his advice) prodded him and made dire pronouncements.', mt:'', ref:'他请过几个医生来看，最贵的要价45法郎，诊断结果都不乐观。' },
  { k:'seg_5_东部_26', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“It is all having a bad effect on the Preludes,” he told Fontana in early December, referring to the collection of piano pieces that had occupied his imagination for some time, the thread of which he was attempting to pick up in Majorca.', mt:'', ref:'“这些事情都对前奏曲产生了负面影响，”他在12月初的信中告诉丰塔纳，前奏曲指的是他构思了好一阵子的钢琴作品集，他本打算在马略卡开始正式的创作。' },
  { k:'seg_5_东部_27', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“God knows when you will receive them.”', mt:'', ref:'“天知道你什么时候才能收到了。”' },
  { k:'seg_5_东部_28', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Before leaving Paris, Chopin had ordered from Pleyel a pianino, but it reached Marseilles only as he was writing to Fontana at the beginning of December, where it was loaded on to a merchant ship, destined, Chopin feared, to spend the next months in one or other port, hostage to rains and customs bottlenecks, to the lethargy that accompanies the onset of winter.', mt:'', ref:'离开巴黎前，肖邦从普莱耶尔处订购了一台小型立式钢琴，但到12月初他写信给丰塔纳时，钢琴才运到马赛，装到了一艘商船上。肖邦担心，冬天的到来将令万物死气沉沉，面对连月不开的阴雨和层层设卡的海关，接下来的几个月，这台琴得在一个个港口中度过了。' },
  { k:'seg_5_东部_29', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“The lack of a piano is a source of great distress to me on the boy’s account,” Sand told Grzymała on December 3, just as Chopin’s health returned.', mt:'', ref:'“没有钢琴让我真替这个小子难过，”乔治·桑在12月3日的信中告诉格日马，此时肖邦的健康状况有所好转。' },
  { k:'seg_5_东部_30', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“He has hired a local one which gives him more vexation than consolation.', mt:'', ref:'“他在本地租到一台琴，不过这台琴没给他带去什么安慰，反而带来很多烦恼。' },
  { k:'seg_5_东部_31', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'All the same he is working.”', mt:'', ref:'不管怎么样，他开始创作了。”' },
  { k:'seg_5_东部_32', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The instrument was made by Juan Bauza of Mission Street, Palma.', mt:'', ref:'这台琴是帕尔马的密西恩大街的胡安·鲍扎制造的。' },
  { k:'seg_5_东部_33', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Majorca was indeed then a musical backwater, insulated from the pianoforte’s sudden and immense popularity throughout mainland Europe in the 1820s and 1830s, sparked by the achievements of Pleyel (Paris), Conrad Graf (Vienna), John Broadwood and Sons (London), Sébastien Erard and his nephew Pierre (Paris), each firm lodging new patents with a regularity that challenged the others.', mt:'', ref:'当时的马略卡，可谓是音乐文化的沙漠，完全隔绝于19世纪20年代至30 年代风靡欧洲大陆的钢琴文化之外。当时，普列埃尔（巴黎）、康拉德 ·格拉夫（维也纳）、约翰·布罗德伍德父子公司（伦敦）、塞巴斯蒂安· 埃拉尔和侄子皮埃尔（巴黎）的各种创新成就带动了这股潮流，每家公司都希望以新的专利发明确立技术标准与别人竞争。' },
  { k:'seg_5_东部_34', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Hélène Choussat de Canut, whose husband Bazile acted as Sand’s banker while she was in Majorca, had bought from a previous French consul a Pape piano—a model Chopin almost certainly knew from his visits to Pape’s showroom and concert hall on the rue des Bons-Enfants in Paris—though an instrument of this quality was a rarity on the island.', mt:'', ref:'乔治·桑在马略卡的银行经理叫巴兹勒，他的夫人海伦·卡努特从一位法国前领事那里买过一架巴贝牌钢琴，肖邦肯定知道这个品牌，因为他参观过巴黎Bons-Enfants大街的巴贝琴行和音乐厅，这种品质的乐器在岛上是罕见的。' },
  { k:'seg_5_东部_35', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In Palma, Bauza was completely isolated from these European developments.', mt:'', ref:'在帕尔马，鲍扎完全不了解欧洲大陆的这些发展。' },
  { k:'seg_5_东部_36', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'He lived less than a kilometer from the artillery barracks.', mt:'', ref:'他住在离炮兵营不到一公里的地方。' },
  { k:'seg_5_东部_37', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Apart from his address and this piano, nothing is known of him—not even whether he was responsible for a number of instruments or was merely a hobbyist, a single project on his mind, inspired by something he had seen or read about.', mt:'', ref:'历史上留下的，只有他的住址和这架钢琴，我们甚至不知道他到底是个乐器工匠，还是个一时兴起的爱好者，是不是当时见过或读到过什么受了启发，很想捣鼓一个东西出来。' },
  { k:'seg_5_东部_38', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Perhaps he was one of Majorca’s famously slow carpenters, about whom Sand is so rude in Un hiver à Majorque: a good furniture maker would have the skills and tools to build a piano.', mt:'', ref:'他也可能是个木匠，拖沓程度在马略卡当地出了名，乔治·桑在《马略卡的冬季》中对他很不客气：有点水平的家具木匠就应该有造钢琴的技术和工具。' },
  { k:'seg_5_东部_39', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Or a clockmaker, schooled in fine machinery and intricate mechanics, self- taught if necessary (as was the horologist John Harrison): a clockmaker too would know how to make a piano if he put his mind to it.', mt:'', ref:'哪怕是钟表匠，无论是接受过精密机械和复杂力学培训的，或是自学成才的（如钟表匠约翰·哈里森）：稍微上点心，也能造出钢琴。' },
  { k:'seg_5_东部_40', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'There was then no one single way to build one: it was much like the automobile industry at the end of the century, inventors and keen-eyed engineers advancing their own ideas, often their own patents, consensus following only later.', mt:'', ref:'当时的造琴法不止一种，这很像本世纪末的汽车工业，发明家和嗅觉灵敏的工程师提出自己的想法，注册独特的专利，技术上的共识要等上一段时间。' },
  { k:'seg_5_东部_41', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Consolidation of sorts came only in the 1860s and subsequently, thanks largely to the craft and innovation of Henry Engelhard Steinway and his five sons in their loft on Varick Street, Manhattan.', mt:'', ref:'直到19世纪60年代，这种技术共识才浮出水面，这在很大程度上要归功于亨利·恩格尔哈德·施坦威和他的五个儿子在曼哈顿瓦里克街阁楼里实践出的工艺和创新。' },
  { k:'seg_5_东部_42', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Before Steinway, piano makers simply responded as best they could to the challenges laid down by great composers: Beethoven in his final five sonatas (1816–22); Liszt in his Sonata in B Minor (1853, the year Steinway, Blüthner, and Bechstein were founded); Brahms in his first concerto (1858).', mt:'', ref:'在施坦威之前，钢琴制造商只是尽最大努力应对伟大作曲家提出的挑战：例如，贝多芬的最后五首奏鸣曲（1816-22年）、李斯特的B小调奏鸣曲（1853年，施坦威、布吕特纳和贝希斯坦成立的那一年），以及勃拉姆斯的第一钢琴协奏曲（1858年）。' },
  { k:'seg_5_东部_43', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'So the nascent revolution of the 1830s and 1840s—which saw instruments gradually increase in size, and strings and frame in tension—was not solely concerned with the pianos being made: what also now mattered was the way they were played (and by whom), and the music being written for them.', mt:'', ref:'到了19世纪30年代至40年代，乐器逐渐变大，琴弦和铁架间的张力逐渐增加，技术革新就不仅限于造琴了，它还关系到乐器的演奏方式、人员、乐曲创作等各方面的革新。' },
  { k:'seg_5_东部_44', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Liszt exploited the possibilities of Sébastien Erard’s double escapement action—whereby a note could be restruck before the hammer had returned to its resting position, a technique that aped Paganini on the violin and which sounded startling on a keyboard—and changed the physicality of piano playing: a pianist’s arms, shoulders, and back were now pressed into service to add weight and heft to the attack.', mt:'', ref:'塞巴斯蒂安·埃拉德的双重擒纵机构技术能让琴槌在回到静止位置之前，弹奏新的音符，这项技术模仿了帕格尼尼的小提琴，用在钢琴上的效果出奇的好。李斯特利用埃拉德的技术，革新了钢琴演奏对身体的要求：钢琴家的手臂、肩膀和背部都要加入演奏，以增加敲击的力度。' },
  { k:'seg_5_东部_45', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Pianos and pianists were suddenly required to do far more, as Liszt acknowledged in the late 1830s, writing about instruments that ran from four As below middle C (A0) to four Gs above (G7).', mt:'', ref:'突然间，钢琴和钢琴家就要承担更多的任务，正如李斯特在19世纪30年代末所承认的，那时的乐器音域从中央C开始，向下能延展到四个八度外的A（A0），向上能延展到四个八度外的G（G7）。' },
  { k:'seg_5_东部_46', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“In its span of seven octaves [the piano] embraces the range of an orchestra; the ten fingers of a single man suffice to render the harmonies produced by the combined forces of more than one hundred concerted instruments...', mt:'', ref:'“[钢琴]能够横跨七个八度，这样的音域堪比一整支交响乐队；一个人靠十个手指，就能弹出百余件乐器那种整齐、协调的和声……' },
  { k:'seg_5_东部_47', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'We make arpeggios like the harp, prolonged notes like wind instruments, staccatos, and a thousand other effects which once seemed the special prerogative of such and such an instrument.”', mt:'', ref:'我们可以弹出竖琴上的琶音、管乐器上的延音和断奏，甚至上千种此般或那般具有某种特色乐器的特殊音效。”' },
  { k:'seg_5_东部_48', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Such ready innovation ensured the piano’s quick passage into popular culture.', mt:'', ref:'这种颇具成熟度的革新，让钢琴迅速进入流行文化。' },
  { k:'seg_5_东部_49', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'A year before Chopin and Sand’s trip to Majorca, Charles Dickens plotted Mr. Pickwick’s escape inside one, removing the innards to make room: consumerism, not solely the advocacy of progressive musicians, was helping drive both industrial and cultural shifts.', mt:'', ref:'就在肖邦和乔治·桑赴马略卡旅行的前一年，查尔斯·狄更斯就在作品中设计了匹克威克先生利用钢琴脱逃的情节——拆除内部机构腾出空间。可以看到，除了进步音乐家的倡导，当时的消费市场也在推动行业和文化的转变。' },
  { k:'seg_5_东部_50', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'By the very circumstances of its construction and its place in the not always linear evolution of the modern piano, Bauza’s instrument was out of date before it was completed.', mt:'', ref:'由于现代钢琴制造技术并非平缓演进，加之马略卡岛的物质条件限制，鲍扎先生打造的琴在完工前已经落后于时代了。' },
  { k:'seg_5_东部_51', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'It possessed no technological pretensions: it was unable to support thicker or longer strings, greater tension, or a larger compass, its wooden frame and iron bracing a hostage to the island’s fierce climate.', mt:'', ref:'技术上，它毫无亮点，既不能支撑更粗更长的琴弦，也无法承受更大的张力，达不到更广的音域。木制框架和铸铁板面对岛上的恶劣气候则存在诸多隐患。' },
  { k:'seg_5_东部_52', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Yet it had its own beauty, and was in any case a rare artifact: a pianino in Majorca in the 1830s.', mt:'', ref:'不过，这架琴却有着独特的魅力，而且，它是19世纪30年代马略卡岛原产的小型立式钢琴，无论如何，都算一件罕见的艺术品了。' },
  { k:'seg_5_东部_53', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The Majorcan Preludes exploited every aspect of the pianos of the day, squeezed out every last drop of their capacity, and they are spread out fairly evenly through the collection.', mt:'', ref:'马略卡前奏曲充分利用了当时钢琴的各项技术进展，淋漓尽致地将其性能发挥到极致，从作品集的角度来看，这些前奏曲的内容分布较为均匀。' },
  { k:'seg_5_东部_54', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In No. 2 (A minor) unmoored harmonies underpin a melody no more sophisticated than something in a medieval psalter (a handful of notes artlessly stretched out), harmonies that ebb with alluring disregard for convention and key, which Chopin defines only in the final cadence when, midstream, he casually drops anchor.', mt:'', ref:'在第二首（A小调）中，无所依托的和声构筑起一段旋律（一组音符毫无雕饰地自然展开），缥缈如一首中世纪的祷告诗。这些和声恍惚地下降，不顾音乐传统和调式，直到结尾，肖邦定下了调式，乐曲也如行至河中央的船，随性地抛下了锚。' },
  { k:'seg_5_东部_55', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'No. 4 (E minor) is a brittle piece in which a bland chain of harmonies slips down a note at a time, glueing together as best it can the melody Chopin places above, which he extends almost to breaking point.', mt:'', ref:'第四首（E小调）是一首如泣如诉的曲子，曲中一连串平淡无奇的和声，一次滑下一个半音，尽可能地将肖邦叠在上方的旋律粘连起来，行至结尾时已近愁肠寸断。' },
  { k:'seg_5_东部_56', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'No. 5 (D) is built around a lumpy spinning-wheel figuration that sets off immediately and does not let up until the end, its character that of an étude, its tempo and intricacy suggesting that the Bauza’s action was spry enough.', mt:'', ref:'第五首（D大调）就像绕在一个凹凸不平的纺车上，随着纺车转起一下子释放开来直到结束。它拥有练习曲的特质，其节奏和复杂性表明鲍扎造的琴敲击起来非常敏捷。' },
  { k:'seg_5_东部_57', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'No. 7 (A) is a gentle music-box waltz that Chopin does not let run down (though he shuts the box’s lid immediately and without warning after the sixteenth bar).', mt:'', ref:'第七首（A大调）是一首来自八音盒的轻柔圆舞曲，肖邦不想让它停下来（不过到16小节后，他没有任何预示就立即关上了八音盒的盖子）。' },
  { k:'seg_5_东部_58', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'No. 9 (E) is a gruelling, insistent funeral march in the middle of the keyboard, under which the bass lumbers like organ pedals, the harmonies lurching from one point to the next in double-dotted Baroque figurations.', mt:'', ref:'第九首（E大调）是由琴键中部奏响的令人疲惫却又持续不断的葬礼进行曲，隆隆前行的低音像是由风琴踏板踩出，和声则蹒跚地一步步走向下一个巴洛克风格的双附点音。' },
  { k:'seg_5_东部_59', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In No. 10 (C sharp minor) scale patterns from high in the piano alternate with chorale fragments at its centre, an improbable duel that proves surprisingly well matched.', mt:'', ref:'第十首（C小调）中，钢琴高音部奏出的各色音阶与中心的合唱片段交替出现，这是一场不可思议的决斗，也是交相辉映的乐章。' },
  { k:'seg_5_东部_60', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'No. 14 (E flat minor) is like a fabulous Bach toccata, with the skeleton of a nursery rhyme or folk song wired into the last three bars, out of place amid such fine, lace-like finger work – out of place too in the dark key of E flat minor.', mt:'', ref:'第十四首（降E小调）像一段绝妙的巴赫托卡塔，而最后三小节注入了童谣或民歌的结构，因此在全曲精致、丝滑的弹奏过程中显得格格不入 ——显得格格不入的还有那个降E小调的黑键。' },
  { k:'seg_5_东部_61', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'(It is a little like Mahler’s grim excursions into the same nostalgic territory sixty years later, where nursery tunes are given the bleakest harmonic backdrops.)', mt:'', ref:'（该曲类似60年后马勒在同样的乡愁题材中创作的忧郁作品，童谣在这些作品中被用作让人倍感凄凉的背景和声。）' },
  { k:'seg_5_东部_62', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The hypnotic ostinato of No. 15 (D flat) works its magic from the outset and establishes the melodic material of the growling, chromatic storm to come.', mt:'', ref:'第十五首（降D小调）那个让人昏昏欲睡的固定音自乐曲开始就展现出魔力，之后又化身为咆哮而出的半音风暴中的旋律。' },
  { k:'seg_5_东部_63', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'(This was Schubert’s device in one of the most exquisite songs he ever wrote, ‘Die liebe Farbe’ in Die schöne Müllerin of 1823, which Chopin must have known, and in which a repeated note runs throughout.)', mt:'', ref:'（这是舒伯特在他写过的最精致的一首歌中用到的技巧，肖邦一定知道 1823年上演的《美丽的磨坊女》中的“被爱的颜色”，歌中始终贯穿着一个重复的音符。）' },
  { k:'seg_5_东部_64', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'No. 16 (B flat minor) is another right-hand étude that fills out the upper octaves of the piano with chromatic meanderings while the left hand does its best to stake a claim to the piece’s core tonality.', mt:'', ref:'第十六首（降B小调）是另一首右手练习曲，一堆迂回的半音在钢琴的高音八度区间跑动，而左手则奋力奏出曲子的主调。' },
  { k:'seg_5_东部_65', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'No. 18 (F minor) is like someone arguing with himself – interrupting, stuttering, slowly gaining in confidence and fluency, prone to wild coloratura declamations.', mt:'', ref:'第十八首（F小调）就像一个人在和自己争论——打岔、吞吞吐吐、渐渐变得自信流利，甚至雄辩到花腔走板。' },
  { k:'seg_5_南部_1', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google Takes Yet Another Run at E-Commerce—and Amazon', mt:'', ref:'对标亚马逊，谷歌再度争取搭上电商快车' },
  { k:'seg_5_南部_2', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google executive Prabhakar Raghavan recently had an issue with his rose bushes.', mt:'', ref:'谷歌高级副总裁普拉巴卡尔·拉加万（Prabhakar Raghavan）最近发现家中的玫瑰花簇长势不大好。' },
  { k:'seg_5_南部_3', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'His wife took a photo of the plants on her phone, uploaded the image to Google, identified the culprit and followed a link for a fungicide.', mt:'', ref:'拉加万的妻子用手机拍下玫瑰，上传到谷歌，知道了问题所在，并点击了杀菌剂的购买链接。' },
  { k:'seg_5_南部_4', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Then she bought it.', mt:'', ref:'接下来就是付费等待邮递。' },
  { k:'seg_5_南部_5', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'A seamless transaction that didn’t involve typing into a search bar, it was a real-life test of sorts for Raghavan’s strategic vision.', mt:'', ref:'这种无需搜索栏输入的无缝交易，正是拉加万的商业愿景。' },
  { k:'seg_5_南部_6', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'A senior vice president responsible for most of Google’s largest services—search, maps, advertising and more—the 61-year-old executive is determined to crack e-commerce, a market projected to hit $2.27 trillion in 2025 that the Alphabet Inc. division has tried and failed to figure out many times before.', mt:'', ref:'但要在现实层面执行并非易事。现年61岁的拉加万目前管理谷歌搜索、地图以及广告等主体业务。他准备带领谷歌再度进军电商领域。电商市场预估2025年营收可达2.27万亿美元，而此前谷歌的行动屡试屡败。' },
  { k:'seg_5_南部_7', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In the past, Google has tried emulating Amazon.com Inc.’s online retail and delivery services, with little luck.', mt:'', ref:'过去，谷歌曾试图效仿亚马逊公司的在线零售和送货服务，但并不奏效。' },
  { k:'seg_5_南部_8', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Now, under Raghavan, the search giant is positioning itself as a kind of anti-Amazon, a free marketplace for merchants and Amazon rivals that’s designed to get consumers more comfortable shopping with Google.', mt:'', ref:'如今在拉加万的带领下，谷歌一反往日效仿亚马逊的在线零售与送货业务的做法，而是重新将自身定位为一个由零售商和其他亚马逊竞争对手进驻的自由市场，为消费者提高更舒适的网购体验。' },
  { k:'seg_5_南部_9', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Last week, at Google’s I/O software conference, Raghavan and his deputies demonstrated new features they hope will achieve that end, including one that lets visitors use photos to search for nearby retail products or find any item in the physical world with the click of a camera.', mt:'', ref:'在上周的谷歌I/O开发者大会上，拉加万团队展示了关于新业务功能的构想，包括允许用户上传照片搜索距离最近的线下零售商，或是通过一键拍照了解到产品线下购买渠道。' },
  { k:'seg_5_南部_10', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'And on Tuesday, the company unveiled a feature that lets people go from merchant listings on Google search to their checkout pages in one click.', mt:'', ref:'本周二，谷歌推出的新功能是用户一键从正在浏览的产品页面跳转到购买页面。' },
  { k:'seg_5_南部_11', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Raghavan hopes the various initiatives will persuade millions of people to click buy, prompting sellers to purchase many more Google ads.', mt:'', ref:'拉加万希望这些功能帮助促进消费者的成交率，从而提高商户投放谷歌广告的意愿。' },
  { k:'seg_5_南部_12', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'For Amazon, which built a booming business by essentially renting its digital real estate to small sellers, the risk is that Google could give those brands a pathway to thriving outside its marketplace.', mt:'', ref:'亚马逊的营收来源于租赁数字房地产给零售商。谷歌也想在自己的地盘上采取相同的做法，分一杯羹。' },
  { k:'seg_5_南部_13', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'That in turn could force the Seattle-based company to more aggressively court sellers with discounts on fees, advertising or logistics services.', mt:'', ref:'为了保证客源，亚马逊可能会在产品定价、广告营销、物流送货等方面给客户更大的优惠。' },
  { k:'seg_5_南部_14', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Still, Amazon remains a formidable rival, and Google confronts daunting challenges.', mt:'', ref:'无论如何，对于谷歌而言，挑战亚马逊如此强大的竞争对手困难重重。' },
  { k:'seg_5_南部_15', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Its renewed push into e-commerce coincides with a slowdown in online shopping as consumers revert to their pre-pandemic habits.', mt:'', ref:'尽管消费水平回升至疫情发生前，但网购依然没有太大的起色，而谷歌选择了这期间重新冲锋电商行业。' },
  { k:'seg_5_南部_16', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Amazon and EBay Inc. both recently reported slowing growth and weak profit outlooks.', mt:'', ref:'亚马逊和eBay公司最近的营收前景惨淡、增长放缓。' },
  { k:'seg_5_南部_17', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Moreover, Google has always sought to make its technology fade into the background.', mt:'', ref:'谷歌一直希望技术淡出大众视野。' },
  { k:'seg_5_南部_18', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Turning the site into a shopping destination risks wrecking the experience and alienating visitors.', mt:'', ref:'网站若纯粹服务于购物，就会严重影响消费者的购物体验，流失用户。' },
  { k:'seg_5_南部_19', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Ahead of the I/O presentation, Raghavan took pains to say shopping on Google would be “super smooth.”', mt:'', ref:'在I/O会议作演讲前，拉加万努力宣传，称用户在谷歌的购物体验超级顺利。' },
  { k:'seg_5_南部_20', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'If the concept works as advertised, he said, “shoppers won’t have to think: ‘Am I doing a search?', mt:'', ref:'他说，一旦概念落地，消费者认为使用谷歌搜索购物，' },
  { k:'seg_5_南部_21', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Am I on Amazon or Google?’”', mt:'', ref:'与使用亚马逊并无差异。' },
  { k:'seg_5_南部_22', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Raghavan is the first Google executive to oversee the technical operations behind both search and the ads division since Sundar Pichai did in 2014, shortly before he became CEO.', mt:'', ref:'拉加万并非负责管理搜索部和广告部技术运营工作的首位高管。 2014年，现任谷歌首席执行官的桑达尔·皮查伊（Sundar Pichai）也曾负责该业务。' },
  { k:'seg_5_南部_23', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Raghavan is also one of the company’s best compensated executives, pulling down $28.6 million last year in salary and stock grants.', mt:'', ref:'拉加万是谷歌年薪收入最高的员工之一，去年单是工资和股票分红已进账2860万美元。' },
  { k:'seg_5_南部_24', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'As such, he has the clout to set an ambitious e-commerce strategy and, at least theoretically, get people who traditionally operated in silos to collaborate instead.', mt:'', ref:'这说明他有足够的信心去制定一个电子商务战略蓝图，理论上能够整合以往关联不大的业务。' },
  { k:'seg_5_南部_25', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Those who have worked with Raghavan point to his technical mastery and operational shrewdness—an unusual combination of attributes at a company that has so often coasted on its inventions and profits.', mt:'', ref:'拉加万的同事指出，他精通技术，善于运营，在谷歌这类注重技术与营收的商业公司来说是少见的人才。' },
  { k:'seg_5_南部_26', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“Google is violently allergic to strategic thinking,” said Sam Ramji, a former executive who worked with Raghavan on Google’s cloud products.', mt:'', ref:'曾与拉加万合作开发谷歌云产品的山姆·拉姆齐（Sam Ramji）评价，拉加万是一个能弥补谷歌缺乏战略思维这一缺点的人。' },
  { k:'seg_5_南部_27', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“He’s the man who brought strategy to Google.”', mt:'', ref:'他是有全局观的领导者。' },
  { k:'seg_5_南部_28', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Adds Martha Welsh, Google’s director of commerce strategy: “He really takes a holistic view of the business.”', mt:'', ref:'谷歌商务战略总监玛莎·威尔士（Martha Welsh）如是称赞道。' },
  { k:'seg_5_南部_29', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Since Raghavan’s promotion in mid-2020, he has torn up Google’s e- commerce playbook, scrapping the fees the company levied for online purchases and shuttering the delivery service.', mt:'', ref:'自2020年上任以来，拉加万修改了谷歌在电商方面的发展计划，免除了网购征税费用，取消了快递服务。' },
  { k:'seg_5_南部_30', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'He has tried poaching merchants irritated with Amazon, reshuffled the leadership ranks, and overhauled Google’s payments operations by dropping its banking plans and narrowing the focus.', mt:'', ref:'实际的操作包括引进不满亚马逊的零售商，调整管理层人事安排，并为了改善谷歌的支付流程，不惜减持理财资金、避免分散资源。' },
  { k:'seg_5_南部_31', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'He even tasked his search division with catering to people making heady commercial decisions, like buying a home or picking a college.', mt:'', ref:'甚至安排搜索团队为用户意向明确的商业决策需求提供服务，比如购房或择校。' },
  { k:'seg_5_南部_32', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“He’s willing to make bold moves,” said Bill Ready, Google’s president of commerce, who joined in 2020 as one of Raghavan’s top deputies.', mt:'', ref:'l 2020年加入谷歌，成为拉加万左膀右臂的商务总裁比尔·雷迪（Bill Ready）认为他的上司行事大胆。' },
  { k:'seg_5_南部_33', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Boldness is required.', mt:'', ref:'冒进是不得已为之。' },
  { k:'seg_5_南部_34', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'While Google’s advertising operation continues to print money, the model is under siege from regulators and privacy clampdowns, including Apple’s ban on targeted marketing messages.', mt:'', ref:'谷歌的广告业务在营利的同时也面对监管和隐私保护的双重打压。其中，苹果公司禁止谷歌投放个性化营销信息。' },
  { k:'seg_5_南部_35', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Due in part to these headwinds, the growth rate of the ad business is destined to slow, and Google isn’t the only one jumping into e-commerce to goose revenue; Meta Platforms Inc. and TikTok are as well.', mt:'', ref:'因此，广告业务停滞不前。而早在谷歌前，脸书和字节跳动两家公司已经开创了转战电商的先河。' },
  { k:'seg_5_南部_36', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Meanwhile, even as Google tries to build an online shopping destination to complement its ad business, Amazon has done the inverse: created a robust advertising operation on top of its enormous online bazaar.', mt:'', ref:'有意思的是，当谷歌选择打造购物网站来开源的同时，亚马逊却反其道而行之，全力投入到广告业务上。' },
  { k:'seg_5_南部_37', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google’s success is hard to gauge because it doesn’t break out e- commerce sales or retail ads.', mt:'', ref:'谷歌的电商与零售商广告业务营收有限，因而无法量化其表现。' },
  { k:'seg_5_南部_38', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Amazon’s is easy to see; its ads business posted 23% growth in the first quarter.', mt:'', ref:'但是亚马逊的广告业务在第一季度增长了23%，成绩一目了然。' },
  { k:'seg_5_南部_39', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“That seems to be working way better for Amazon than it is for Google,” said Mike Ryan, a portfolio strategist for Smarter Ecommerce GmbH.', mt:'', ref:'奥地利企业Smarter Ecommerce的投资分析师迈克·瑞安（Mike Ryan）认为亚马逊转换赛道的效果比谷歌要好。' },
  { k:'seg_5_南部_40', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Raghavan has tied Google’s main revenue and profit drivers—search and ads—more tightly to its e-commerce efforts than ever before.', mt:'', ref:'拉加万表现出比以往更强烈的决心，有意将谷歌的主营业务（搜索与广告）与电商捆绑发展。' },
  { k:'seg_5_南部_41', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'That’s all put more pressure on him to deliver on his strategy.', mt:'', ref:'这样做的后果是他面临更大的压力去贯彻他的战略目标。' },
  { k:'seg_5_南部_42', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Shopping Express', mt:'', ref:'昔日的网购速达' },
  { k:'seg_5_南部_43', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google’s last big e-commerce push involved going at Amazon head-on.', mt:'', ref:'谷歌上次进军电商采取的行动是正面挑战亚马逊。' },
  { k:'seg_5_南部_44', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In 2013, Google launched Shopping Express, a delivery service with a nifty app and a promise to ship many items on the same day.', mt:'', ref:'2013年，谷歌推出了网购速达的快递服务。用户下单程序的界面优美，且承诺当日送货上门。' },
  { k:'seg_5_南部_45', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google had huge retail partners on board, including Target Corp. and Walgreens, and planned an annual subscription model a la Amazon Prime.', mt:'', ref:'谷歌昔日的合作伙伴有塔吉特百货公司和药企沃尔格林公司等零售巨头。当时谷歌计划打造一个类似亚马逊Prime付费订阅会员的制度。' },
  { k:'seg_5_南部_46', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Back then, when quick e-commerce delivery was a novelty, Google’s service looked like a natural Amazon contender.', mt:'', ref:'在快速送货上门服务并不多见的年代，谷歌此举无疑表明其是亚马逊的有力竞争者。' },
  { k:'seg_5_南部_47', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'But it never was.', mt:'', ref:'但实际上谷歌未曾对亚马逊构成真正的威胁。' },
  { k:'seg_5_南部_48', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Shopping Express expanded to a few cities outside of the San Francisco Bay Area, but had little appeal for consumers.', mt:'', ref:'网购速达的服务覆盖旧金山湾区及其他几个美国城市，但消费者并不买账。' },
  { k:'seg_5_南部_49', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google’s “Shopping” site, accessible as a tab on its homepage, aggregated listings from online retailers with paid ads at the top, but attracted relatively few visitors compared with the main search page.', mt:'', ref:'主要原因在于，跟搜索主页相比，购物页面的浏览量少得可怜。用户可以在谷歌主页点击其中一个页签进入购物网站，占据购物网页前排位置的是购买付费广告的线上零售商。' },
  { k:'seg_5_南部_50', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Former Google employees say managerial indecision and an unwillingness to invest heavily in the margin-thin business undercut the strategy.', mt:'', ref:'谷歌的员工表示管理层认为电商业务利润微博，不愿意重金投资，所以在该领域的决策上权衡许久，导致了第一次进军的失败。' },
  { k:'seg_5_南部_51', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Then in 2015, Europe hit Google with a massive anti-monopoly suit that argued the search engine unfairly promoted its own shopping service over others.', mt:'', ref:'2015年，谷歌在欧洲折戟，收到反垄断集团诉讼，原因是谷歌搜索推广其购物网站业务这一行为，违背商业公平。' },
  { k:'seg_5_南部_52', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'That forced the company to spin off the European business and move more cautiously.', mt:'', ref:'因此谷歌的电商业务不得不放弃欧洲市场，并且更加谨慎行事。' },
  { k:'seg_5_南部_53', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google brought in consultants from BCG to assess a specific e-commerce strategy, but didn’t follow the firm’s recommendations.', mt:'', ref:'在这种情形下，谷歌邀请波士顿咨询公司（BCG）的专业顾问来为其电商战略进行点评，但最后却没有采纳对方的建议。' },
  { k:'seg_5_南部_54', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The company shortened the delivery service’s name (to just Express) and revamped it to center on its digital voice-assistant, another Amazon competitor.', mt:'', ref:'谷歌将“网购速达（Shopping Express）”改名为“速达（Express）”，并着重研发语音助理产品。其语音助理整体解决方案也是亚马逊Alexa的竞品。' },
  { k:'seg_5_南部_55', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'That effort fizzled, too.', mt:'', ref:'不过这些努力都没有奏效。' },
  { k:'seg_5_南部_56', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“For the past 15 years, Google has been trying to figure out commerce,” said Rick Watson, the head of RMW Commerce Consulting.', mt:'', ref:'纽约RMW商业咨询公司首席执行官瑞克·沃森（Rick Watson）评价称谷歌在过去十五年都致力于涉足电商的计划，' },
  { k:'seg_5_南部_57', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“And they’ve never really executed.”', mt:'', ref:'但却从未真正落实执行。' },
  { k:'seg_5_南部_58', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In early 2020, Google reset its strategy.', mt:'', ref:'2020年初，谷歌重新调整发展战略。' },
  { k:'seg_5_南部_59', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Management recruited Ready from PayPal to lead the commerce unit and realigned the search, payments and maps divisions to work more closely with his.', mt:'', ref:'PayPal第三方支付服务商企业的首席运营官雷迪（Bill Ready）加入谷歌，担任商务总裁一职，与负责搜索、支付和地图的业务部门有紧密合作。' },
  { k:'seg_5_南部_60', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'To run that entire portfolio, Google picked Raghavan, a veteran of its enterprise division who was put in charge of ads in 2018.', mt:'', ref:'不仅如此，谷歌还选中了拉加万领导电商等业务的发展。他在2018年曾主管广告业务。' },
  { k:'seg_5_南部_61', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Retail Leads the Online Ads Blitz', mt:'', ref:'零售促销线上广告' },
  { k:'seg_5_南部_62', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google\'s e-commerce strategy banks on getting retailers to buy more ads', mt:'', ref:'谷歌的电商战略在于促使零售商购买更多广告' },
  { k:'seg_5_南部_63', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Before joining Google in 2012, Raghavan spent years at tech research labs and in academia, where he became an expert on web search technologies just as they began taking off.', mt:'', ref:'在2012年加入谷歌之前，拉加万的工作场所是技术研究实验室和学术界。在网络搜索技术起步阶段，他已是这方面的专家。' },
  { k:'seg_5_南部_64', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'He speaks five languages and still carries himself more like a professor than a senior executive.', mt:'', ref:'不仅如此，他还精通五国语言。在他的身上，你更多会看到一位教授，而不是高管的影子。' },
  { k:'seg_5_南部_65', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'While discussing Google’s decision to emulate the visual, rapid-fire features of TikTok, he said, “It behooves us to also start thinking about those paradigms.”', mt:'', ref:'拉加万认为海外抖音(Tik Tok)的短视频带货是个很好的范例，并在会议上表示谷歌也应该去尝试。' },
  { k:'seg_5_南部_66', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'He once requested classical music to accompany his entrance onstage at an event before a staffer interceded.', mt:'', ref:'曾经有一次参与活动时，要不是工作人员阻止的话，他希望上台发言时的伴奏是古典音乐。' },
  { k:'seg_5_南部_67', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“He’s always surprised when he gets more responsibility,” said Jayshree Ullal, a longtime friend who runs Arista Networks Inc.', mt:'', ref:'网络设备企业Arista Networks公司的首席执行官雅什利·乌拉尔（Jayshree Ullal）与拉加万是多年的好友，他直言，“作为谷歌的二号人物，这样的人事任命让拉加万自己也感到惊讶。' },
  { k:'seg_5_南部_68', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“You can never tell he’s a high-powered number-two executive at Google.”', mt:'', ref:'他给人的感觉并不像是高高在上、重权在握的管理人员。”' },
  { k:'seg_5_南部_69', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Still, Raghavan made his e-commerce ambitions clear during the first year in his new role.', mt:'', ref:'上任第一年，拉加万还是明确表现出进军电商的决心。' },
  { k:'seg_5_南部_70', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google, he told colleagues, should think of users being on “journeys”—not simply coming to Google.com for information but to research and, hopefully, buy something.', mt:'', ref:'他对团队的要求是要把用户视为游客——用户不仅是在谷歌上搜索信息，而且是分析产品，最好是能直接购买商品。' },
  { k:'seg_5_南部_71', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'He and Ready quickly decided to pull the plug on Express.', mt:'', ref:'谷歌迅速决定放弃提供“速达（Express）”快递业务，' },
  { k:'seg_5_南部_72', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'They dropped the commission Google took for sales on its properties and the fees it charged merchants to list items on its shopping site, a signal to the industry that it wanted to be an open marketplace, not a competitor.', mt:'', ref:'以及数字资产销售提成，还有零售商广告排名的收费。这无疑是向行业释放出谷歌希望成为一个开放的市场，而非零售商的竞争对手。' },
  { k:'seg_5_南部_73', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“We’re not trying to put boxes on doorsteps,” Ready explained.', mt:'', ref:'雷迪解释谷歌不想成为快递服务提供商，' },
  { k:'seg_5_南部_74', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“What we’re trying to solve is the information part of the problem.”', mt:'', ref:'而是要解决信息不对称问题。' },
  { k:'seg_5_南部_75', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'By that, Ready meant making it easier for consumers to find desired products, deals or brands—even those that haven’t bought an ad.', mt:'', ref:'雷迪认为，这样一来，消费者更容易找到想要的产品、服务或品牌—— 无论卖家是否付费推广。' },
  { k:'seg_5_南部_76', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Search results now identify discounts and loyalty programs, while new widgets list the shipping costs and hidden fees on specific purchases.', mt:'', ref:'搜索结果自动显示产品折扣和其他优惠政策。新上市的产品会显示运费与价格明细。' },
  { k:'seg_5_南部_77', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google cut deals with Shopify Inc., Block Inc. and other commerce companies to make it more compelling for businesses to sell on Google properties.', mt:'', ref:'谷歌与电商Shopify、移动支付Block等企业就此达成一致。此举有望提高零售商购买谷歌数字资产的意愿。' },
  { k:'seg_5_南部_78', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Those features are designed for buying products like sneakers and cooking pans.', mt:'', ref:'同样地，消费者在选购运动鞋和平底锅等产品时也更加方便。' },
  { k:'seg_5_南部_79', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'But the company is also experimenting with items that aren’t on most e- commerce sites—helping consumers buy NFTs via image search or research such big-ticket purchases as real estate.', mt:'', ref:'但是谷歌购物网站上的产品也有一些是普通电商网站所没有的，比如使用图片搜索数字货币NFT，或者房地产等大宗买卖。' },
  { k:'seg_5_南部_80', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The company has noticed that searchers in the market for a home, college or car will often return to Google more than 60 times with similar queries before making a decision.', mt:'', ref:'用户在作出购买房屋、学校或汽车等大宗商品的决策前，至少会在谷歌上搜索60余次进行相关查询。' },
  { k:'seg_5_南部_81', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The idea is to customize the search experiences for these use cases in ways Google hasn’t before.', mt:'', ref:'于是，谷歌希望可以为这些用户定制化前所未有的搜索体验。' },
  { k:'seg_5_南部_82', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google has already done that with certain categories, creating unique features for people searching for jobs or hotels.', mt:'', ref:'在用户搜索职位与酒店这方面，谷歌已经做到了。' },
  { k:'seg_5_南部_83', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Companies like Yelp and the online travel industry have complained that these changes buried their sites and forced them to buy more ads to get clicks.', mt:'', ref:'同时，这也引起了点评网站Yelp和一众旅游网站的不满，认为他们网站的曝光率因此降低，从而需要付费购买广告获取点击率。' },
  { k:'seg_5_南部_84', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google’s search team has been quietly working on adding more topics.', mt:'', ref:'谷歌的搜索团队默默增加搜索主题数量。' },
  { k:'seg_5_南部_85', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Under the project, codenamed Mercury, the search team has ceded to the advertising group such areas as “shopping, real estate, mortgages, etc,” according to a memo reviewed by Bloomberg.', mt:'', ref:'据彭博社消息，谷歌的会议纪要显示，在一个代号为水星的项目中，广告团队取代搜索团队，负责购物、房地产、抵押贷款业务。' },
  { k:'seg_5_南部_86', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The authors of the document prioritized boosting traffic for merchants and creating “oh wow moments!” that would lure searchers back to Google.com and, eventually, a purchase.', mt:'', ref:'谷歌希望优先增加零售商的访问量，追求消费者尖叫度（Wow Moment），提高用户对谷歌的忠诚度，并最后能产生购买行为。' },
  { k:'seg_5_南部_87', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google declined to comment on the project, but executives have said the ads division doesn’t influence unpaid search results.', mt:'', ref:'谷歌方面拒绝对这个项目进行评价，但他们可以明确的是，这不会影响到免费商家的搜索结果。' },
  { k:'seg_5_南部_88', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Raghavan said the company has no plans to rival real estate brokers like Redfin.', mt:'', ref:'根据拉加万的说法，谷歌无意参与包括雷德芬（Redfin）在内的房地产中介公司的竞争。' },
  { k:'seg_5_南部_89', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'And, so far, Google has resisted using the search history of repeat visitors to tailor results.', mt:'', ref:'谷歌一直以来都拒绝使用重复访客的搜索历史来定制搜索结果。' },
  { k:'seg_5_南部_90', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'That’s largely to avoid violating people’s sense of privacy, he explained.', mt:'', ref:'拉加万的解释是这样做可以避免侵犯用户的隐私权。' },
  { k:'seg_5_南部_91', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“Can you, in these situations, offer the user more support in a long-running journey, without in any way creeping them out?”', mt:'', ref:'因此用户不会弃用谷歌，而谷歌可以长期留存客户，为他们提供更多的支持。' },
  { k:'seg_5_南部_92', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Raghavan said his teams were still exploring if they could.', mt:'', ref:'这正是拉加万团队致力实现的目标。' },
  { k:'seg_5_南部_93', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Some in Silicon Valley have blasted Google for filling search results with too many ads.', mt:'', ref:'部分硅谷人士批评谷歌在搜索结果显示中加入过多广告。' },
  { k:'seg_5_南部_94', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Raghavan said increased demand from advertisers during the pandemic probably drove the recent uptick in advertising, and he expects it to cool off amid easing restrictions on travel and events.', mt:'', ref:'拉加万称广告数量的攀升是疫情期间商家的广告投放需求增加导致的。随着政府放松对旅游和聚集活动的管制，广告付费将逐渐降温。' },
  { k:'seg_5_南部_95', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Early Success', mt:'', ref:'胜利的号角' },
  { k:'seg_5_南部_96', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'There are signs that Raghavan’s strategy is starting to pay off.', mt:'', ref:'事实证明，拉加万的计划奏效。' },
  { k:'seg_5_南部_97', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Earlier this year, Google revealed that e-commerce advertising was a leading contributor to a 43% bump to search revenue in 2021.', mt:'', ref:'今年年初，谷歌披露的消息称2021年搜索业务营收增长43%，其中电商广告功不可没。' },
  { k:'seg_5_南部_98', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Google also said last year that over a billion people shop on its properties every day, though it hasn’t updated the figure.', mt:'', ref:'根据谷歌截止到当日的统计，去年谷歌网站上的日均消费人数高达十亿以上，而统计数据在更新后只会更多。' },
  { k:'seg_5_南部_99', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In the fall, Morgan Stanley research showed that consumers were using Google and YouTube to research products and price-shop more often than they used Amazon, EBay or Walmart.', mt:'', ref:'摩根士丹利（Morgan Stanley）在去年秋季的研究显示，消费者分析商品时更倾向使用谷歌、YouTube与平价商店，反而很少选择亚马逊、 EBay或沃尔玛。' },
  { k:'seg_5_南部_100', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In April, the bank reported that 59% of survey respondents who are Amazon Prime members said they started researching products on Google, up from 50% in the fall.', mt:'', ref:'今年4月的调查报告表明，59%的受访者是亚马逊Prime付费订阅会员，他们已经使用谷歌来浏览商品。去年秋季这部分人数只有50%。' },
  { k:'seg_5_南部_101', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Talley & Twine, an independent watch brand based in Virginia, started getting serious about Google in the past two years and has sometimes seen a fivefold return on its ad spending.', mt:'', ref:'过去两年间，位于弗吉尼亚州的独立品牌手表制造商Talley & Twine开始重视谷歌的价值，因为在谷歌的广告投放会带来五倍的收益回报。' },
  { k:'seg_5_南部_102', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“It’s been a saving grace for us,” said President Randy Williams.', mt:'', ref:'首席执行官兰迪·威廉姆斯（Randy Williams）感叹这拯救了他们公司的业绩。' },
  { k:'seg_5_南部_103', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The other benefit, he added, is that the search engine sends customers to his web store.', mt:'', ref:'不仅如此，谷歌还帮助引流消费者到他们的网上商店。' },
  { k:'seg_5_南部_104', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“That’s the roadblock we have with Amazon,” Williams said.', mt:'', ref:'这是亚马逊没法做到的。' },
  { k:'seg_5_南部_105', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“Amazon’s customers are Amazon customers.”', mt:'', ref:'在他看来，亚马逊网站的消费者不属于零售商自身。' },
  { k:'seg_5_南部_106', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Still, some industry insiders say Google’s biggest moves to create a marketplace—cutting commissions and listing fees for merchants—have yet to attract significant numbers of shoppers.', mt:'', ref:'为了建立市场，谷歌降低商品展示的收费和提成。但有业内人士认为，此举未能提高消费者的访问量。' },
  { k:'seg_5_南部_107', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'When those changes were announced, some merchants braced for a big uptick in traffic and sales, said Ryan, the e-commerce strategist.', mt:'', ref:'例如，投资分析师瑞安认为，许多商家收到消息后期待点击率和销售额能大幅上升，但最后发现希望落空。' },
  { k:'seg_5_南部_108', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“Then nothing happened,” he said.', mt:'', ref:'谷歌的做法实际上意义不大。' },
  { k:'seg_5_南部_109', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“I would describe it as nice, but low-impact.”', mt:'', ref:'但看起来很好。' },
  { k:'seg_5_南部_110', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Kirk Williams, head of the online agency Zato Marketing, said Google’s fee adjustments didn’t alter consumer behavior enough to lure in more merchants.', mt:'', ref:'搜索引擎营销Zato Marketing的负责人柯克·威廉姆斯（Kirk Williams）也认为这样做并未改变消费者的网购习惯，因而商家进驻平台的意愿也较低。' },
  { k:'seg_5_南部_111', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Not many more people visited Google’s shopping site, where merchants could list for free, and most eyeballs remained on the search page, where merchants still have to buy ads to get in front of consumers.', mt:'', ref:'谷歌的购物网站浏览量不多，因而商家可以免费展示。而为了在流量最高的搜索网站有一席之地，商家必须购买付费广告才能得到曝光。' },
  { k:'seg_5_南部_112', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“It hasn’t been anywhere near the traffic volume that they were hoping to see,” Williams said.', mt:'', ref:'在柯克看来，这在商家眼里并没什么吸引力。' },
  { k:'seg_5_北部_1', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'When Did Humans Domesticate the Horse?', mt:'', ref:'马是何时被人类驯化的？' },
  { k:'seg_5_北部_2', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Only recently have scientists discovered exactly when and where the animal went from wild to tame', mt:'', ref:'直到最近科学家才成功确定家马的驯化时间和地点' },
  { k:'seg_5_北部_3', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Amber Dance, Knowable Magazine', mt:'', ref:'艾波·丹斯，《可知杂志》' },
  { k:'seg_5_北部_4', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'They say dogs are man’s best friend, but horses could also claim that', mt:'', ref:'人们都知道狗是人类最好的朋友，但马也是人类忠实的朋友。' },
  { k:'seg_5_北部_5', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Horses gave us a way to transport people and goods — literal', mt:'', ref:'马为人员往来和货物运输提供了一种新的方式——字面上讲的马力。' },
  { k:'seg_5_北部_6', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'horsepower They changed warfare: drawing chariots, carrying the cavalry.', mt:'', ref:'它们改变了战争形式：马可以拉战车，可以运送骑兵。' },
  { k:'seg_5_北部_7', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'They’ve inspired artists from Stone Age cave painters to the makers of “ My Little Pony.”', mt:'', ref:'它们为艺术家的创作提供了灵感，既包括石器时代洞穴画家，也包括《 小马宝莉》的制作人。' },
  { k:'seg_5_北部_8', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Their role in industry may have waned in favor of machines, but they still maintain a place in sport, in leisure and in our collective hearts.', mt:'', ref:'随着机器的出现和使用，马在生产中的作用就越来越小了，但它们在运动、休闲和我们心中仍然占有一席之地。' },
  { k:'seg_5_北部_9', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Horses have been intertwined with human culture since at least 2000 B.C.E. and were associated with certain human groups even earlier.', mt:'', ref:'至少从公元前2000年开始，马就与人类文化交织在一起，它们与某些人类群体的联系可能更早。' },
  { k:'seg_5_北部_10', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“Horses are the animal that has changed history,” says Ludovic Orlando, a molecular archaeologist at the University of Toulouse III-Paul Sabatier in France.', mt:'', ref:'法国图卢兹第三大学的分子考古学家卢多维克·奥兰多说：“马改变了人类的历史。”' },
  { k:'seg_5_北部_11', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Today, horse breeds number in the hundreds, from the high-stepping Lipizzan horses of Austria to the Clydesdale draft horses of Budweiser commercials to the thoroughbreds of the Kentucky Derby.', mt:'', ref:'目前，世界上的马有数百种之多，从奥地利的高脚利比扎马到百威啤酒广告中的克莱兹代尔挽马，再到肯塔基赛马会的纯种马。' },
  { k:'seg_5_北部_12', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Despite their differences, these animals are all Equus caballus, joined in the modern equid family by donkeys, zebras and the wild Przewalski’s horses of Central Asia (though some taxonomists prefer the name Equus ferus for wild horses, and classification of Przewalski’s horses can vary).', mt:'', ref:'它们虽有不同，但都是马 (Equus caballus)，现代马科动物还包括驴、斑马和中亚的普氏野马（尽管一些分类学家更喜欢用Equus ferus称呼野马，普氏野马的分类可能会有所不同）。' },
  { k:'seg_5_北部_13', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The evolutionary path leading up to Equus is a classic model of evolution — a thoroughly documented history that graces textbooks and museum exhibits.', mt:'', ref:'马的进化之路遵循着经典的进化模式——有着完整的历史记录，为教科书和博物馆陈列增色不少。' },
  { k:'seg_5_北部_14', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'But until lately, the route to domestication by people has been a black', mt:'', ref:'但是直到最近，马的驯化仍是一个未解之谜。' },
  { k:'seg_5_北部_15', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The bones of E. caballus all look pretty much the same, whether wild or domestic, so they couldn’t answer a longstanding question: Where and when did humans first domesticate horses, linking the two species on a road that would lead to horse-drawn carriages, horse-racing and so much more?', mt:'', ref:'无论是野马还是家马，它们的骨头看起来没什么区别，所以也就无法回答一个长期存在的问题：人类在何时何地首次驯化马匹？驯化将人类和马联系在一起，催生了马车、赛马等与马相关的物品和活动，使人类走上了新的发展道路。' },
  { k:'seg_5_北部_16', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Today, a revolution in the study of DNA, from both ancient and modern creatures, is providing answers.', mt:'', ref:'目前，对古马和现代家马DNA研究的革命正在破解这个难题。' },
  { k:'seg_5_北部_17', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Applying the same approach used in a landmark 2010 study of Neanderthal DNA, scientists have learned much about the history of Equus caballus.', mt:'', ref:'运用2010年对尼安德特人DNA的里程碑式研究中使用的同一方法，科学家对马的历史有了很多了解。' },
  { k:'seg_5_北部_18', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'They have tracked how ancient wild horses shared genes across the Bering Strait between Asia and North America, and revealed the surprising history of Przewalski’s horse.', mt:'', ref:'他们追踪到古代野马是如何跨越亚洲和北美洲之间的白令海峡共享基因的，并揭示了普氏野马的前世今生。' },
  { k:'seg_5_北部_19', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'And working with more modern samples, they have observed how recent management by people has undone much of the diversity in horse genomes, while adding a host of breed-specific features.', mt:'', ref:'通过对更多现代样本的研究，他们发现人类驯养马匹增加了不同品种的特性，但也破坏了马基因组的大部分遗传多样性。' },
  { k:'seg_5_北部_20', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'But there has never been quite enough ancient DNA to answer the question of domestication — until late 2021, when scientists reported their analysis of more than 250 ancient horse genomes.', mt:'', ref:'但是在2021年底之前，一直没有足够的古马DNA用于解答马匹驯化之谜。这年年底，科学家报告了他们对250多个古马基因组的研究结果。' },
  { k:'seg_5_北部_21', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“It’s great to have this big piece filled in, in the puzzle of where horses actually came from,” says Jessica Petersen, an animal geneticist at the University of Nebraska-Lincoln who wasn’t involved with that particular mystery.', mt:'', ref:'内布拉斯加大学林肯分校的动物遗传学家杰西卡·彼得森说：“在马的起源这个未解之谜中，这么大的一块空白被填补真是了不起。”她本人并没有参与这项研究。' },
  { k:'seg_5_北部_22', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'But, she adds, the domestication process was a complex series of events, and more intricate details will be difficult to uncover.', mt:'', ref:'但是，她补充道，驯化过程涉及一系列复杂的事件，很难揭示更为复杂的细节。' },
  { k:'seg_5_北部_23', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Evolution of the horse', mt:'', ref:'马的进化' },
  { k:'seg_5_北部_24', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Sifting through fossil bones and teeth, paleontologists have traced the ancestry of horses back roughly 50 million years to a dog-sized, hoofed animal called Hyracotherium — aka eohippus, the “dawn horse.”', mt:'', ref:'通过对马的骨骼和牙齿化石的筛选研究，古生物学家发现马的祖先可以追溯到大约5000万年前，是一种大小如狗、有蹄的动物，名叫“始祖马”，又名“黎明马”。' },
  { k:'seg_5_北部_25', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The genus Equus, as we know it, probably emerged between 4 million and 4.5 million years ago in the continent that would become North', mt:'', ref:'我们了解的马属动物可能出现在距今400万到450万年前的北美大陆上。' },
  { k:'seg_5_北部_26', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'(That’s well before the Homo lineage, which wouldn’t hit the scene for at least another million years.)', mt:'', ref:'（远在猿人谱系出现之前，因为至少在一百万年后，猿人谱系才会出现）。' },
  { k:'seg_5_北部_27', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Fast forward to the late Pleistocene, 11,700 to 129,000 years ago, and horses were trotting back and forth between Asia and the Americas on the Bering Land Bridge.', mt:'', ref:'快进到更新世晚期，距今1.17万年到12.9万年前。那时，马通过白令陆桥来回穿梭于亚洲和美洲之间。' },
  { k:'seg_5_北部_28', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The line leading to modern-day domestic horses and wild Przewalski’s horses split sometime in the middle of that epoch, between 35,000 and 50,000 years ago.', mt:'', ref:'大约在3.5万年到5万年前，现代家马和普氏野马在更新世中期的某个时候进化方向发生了分化。' },
  { k:'seg_5_北部_29', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'But about 11,000 years ago, around the time the Bering Land Bridge submerged for the last time, the North American horses went extinct, along with many other large species such as mammoths and giant', mt:'', ref:'然而，大约在1.1万年前，也就是白令陆桥最后一次被海水淹没的时候，北美马灭绝了，同时灭绝的还有猛犸象和巨型海狸等许多其他大型物种。' },
  { k:'seg_5_北部_30', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'While it’s hard to pinpoint a reason, climate, hunting or a combination of the two might have been a factor, says Alisa Vershinina, a geneticist at LifeMine Therapeutics in Cambridge, Massachusetts, who investigated the Bering crossings while working as a researcher at the University of California, Santa Cruz.', mt:'', ref:'马萨诸塞州剑桥市生物制药公司LifeMine Therapetuics的遗传学家阿利莎·韦尔西尼娜说，虽然很难确定北美马灭绝的具体原因，但气候、狩猎或两者的结合可能是其中一个因素。她在加州大学圣克鲁兹分校担任研究员期间曾经调查过白令陆桥通道。' },
  { k:'seg_5_北部_31', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Early humans would have seen horses around, and they were clearly interested in the majestic animals: Horses are the top animal depicted in Stone Age, Western European cave art.', mt:'', ref:'早期的人类会在定居点周围看到马，显然他们对这些高大雄壮的动物很感兴趣：马是石器时代西欧洞穴艺术中描绘的最重要的动物。' },
  { k:'seg_5_北部_32', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'But there’s a big difference between observing the animals for artistic inspiration and harnessing them for horsepower, transport and sport.', mt:'', ref:'但是，观察马匹以获得艺术灵感和驾驭它们以获得马力、便利交通和进行运动之间有很大的区别。' },
  { k:'seg_5_北部_33', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'When, and where, did the relationship between human and beast undergo a dramatic change?', mt:'', ref:'人类与马之间的关系是在何时何地发生了根本性的变化？' },
  { k:'seg_5_北部_34', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Horses were a late addition to the barnyard.', mt:'', ref:'马是后来才被驯化的。' },
  { k:'seg_5_北部_35', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Dogs were domesticated 15,000 years ago; sheep, pigs and cattle, about 8,000 to 11,000 years ago.', mt:'', ref:'狗在1.5万年前被驯化；羊、猪和牛大约在8000至11000年前被驯化。' },
  { k:'seg_5_北部_36', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'But clear evidence of horse domestication doesn’t appear in the archaeological record until about 5,500 years ago.', mt:'', ref:'但是考古资料中有明确证据显示马的驯化始于距今约5500年前。' },
  { k:'seg_5_北部_37', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Horse remains from across Eurasia gave scientists several candidates for the first domestication event.', mt:'', ref:'欧亚大陆各地发现的马的遗骸为科学家们了解马匹首次驯化提供了几个候选遗址。' },
  { k:'seg_5_北部_38', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'For example: In 2018, scientists found a frozen, mummified horse in modern-day Siberia.', mt:'', ref:'例如， 2018年，科学家在西伯利亚发现了一匹冰冻木乃伊马，' },
  { k:'seg_5_北部_39', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'It was dated to about 4,600 years ago.', mt:'', ref:'其历史可以追溯到大约4600年前。' },
  { k:'seg_5_北部_40', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Might it have been one of the first workhorses?', mt:'', ref:'它有可能是最早的驮马吗？' },
  { k:'seg_5_北部_41', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Iberia, the peninsula containing modern-day Spain and Portugal, seemed promising because horses have continuously inhabited the region for the past 50,000 years, and would have been available for potential domestication.', mt:'', ref:'伊比利亚半岛，包括今天的西班牙和葡萄牙，似乎很有希望，因为在过去的5万年里该地区一直有马在活动，所以存在驯化的可能。' },
  { k:'seg_5_北部_42', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'And in the part of Eastern Europe around the Caspian Sea, archaeologists noticed horse remains appearing alongside those of other domestic animals.', mt:'', ref:'在里海周围的东欧部分地区，考古学家发现马的遗骸与其他家畜的遗骸一起出现。' },
  { k:'seg_5_北部_43', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Human burials about 6,000 years ago began to contain maces decorated with horse heads, perhaps indicating some change in human-horse relations.', mt:'', ref:'大约6000年前，人类墓葬中开始出现马头形权杖，这显示人与马的关系可能发生了一些变化。' },
  { k:'seg_5_北部_44', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'This area also got attention because of long-term horse presence in the area.', mt:'', ref:'该地区也因为马在附近长期活动而备受关注。' },
  { k:'seg_5_北部_45', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'But the archaeological site that captivated many horse-domestication researchers was the 3500 B.C.E. settlement at Botai, about 1,000 miles northwest of the Caspian, in modern-day Kazakhstan.', mt:'', ref:'然而，吸引了众多马匹驯化研究人员的考古遗址是公元前3500年的波泰人定居点。波泰遗址位于里海西北约1000英里，在今天的哈萨克斯坦境内。' },
  { k:'seg_5_北部_46', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The diet of the people in Botai seems to have been “entirely focused on horses,” says Alan Outram, a zooarchaeologist at the University of Exeter in England.', mt:'', ref:'英国埃克塞特大学的动物考古学家艾伦·奥特拉姆说，波泰人的饮食似乎“完全以马中心”。' },
  { k:'seg_5_北部_47', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Aside from a few dog bones, those of horses make up the majority of non-human remains on the site.', mt:'', ref:'在波泰遗址发现的非人类遗骸，除了几根狗骨之外，大部分都是马骨。' },
  { k:'seg_5_北部_48', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'There’s evidence of fenced yards that might have held herds.', mt:'', ref:'有证据表明，栅栏围起来的场地可能是用来圈养马匹的。' },
  { k:'seg_5_北部_49', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Some skulls hint at slaughter by an axlike tool, and some horse teeth exhibit “bit wear,” as if they’d been bridled.', mt:'', ref:'一些头骨显示这些马是用斧状工具宰杀的，而一些马牙有“磨损”的痕迹，就像它们被勒过一样。' },
  { k:'seg_5_北部_50', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Pottery shards contain chemical traces of mare’s milk, which Outram says might have been consumed as butter, yogurt or cheese.', mt:'', ref:'陶器碎片上残留着马奶痕迹，奥特拉姆说这些马奶可能被用来制作黄油、酸奶或奶酪供人们食用。' },
  { k:'seg_5_北部_51', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Nonetheless, the site’s importance has been hotly debated.', mt:'', ref:'尽管如此，这个遗址的重要性还是引发了激烈的争论。' },
  { k:'seg_5_北部_52', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'There’s no way to confirm that Botai inhabitants fully domesticated horses.', mt:'', ref:'目前尚无法证实波泰人成功地驯化了马。' },
  { k:'seg_5_北部_53', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Outram suspects that the Botai peoples treated the horses somewhat like how modern reindeer herders use their animals: They may have kept the horses near at hand for meat and milk, and maybe even have ridden a few of them to herd others.', mt:'', ref:'奥特拉姆猜测波泰人对待马的方式可能有点像现代驯鹿牧民使用驯鹿那样：他们在定居点附近养马，用来吃肉和喝奶，甚至可能会骑几匹马去放牧其他家畜。' },
  { k:'seg_5_北部_54', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'But they probably weren’t managing breeding or using the animals extensively as pack or transport animals.', mt:'', ref:'但他们可能没有繁育马匹，也没将其广泛用作驮畜或交通工具。' },
  { k:'seg_5_北部_55', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'And without enough ancient DNA, there was no way to be sure these were the horses that spread around the world as human-managed', mt:'', ref:'由于没有足够的古马基因，就无法确定这些马是否作为人类驯养的家畜传播到世界各地的。' },
  { k:'seg_5_北部_56', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Then Orlando, Outram and colleagues analyzed a broad set of horse genomes, from as far back as about 42,800 years ago all the way up to 18 modern breeds, publishing the findings in the journal Science in 2018.', mt:'', ref:'后来，奥兰多、奥特拉姆和同事共同分析了马基因组，涵盖范围很广，从大约4.28万年前一直到18个现代马种，并于2018年在《科学》杂志上发表了研究成果。' },
  { k:'seg_5_北部_57', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The result: Today’s ponies, draft horses and their ilk have little in common with the Botai horse bones.', mt:'', ref:'研究发现现代矮马、役马及其同类与波泰马的骨头几乎没有相同之处。' },
  { k:'seg_5_北部_58', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'They re not the genetic origin for modern domestic horses, says', mt:'', ref:'“这足以说明波泰马不是现代家马的祖先，”奥特拉姆说。' },
  { k:'seg_5_北部_59', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Outram The Botai lineage does live on, though.', mt:'', ref:'不过，波泰马的血统确实存在。' },
  { k:'seg_5_北部_60', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Unexpectedly, the researchers were able to draw a direct line between those 5,500-year-old bones and modern Przewalski’s horses.', mt:'', ref:'出乎意料的是，研究人员发现这些5500年前的马骨与普氏野马存在着关联。' },
  { k:'seg_5_北部_61', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'These stocky animals with short, bristly manes live on the steppes of Mongolia, where they’re called takhi, or “spirit,” and considered a national symbol.', mt:'', ref:'普氏野马体型健硕，鬃毛较短而直立，生活在蒙古大草原上，在那里人们称其为“天马”，并将其视为民族的象征。' },
  { k:'seg_5_北部_62', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In other words, Przewalski’s horses, once considered the remnants of an eternally wild population, may not be completely wild after all.', mt:'', ref:'换言之，普氏野马曾经一度被认为是永久野生种群的残留，但它们可能并不完全是野生的。' },
  { k:'seg_5_北部_63', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Rather, they seem to be the feral descendants of horses that people at Botai might have managed, to some extent, but later lost control of.', mt:'', ref:'相反，它们似乎是曾经由波泰人驯养但后来又逃脱的马的后代。' },
  { k:'seg_5_北部_64', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'They’d have that in common with other feral populations such as the mustangs of the American West and Australian brumbies.', mt:'', ref:'在这方面，它们与其他野生种群，如美国西部野马和澳大利亚野马，并无不同。' },
  { k:'seg_5_北部_65', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Przewalski’s horses aren’t much good for riding, notes Arne Ludwig, an evolutionary geneticist at the Leibniz Institute for Zoo and Wildlife Research in Germany.', mt:'', ref:'德国莱布尼茨动物园和野生动物研究所的进化遗传学家阿恩·路德维希指出，普氏野马不太适合骑乘。' },
  { k:'seg_5_北部_66', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Perhaps, he speculates, that’s why they fell out of use.', mt:'', ref:'在他看来，这也许是它们被淘汰的原因。' },
  { k:'seg_5_北部_67', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Whatever happened after Botai, Przewalski’s horses had a rough go of it.', mt:'', ref:'在波泰人之后，不管怎样，它们的生存都异常艰难。' },
  { k:'seg_5_北部_68', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'They nearly went extinct, with the last wild animal disappearing in 1969.', mt:'', ref:'它们几乎灭绝了，1969年最后一匹野外环境下的普氏野马死亡了。' },
  { k:'seg_5_北部_69', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Today’s population, all descendants of a handful of animals that persisted in captivity, now number around 2,000 individuals in captivity or natural reserves.', mt:'', ref:'今天的普氏野马种群，都是少数圈养的普氏野马的后代，目前有2000匹被圈养或生活在自然保护区，' },
  { k:'seg_5_北部_70', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'There are also a few modern domestic horses in their family tree.', mt:'', ref:'其谱系中也有一些现代家马。' },
  { k:'seg_5_北部_71', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Domestication rising', mt:'', ref:'驯化提升' },
  { k:'seg_5_北部_72', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Despite these advances, when Orlando documented genomic studies of horse domestication for the Annual Review of Genetics in 2020, he was forced to conclude, “The geographic origin of modern domestic horses is presently unknown.”', mt:'', ref:'尽管相关研究取得了一些进展，当奥兰多2020年为学术期刊《遗传学研究进展年鉴》撰文对马匹驯化基因组研究进行综述时，他也不得不承认，“我们目前尚不清楚现代家马的地理起源。”' },
  { k:'seg_5_北部_73', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'But the clues were building up.', mt:'', ref:'但是证据在不断增加。' },
  { k:'seg_5_北部_74', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Scientists had already nixed the Iberia and Siberia candidates: When researchers looked at ancient DNA, they found that those horse populations withered away, contributing little to the modern domestic lineage.', mt:'', ref:'科学家已经否决了家马起源于伊比利亚半岛和西伯利亚的说法：当研究人员观测古马DNA时，发现生活在上述两个地区的马的种群数量越来越少，对现代家马谱系贡献甚微。' },
  { k:'seg_5_北部_75', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Getting to the true domestication site was a numbers game, says lead author Orlando.', mt:'', ref:'该研究的主要作者奥兰多说，确定真正的驯化地点是一个数字游戏。' },
  { k:'seg_5_北部_76', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“We built the answer by narrowing down the evidence, little by little.”', mt:'', ref:'“我们通过一点一点地缩小证据范围来找到答案。”' },
  { k:'seg_5_北部_77', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The more than 150 collaborating scientists, including Outram and Ludwig, kept adding more horse genomes, from across Eurasia and spanning about 50,000 to 200 B.C.E.', mt:'', ref:'包括奥特拉姆和路德维希在内的150多名科学家携手合作不断添加更多的马基因组，这些基因组来自欧亚大陆，时间跨度很大，从5万年前左右到公元前200年。' },
  { k:'seg_5_北部_78', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'With 264 ancient horse genomes in hand, the answer was undeniable: The homeland of modern domestic horses was the part of Western Eurasia between and north of the Black and Caspian seas, more specifically known as the lower Volga-Don region.', mt:'', ref:'研究基于现有的264个古马基因组，因此结果是不容置疑的：现代家马起源于西欧亚大陆的某一地区，该地区位于黑海和里海之间及以北，具体来说是伏尔加河和顿河下游地区。' },
  { k:'seg_5_北部_79', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The team reported their results in Nature in October 2021.', mt:'', ref:'研究团队于2021年10月在《自然》杂志上发表了他们的研究成果。' },
  { k:'seg_5_北部_80', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'While the data point to a clear answer, there’s still plenty of room for interpretation and speculation.', mt:'', ref:'尽管数据指向了一个明确的答案，但仍然需要进行大量阐释与探讨。' },
  { k:'seg_5_北部_81', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Pinpointing that spot near the Caspian doesn’t mean it was the only place — and time — that people bent horses to the bridle.', mt:'', ref:'确定里海附近的那个地区并不意味着它是人们驯化马匹的唯一地点和时间。' },
  { k:'seg_5_北部_82', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The genomic and paleontological evidence from the other candidate regions suggests horses may have been domesticated multiple times, at Botai and elsewhere, without leading to widespread horsemanship.', mt:'', ref:'来自其他候选地区的基因组和古生物学证据表明，马可能曾经在波泰和其他地方被驯化过多次，尽管没有使骑术传播开来。' },
  { k:'seg_5_北部_83', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'“It shows how important horses were to people, that so many groups of people independently domesticated them,” says Beth Shapiro, an evolutionary biologist at the University of California, Santa Cruz, and a coauthor of the Nature study.', mt:'', ref:'加州大学圣克鲁兹分校的进化生物学家、《自然》研究的合作者贝丝· 夏皮罗说：“那么多群体独立进行马匹驯化，这足以表明马对人类有多重要。”' },
  { k:'seg_5_北部_84', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The 2021 analysis does suggest that the domestication in the Volga-Don was the only one that “took,” the only one that spread like horse-drawn wildfire.', mt:'', ref:'2021年的研究表明，伏尔加河和顿河地区的马匹驯化是唯一一次“传播开来”的驯化，唯一一次野火般蔓延开来的驯化。' },
  { k:'seg_5_北部_85', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Why were horses one of the last animals to be domesticated, and why these horses in particular?', mt:'', ref:'为什么马是最后被驯化的家畜呢？为什么是这些马呢？' },
  { k:'seg_5_北部_86', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'While it’s impossible to be certain, ancient genomes suggest tantalizing hypotheses.', mt:'', ref:'虽然无法确定最终原因，但古马基因组足以让我们提出诱人的假设。' },
  { k:'seg_5_北部_87', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The lineage leading to modern domestic horses included a change near a gene called GSDMC.', mt:'', ref:'现代家马谱系包含一个名为GSDMC的基因，该基因周围发生了的变化。' },
  { k:'seg_5_北部_88', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In people, alterations to this gene are linked to back problems.', mt:'', ref:'在人类身上，这种基因的改变与背部问题有关。' },
  { k:'seg_5_北部_89', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'It’s possible that the domestic horse version gave the animals stronger backs, suitable for long-distance riding.', mt:'', ref:'家马的这种基因变化能够赋予其更加强壮的背部，使其适合长途骑行。' },
  { k:'seg_5_北部_90', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The domestic horse line also includes a change near a gene called', mt:'', ref:'家马谱系还包含一个名为ZFPM1的基因，' },
  { k:'seg_5_北部_91', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'ZFPM1 This gene is important in mood regulation.', mt:'', ref:'该基因对调节情绪非常重要。' },
  { k:'seg_5_北部_92', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Perhaps some domestic version of ZFPM1 made the animals in the region more docile, easier to tame.', mt:'', ref:'也许是某个版本中ZFPM1的基因变化使马变得更温顺，更容易驯化。' },
  { k:'seg_5_北部_93', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'These changes could have been the key to long-term horse domestication — but that’s all speculation, says Shapiro.', mt:'', ref:'夏皮罗说，这些变化可能是长期驯化马的关键——当然这也只是猜测。' },
  { k:'seg_5_北部_94', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'As for who did the domesticating, it hasn’t been possible to narrow it down to one culture, says Orlando.', mt:'', ref:'奥兰多说，至于是谁驯养的，目前还无法将其归结到某一文化。' },
  { k:'seg_5_北部_95', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Diverse people from the region may have started experimenting with these horses about 4,200 years ago.', mt:'', ref:'生活在该地区的各个民族大约从4200年前就已经开始驯化马了。' },
  { k:'seg_5_北部_96', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Domestic horses spread a bit from that point on, but things didn’t really take off until about 2000 B.C.E.', mt:'', ref:'从那时起，家马开始向外传播，但直到公元前2000年左右家马的传播才算真正开始。' },
  { k:'seg_5_中西部_1', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The mere thought of Chinese cultural influence on the founding of the United States is unimaginable to some.', mt:'', ref:'对一些人来说，仅仅想一想中国文化对美国建国产生了影响是难以置信的。' },
  { k:'seg_5_中西部_2', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Misperceptions—colored by potent, biased assumptions in the West—are partially responsible.', mt:'', ref:'其中部分原因在于他们被西方各种强有力的、带有偏见的假设所影响。' },
  { k:'seg_5_中西部_3', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'This book presents evidence—based on investigation and analysis—that the founders of the United States were influenced by many positive elements derived from their study of classical Chinese culture.', mt:'', ref:'本书提出的证据都是基于调查和分析。这些证据表明美国的开国元勋受到了他们研究的中国传统文化中许多积极因素的影响。' },
  { k:'seg_5_中西部_4', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Indeed, those same cultural and technological influences on what emerged as an independent, forward-thinking nation started even before the formal Declaration of Independence on July 4, 1776.', mt:'', ref:'确实，这些来自中国文化和技术的影响早在1776年7月4日美国《独立宣言》发布前就存在了。它们影响了美国这个独立的、具有前瞻性的国家的建立。' },
  { k:'seg_5_中西部_5', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Although China was geographically far removed from direct contact with the British Empire’s North American colonies, the newly independent, fledgling American republic’s relationship with China started with trade in 1784 via the voyage of the Empress of China.', mt:'', ref:'虽然地理上，中国与远离英国的这块北美殖民地相距甚远，但这个新独立的、羽翼未丰的共和国与中国的关系始于通过1784年中国皇后号进行的贸易往来。' },
  { k:'seg_5_中西部_6', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Chinese civilization was the object of intrigue, curiosity, and admiration by Europeans and Americans alike, carried over by Jesuits’ articles and translations of Chinese classics and conveyed via the stories of traders and explorers.', mt:'', ref:'欧美等地的人们对神秘的中华文明感到好奇，非常钦佩。他们对中华文明的了解来自于耶稣会士的文章，或是中国经典作品的翻译，或是商人和探险家的故事。' },
  { k:'seg_5_中西部_7', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Influences varied.', mt:'', ref:'中华文明的影响多种多样。' },
  { k:'seg_5_中西部_8', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'They ranged in the areas of agriculture, architecture, Confucian-based moral and political philosophies, and more as foundations for the new American nation evolved.', mt:'', ref:'这些影响随着新生的美国国家发展，涉及到农业、建筑、基于儒家的道德思想和政治哲学等等诸多方面。' },
  { k:'seg_5_中西部_9', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Recognized as one of the world’s most stable and successful classical civilizations, China offered many lessons and precedents that were distinct from the founders’ European heritage.', mt:'', ref:'众所周知，中华文明是世界上最稳定、历史最悠久的文明之一，蕴含许多经验和先例，它们与开国元勋所继承的欧洲传统截然不同。' },
  { k:'seg_5_中西部_10', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'To some of the founders, China presented a model for the young nation.', mt:'', ref:'对一些开国元勋来说，中国是这个年轻国家学习的榜样。' },
  { k:'seg_5_中西部_11', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'They welcomed positive elements from Chinese civilization while integrating those same elements into an authentic, distinctly American culture that in turn had been inspired by the winds of change propelled by the best of the Age of Enlightenment that had emerged in Europe.', mt:'', ref:'他们欢迎来自中华文明的积极元素，同时将这些元素融入到真正的、独特的美国文化中，而这种美国文化又受到了欧洲启蒙运动最佳时期推动的变革浪潮的鼓舞。' },
  { k:'seg_5_中西部_12', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In pre-independence America, the founders introduced elements of Chinese agriculture practice to the North American colonies, facilitating advances in social and economic development.', mt:'', ref:'在独立前的美国，开国元勋把中国农业的实践元素引入北美殖民地，促进了社会和经济发展的进步。' },
  { k:'seg_5_中西部_13', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Chinese-inspired agriculture and industrial technologies bolstered the colonial economies, resulting in prosperity for the Americans.', mt:'', ref:'受到中国的启发，殖民地的农业和工业技术促进了经济发展，给美国人带来了繁荣。' },
  { k:'seg_5_中西部_14', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Personal letters and other records indicate that Benjamin Franklin obtained seedlings of select Chinese plants.', mt:'', ref:'私人信件和其他记录都表明，本杰明·富兰克林（Benjamin Franklin）获得了多种中国植物的精选幼苗。' },
  { k:'seg_5_中西部_15', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Washington and Jefferson experimented with Chinese flowers in their personal gardens.', mt:'', ref:'华盛顿和杰斐逊在他们的私人花园中试种了来自中国的花卉。' },
  { k:'seg_5_中西部_16', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Franklin—America’s most famous scientist and philosopher—expressed great interest in Chinese industrial technologies, such as milling, heating, shipbuilding, and papermaking.', mt:'', ref:'美国最著名的科学家和哲学家富兰克林对中国的工业技术，比如碾磨、供热、造船、造纸等，都表示出浓厚兴趣。' },
  { k:'seg_5_中西部_17', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'He and fellow statesman Benjamin Rush promoted silk-making (or sericulture) in North America.', mt:'', ref:'他和另一位政治家本杰明·拉什(Benjamin Rush)在北美推广了丝绸制造（或养蚕）的工艺。' },
  { k:'seg_5_中西部_18', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Almost simultaneously, Thomas Jefferson was influenced by classical elements of Chinese architecture where it took form at Monticello.', mt:'', ref:'几乎同时，托马斯·杰斐逊(Thomas Jefferson)受到了中国古代建筑元素的影响，这些元素在他位于蒙蒂塞洛（Monticello）的住所得以呈现。' },
  { k:'seg_5_中西部_19', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'George Washington, Alexander Hamilton, and Gouverneur Morris were inspired through published literature by explorers on the Grand Canal of China.', mt:'', ref:'乔治·华盛顿（George Washington）、亚历山大·汉密尔顿（Alexander Hamilton）和古弗尼尔·莫里斯（Gouverneur Morris）都受到来自中国京杭大运河上的探险家的文学作品的启发。' },
  { k:'seg_5_中西部_20', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Later, these same Chinese technological innovations would influence the construction of the Erie Canal and spur the development of New York City.', mt:'', ref:'之后，这些同样的技术创新将影响伊利运河的开凿，并且推动纽约的城市发展。' },
  { k:'seg_5_中西部_21', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'America’s Founding Fathers modeled efforts toward the self-cultivation of personal virtue.', mt:'', ref:'美国的开国元勋努力培养个人美德，做出了典范。' },
  { k:'seg_5_中西部_22', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In turn, younger generations of Americans had free access to published works where traditions associated with Confucian philosophy were articulated.', mt:'', ref:'相应地，一代代的年轻美国人免费阅读各种出版物，了解儒家哲学的传统思想。' },
  { k:'seg_5_中西部_23', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The founders frequently drew from Confucian philosophies, embracing a new political framework for the young nation.', mt:'', ref:'开国元勋们经常借鉴儒家哲学思想，为这个年轻的国家制定了全新的政治框架。' },
  { k:'seg_5_中西部_24', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Many prominent colonists—Benjamin Franklin, Thomas Jefferson, John Adams, Thomas Paine, John Bartram, and Jedidiah Morse, among others—demonstrated their respect for Confucian moral philosophy, incorporating its principles into American culture.', mt:'', ref:'包括本杰明·富兰克林、托马斯·杰斐逊、约翰·亚当斯（John Adams）、托马斯·潘恩（Thomas Paine）、约翰·巴特拉姆（John Bartram）和杰迪迪亚·莫尔斯（Jedidiah Morse）在内的许多杰出的殖民者，尊重儒家道德哲学，并将其原则融入美国文化。' },
  { k:'seg_5_中西部_25', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Chinese culture became important when some of the U.S. founders looked for resources that could be mobilized in their efforts to build a new nation after declaring independence from Great Britain.', mt:'', ref:'随着一部分美国开国元勋在宣布脱离英国独立建国后寻找可用于建设新国家的资源时，中国文化变得重要。' },
  { k:'seg_5_中西部_26', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Chinese contributions to early America were varied.', mt:'', ref:'中国对早期美国的贡献是多种多样的。' },
  { k:'seg_5_中西部_27', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In their efforts to cultivate personal virtue and to educate the younger generations to be virtuous, several Founding Fathers sought guidance from Confucian philosophy.', mt:'', ref:'几位开国元勋在培养个人美德和教育年轻一代成为有德之士的努力中，寻求获取儒家哲学思想的指导。' },
  { k:'seg_5_中西部_28', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The founders also adopted Chinese inventions to facilitate the social and economic development of colonies and introduced elements of Chinese agriculture to North America.', mt:'', ref:'开国元勋还应用了中国的发明，将中国农业经验引入北美，来促进殖民地的社会和经济发展。' },
  { k:'seg_5_中西部_29', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The timing of China’s impact on America’s founders is particularly significant.', mt:'', ref:'中国对美国开国元勋产生影响的时机尤为重要。' },
  { k:'seg_5_中西部_30', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Why did such American notables as Benjamin Franklin, Thomas Jefferson, George Washington, and John Adams focus their attention and insatiable curiosity on China?', mt:'', ref:'为什么像本杰明·富兰克林、托马斯·杰斐逊、乔治·华盛顿和约翰·亚当斯这样的美国重要人物都对中国充满了好奇，对中国十分关注？' },
  { k:'seg_5_中西部_31', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'As one of the most stable, and certainly the most long-lived civilization in the world, to the architects of the new, independent American nation China was the subject of intrigue and admiration.', mt:'', ref:'中华文明是世界上最稳定、当然也是历史最悠久的文明之一。对新生的独立的美国国家的开国元勋来说，中国是他们好奇和钦佩的对象。' },
  { k:'seg_5_中西部_32', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'When the storm clouds of revolution started to gather momentum, Franklin astutely promoted his theory of social progress by combining Confucian political ideas with the Western tradition of social progress.', mt:'', ref:'独立革命蓄势待发时，富兰克林将儒家的政治思想与西方的社会进步传统结合起来，巧妙地推广他的社会进步理论。' },
  { k:'seg_5_中西部_33', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Franklin and other statesmen would later apply this theory to craft the U.S.Constitution, thus solidifying the foundations of the nation’s political infrastructure.', mt:'', ref:'他和其他政治家后来应用这一理论制订了美国宪法，从而巩固了美国的政治基础。' },
  { k:'seg_5_中西部_34', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Chinese civilization provided an opportunity to fuse its social and political frameworks with notions of the European Enlightenment, supporting the Founding Fathers’ efforts to create a uniquely American tradition.', mt:'', ref:'中华文明提供了一个将美国社会和政治框架与欧洲启蒙运动思想相融合的机会，支持开国元勋努力创造独特的美国传统。' },
  { k:'seg_5_中西部_35', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'These same founders sought to establish a political identity that was distinct from European aristocratic traditions.', mt:'', ref:'他们寻求建立一种有别于欧洲贵族传统的政治身份。' },
  { k:'seg_5_中西部_36', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Facing British trade sanctions after the Revolutionary War, U.S. political leaders initiated efforts to build direct economic connections with China.', mt:'', ref:'独立战争结束后，面对来自英国的贸易制裁，美国的政治领导人开始设法与中国建立直接的经济联系。' },
  { k:'seg_5_中西部_37', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Robert Morris and George Washington were directly involved in the opening of trade with China with support from other American founders.', mt:'', ref:'在其他开国元勋的支持下，罗伯特·莫里斯（Robert Morris）和乔治·华盛顿直接参与了对华贸易的开启。' },
  { k:'seg_5_中西部_38', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'One important reason behind Thomas Jefferson’s quest for westward expansion through the acquisition of the Louisiana Purchase in 1803 was the search for a shortcut to China, and late in his presidency, he communicated the desirability of creating something like a U.S.-China policy.', mt:'', ref:'托马斯·杰斐逊通过1803年路易斯安那购地案寻求向西扩张的一个重要原因是寻找通往中国的捷径。在他总统任期的后期，他表达了制定类似美中政策的愿望。' },
  { k:'seg_5_中西部_39', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'IDEAS FROM THE EAST', mt:'', ref:'东方思想的影响' },
  { k:'seg_5_中西部_40', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'During the colonial era, the founders realized the value of Chinese civilization and applied certain Chinese ideas to improve social and economic life in the colonies.', mt:'', ref:'殖民时期，开国元勋意识到中华文明的价值，运用某些中国思想来改善殖民地人们的社会和经济生活。' },
  { k:'seg_5_中西部_41', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In the wake of the victory of the revolution, some main founders even looked to China as a guide for their new nation.', mt:'', ref:'独立战争胜利后，一些主要的开国元勋甚至把中国视为美国这个新生国家学习的典范。' },
  { k:'seg_5_中西部_42', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'They regarded China’s long agrarian tradition as a rich resource from which the newborn United States could learn valuable lessons.', mt:'', ref:'他们认为中国悠久的农业传统是一种丰富的资源，新生的美国可以从中汲取宝贵的经验。' },
  { k:'seg_5_中西部_43', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Chinese ideas, particularly Confucian moral philosophy, inspired the founders.', mt:'', ref:'开国元勋受到中国思想，尤其是儒家道德哲学的启发。' },
  { k:'seg_5_中西部_44', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Chinese ideas that the founders believed to be of great value to North America included certain practices of the Chinese imperial government, the social mobility based on meritocracy, and gentry spirits of community services.', mt:'', ref:'他们认为对北美有重大价值的中国思想包括中国政府的某些措施、基于任人唯贤制度的社会流动和贤德之士的公共服务精神。' },
  { k:'seg_5_中西部_45', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Franklin probably read The Morals of Confucius as early as his 1724–1726 stay in London.', mt:'', ref:'可能早在1724年至1726年间，富兰克林就在伦敦读过《孔子的道德》一书。' },
  { k:'seg_5_中西部_46', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'From his autobiography, it appears that—partially influenced by Confucius—Franklin focused on the cultivation of personal virtue as early as 1726.', mt:'', ref:'从自传中可以看出，富兰克林在一定程度上受到孔子的影响，早在1726 年他就注重培养个人品德。' },
  { k:'seg_5_中西部_47', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Confucius designed the path for virtuous perfection—from oneself to one’s family, to the state, and then to the whole empire.', mt:'', ref:'孔子设计了一条达到道德至善的道路，从个人到家庭，到国家，再到整个天下。' },
  { k:'seg_5_中西部_48', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In 1737, Franklin introduced this notion to American colonists.', mt:'', ref:'1737年，富兰克林向美国殖民者介绍了这一概念。' },
  { k:'seg_5_中西部_49', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Franklin agreed with Confucius that a man should not only cultivate personal virtues but also disseminate them to others—including political leaders.', mt:'', ref:'他赞同孔子的观点，即一个人不仅应该培养个人品德，还应该将这些美德传递给他人——包括政治领袖。' },
  { k:'seg_5_中西部_50', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In a 1749 letter to George Whitefield, one of the most influential of all colonial American clergy, Franklin advocated that knowledge of Confucian ideas could even foster social tranquility.', mt:'', ref:'1749年，在写给美国殖民地最有影响力的神职人员之一乔治·怀特菲尔德(George Whitefield)的信中，福兰克林主张了解儒家思想甚至可以促进社会安定。' },
  { k:'seg_5_中西部_51', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Confucius yearned to see people, especially rulers, adopt better morals and more compassion.', mt:'', ref:'孔子渴望看到人们，尤其是统治者，心怀怜悯，具有良好的道德情操。' },
  { k:'seg_5_中西部_52', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'For him, virtue was the foundation of a good and flourishing empire.', mt:'', ref:'对他来说，美德是一个国家长期存在、保持繁荣的基础。' },
  { k:'seg_5_中西部_53', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Confucius asserted that rulers should behave appropriately in court and at home because they would certainly be imitated.', mt:'', ref:'孔子主张统治者在朝堂上和家里应该举止得体，因为他们的一举一动都会被效仿。' },
  { k:'seg_5_中西部_54', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'During the Revolutionary War, Franklin worked hard to promote this important principle.', mt:'', ref:'独立战争期间，富兰克林努力倡导这一重要原则。' },
  { k:'seg_5_中西部_55', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'After the American victory, some veterans wanted permanent recognition for their triumph through formation of an order of hereditary knights.', mt:'', ref:'战争胜利后，一些退伍军人希望通过建立世袭的勋爵制度来永久认可他们的功绩。' },
  { k:'seg_5_中西部_56', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Franklin raised objections to this idea by using Confucius’s principle of social promotion.', mt:'', ref:'借用孔子的社会促进原则，他对此表示反对。' },
  { k:'seg_5_中西部_57', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Confucius maintained that law and punishment were the minimum requirements for order, but social harmony can only be achieved by virtuous behavior.', mt:'', ref:'孔子认为，法律和惩罚制度是秩序的最低要求，而社会和谐只能通过道德行为来实现。' },
  { k:'seg_5_中西部_58', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In his enormously influential Poor Richard’s Almanack, most of Franklin’s advice for readers stresses virtues such as hard work, frugality, and attention to family.', mt:'', ref:'富兰克林的《穷理查德年鉴》一书极具影响力。书中他给读者的大多数建议都强调勤奋、节俭和关注家庭等美德。' },
  { k:'seg_5_中西部_59', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Dr. Benjamin Rush, an ardent patriot, in a 1798 essay on education in the new republic, asserted that “the only foundation for a useful education in a republic is to be laid in Religion.', mt:'', ref:'本杰明·拉什博士是一位热情的爱国者。他在1798年发表的一篇关于新共和国教育的文章中断言，“共和国中有效教育的唯一基石是宗教。' },
  { k:'seg_5_中西部_60', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Without this there can be no virtue, and without virtue there can be no liberty, and liberty is the object and life of all republican governments.”', mt:'', ref:'没有宗教就没有美德，没有美德就没有自由，而自由是所有共和政府部门的目标和生命。”' },
  { k:'seg_5_中西部_61', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Having expressed his veneration for Confucianism that “reveals the attributes of the Deity,” Rush declared that he would rather see the opinions of Confucius “inculcated upon our youth, than see them grow up wholly devoid of a system of religious principles.”', mt:'', ref:'拉什对“揭示神祇的属性”的儒家思想表示崇敬之情，并宣布他宁愿看到孔子的思想“灌输给我们的年轻人，也不愿看到他们在成长过程中完全没有受到宗教原则体系的指引”。' },
  { k:'seg_5_中西部_62', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'John Adams, in a letter to Thomas Jefferson, criticized the English theologian and natural philosopher Joseph Priestley for ignoring Confucius in his writing.', mt:'', ref:'在给托马斯·杰弗逊的一封信中，约翰·亚当斯批评英国神学家和自然哲学家约瑟夫·普利斯特列（Joseph Priestley）在他的作品中忽视了孔子及儒家思想。' },
  { k:'seg_5_中西部_63', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'James Madison, father of the U.S.Constitution, hung a portrait of Confucius at his home.', mt:'', ref:'美国宪法之父詹姆斯·麦迪逊 (James Madison) 在家中悬挂了孔子的肖像画。' },
  { k:'seg_5_中西部_64', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'It was probably not a historical coincidence that Confucian moral ideals were respected in an era when some U.S. leaders sought to liberate American culture from what they viewed as failed European ideologies.', mt:'', ref:'在美国一些领导人寻求将美国文化从他们认为失败的欧洲意识形态中解放出来的同时，儒家的道德理想受到尊重，这可能不是一个历史巧合。' },
  { k:'seg_5_中西部_65', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'CHINESE TECHNOLOGY', mt:'', ref:'中国技术的影响' },
  { k:'seg_5_中西部_66', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Chinese innovations in areas such as heating technology, silk production, porcelain ware, manufacturing, navigation, canal construction, and even regarding the construction of the Great Wall of China found their way to North America via Europe.', mt:'', ref:'中国在诸如供暖技术、丝绸加工、瓷器烧制、制造业、航海业、运河开凿等方面的创新，甚至是关于中国长城修建的创新，都通过欧洲传到了北美。' },
  { k:'seg_5_中西部_67', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The founders realized this information could be used to promote social and economic development.', mt:'', ref:'开国元勋意识到这些技术都可以用来促进美国社会和经济发展。' },
  { k:'seg_5_中西部_68', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'In 1763, Benjamin Franklin, in an effort to promote the creation of a colonial silk industry, sent prominent American academic and Congregationalist minister Ezra Stiles copies of Chinese prints illustrating silk production.', mt:'', ref:'为了促进殖民地丝绸业的发展，1763年本杰明·富兰克林给著名的美国学者和公理会牧师埃兹拉·斯泰尔斯（Ezra Stiles）寄去了一些介绍中国丝绸生产工艺的印刷品。' },
  { k:'seg_5_中西部_69', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Scarce energy resources also stimulated Franklin to examine Chinese technology.', mt:'', ref:'能源资源稀缺也刺激富兰克林研究源自中国的技术。' },
  { k:'seg_5_中西部_70', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'By the 1740s, the growing colonial population resulted in noticeable diminishment of forests, which supplied fuel.', mt:'', ref:'到十八世纪四十年代，殖民地人口的不断增长导致可以提供燃料的森林面积显著缩小。' },
  { k:'seg_5_中西部_71', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The heating of houses was growing more expensive.', mt:'', ref:'房屋的取暖成本也就变得越来越高。' },
  { k:'seg_5_中西部_72', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Wood utilization was inefficient, and much of the heat—83 percent, Franklin estimated in many cases—was lost up chimneys.', mt:'', ref:'木材的利用率很低。据富兰克林估计，许多情况下，83%的热量都从烟囱流失了。' },
  { k:'seg_5_中西部_73', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Franklin carefully studied the Chinese technology of heating their houses in the cold winters.', mt:'', ref:'富兰克林仔细研究了中国人在寒冬为房屋供暖的技术。' },
  { k:'seg_5_中西部_74', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Franklin in part used these principles to invent the Pennsylvania Fireplace, which was later improved upon and became the famous Franklin Stove.', mt:'', ref:'他在一定程度上利用这些技术发明了宾夕法尼亚壁炉，后来加以改进成为著名的富兰克林炉。' },
  { k:'seg_5_中西部_75', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Better heating technology made the cold winter less harsh and induced more colonists to move to the North—which later contributed greatly to its development as a manufacturing center.', mt:'', ref:'取暖技术变得更先进，寒冷的冬天也变得不那么难熬，这就吸引了更多的殖民者搬到北方--这为以后大大促进了北方成为制造业中心做出了贡献。' },
  { k:'seg_5_中西部_76', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Franklin also carefully studied Chinese ship construction and publicized the Chinese practice of watertight compartment construction.', mt:'', ref:'富兰克林还仔细研究了中国的船舶建造技术，并宣传了中国的水密舱建造方法。' },
  { k:'seg_5_中西部_77', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'During the French and Indian War, 1754–1763, Franklin introduced the notion of a defensive wall—similar to the Great Wall of China—into public debate.', mt:'', ref:'在1754-1763年的法国-印第安人战争（French and Indian War）期间，富兰克林在公共辩论中引入了修建类似中国长城的此类防御设施的话题。' },
  { k:'seg_5_中西部_78', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'He maintained that building an American Great Wall was the most efficient way to protect the thirteen colonies.', mt:'', ref:'他坚持认为，修建美国式长城可以最有效地保护十三个殖民地。' },
  { k:'seg_5_中西部_79', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Franklin again raised the notion of the Great Wall during the Revolutionary War.', mt:'', ref:'独立战争期间，他再次提出了修建美式长城的建议。' },
  { k:'seg_5_中西部_80', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'A few Chinese technological innovations were also used to advance certain economic goals prior to American independence.', mt:'', ref:'美国独立之前，源自中国的一些技术创新也被用于推进某些经济目标。' },
  { k:'seg_5_中西部_81', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Some colonial leaders, for example, viewed porcelain manufacturing as essential to national economic self-reliance.', mt:'', ref:'例如，一些殖民地领导人认为瓷器烧制对殖民地发展经济自立极为重要。' },
  { k:'seg_5_中西部_82', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Chinese porcelain, like tea, had been a major colonial import.', mt:'', ref:'中国瓷器和茶叶一样，一直是殖民地的主要进口产品。' },
  { k:'seg_5_中西部_83', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Benjamin Rush was among the first who advocated building a porcelain factory in North America with the intent of overcoming American dependence on British imports.', mt:'', ref:'本杰明·拉什是主张在北美建立瓷器工厂的最早一批倡导者之一，目的是摆脱美国对英国进口商品的依赖。' },
  { k:'seg_5_中西部_84', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Gouverneur Morris, prominent founder of the republic, studied China’s Grand Canal.', mt:'', ref:'著名的共和国缔造者古弗尼尔·莫里斯曾研究过中国的京杭大运河。' },
  { k:'seg_5_中西部_85', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'With his encouragement, the New Yorkers built the Erie Canal, connecting New York to the Midwest.', mt:'', ref:'在他的鼓励下，纽约人开凿了伊利运河，将纽约市与中西部地区连接起来。' },
  { k:'seg_5_中西部_86', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The canal played a role in New York City’s rise, triggered an explosion in canal building, facilitated economic growth, and linked the Northeast with the Great Lakes region.', mt:'', ref:'这条运河在纽约市的崛起中发挥了作用，促使美国多地迅速开凿运河，促进了经济增长，并将美国东北地区与五大湖区连接起来。' },
  { k:'seg_5_中西部_87', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The colonists’ pursuit of domestic Chinese porcelain ware became a powerful call for patriotic support of American economic independence.', mt:'', ref:'殖民者寻求在美国国内烧制瓷器，成为支持美国经济独立的强有力的爱国号召。' },
  { k:'seg_5_中西部_88', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Franklin, in London when Rush was promoting colonial porcelain production, echoed this sentiment in a letter to his wife: “I am pleased to find so good progress made in the China Manufactory.', mt:'', ref:'当拉什在伦敦推广殖民地的瓷器生产时，富兰克林在给妻子的信中也表达了同样的感情:“我很高兴看到瓷器制造厂取得了如此巨大的进步。' },
  { k:'seg_5_中西部_89', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'I wish it Success most heartily.”', mt:'', ref:'我衷心祝愿它获得成功。”' },
  { k:'seg_5_中西部_90', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'The American China Manufactory in Philadelphia became noted for its quality, and more importantly, succeeded in cultivating patriotism as it challenged Britain’s monopoly of the product and indirectly contributed to the struggle for independence.', mt:'', ref:'位于费城的美国瓷器制造厂因产品质量而闻名。更重要的是，它成功地激发了爱国主义热情，因为它挑战了英国对瓷器的垄断，并间接地为独立斗争做出了贡献。' },
  { k:'seg_5_中西部_91', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Explicit examples of Chinese architectural influences are present in one of America’s most historic buildings.', mt:'', ref:'中式建筑对美国也产生了影响，最典型的例子就是一座最具历史意义的建筑物。' },
  { k:'seg_5_中西部_92', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Jefferson developed a new type of architecture by incorporating certain Chinese designs into his famous neoclassical-style home, Monticello.', mt:'', ref:'杰斐逊将某些中国设计元素融入他著名的新古典主义风格的住宅蒙蒂塞洛(Monticello)，从而形成了一种新的建筑风格。' },
  { k:'seg_5_中西部_93', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Jefferson used Chinese lattice in many buildings, including Barboursville, the Orange County, Virginia home he designed.', mt:'', ref:'他在许多建筑中都使用了中式格子，其中包括他设计的位于弗吉尼亚州奥兰治县巴伯斯维尔（Barboursville）的住宅。' },
  { k:'seg_5_中西部_94', ed:'5', stage:'初赛', dir:'英译汉', eng:'火山翻译', src:'Jefferson also planned to build a Chinese pavilion when he remodeled Monticello in the last decade of the eighteenth century.', mt:'', ref:'他在十八世纪最后十年改造蒙蒂塞洛时，也计划修建一座中式亭子。' },
  { k:'seg_6_决赛_1', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'原来“江湖中人”有颗细腻的心', mt:'The \'people in the rivers and lakes\' originally had a delicate heart.', ref:'My “Swordsman” Father' },
  { k:'seg_6_决赛_2', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'在我的童年记忆和道听途说中，爸爸是一个“江湖中人”。', mt:'In my childhood memories and hearsay, my father was a "man of the world".', ref:'From what I heard and remembered as a child, my father was a “swordsman”.' },
  { k:'seg_6_决赛_3', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'据我妈口述，当年隔壁邻居家进了小偷，被发现后，我爸抄起武器，也许是厨房的菜刀，也许是阳台的棍子，和邻居追出去了两里地，最后邻居跑不动了说算了吧，我爸甚为遗憾。', mt:'According to my mother\'s account, a thief broke into our neighbor\'s house years ago. After being discovered, my father grabbed a weapon, perhaps a kitchen knife or a balcony stick, and chased after the thief with the neighbor for two miles. In the end, the neighbor couldn\'t run anymore and gave up, which my father was very regretful about.', ref:'My mother used to tell me a story of how he once confronted a burglar who had broken into our neighbor’s house and pursued him for roughly one kilometer with a “weapon” – probably a kitchen knife or a balcony stick. He only stopped when the neighbor gave up and said it was not worth it, but he regretted letting the thief escape.' },
  { k:'seg_6_决赛_4', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'类似的故事我听过很多，足以拼凑出一幅江南小城热血青年的叱咤图景。', mt:'I have heard many similar stories, which can be pieced together to form a scene of hot-blooded young people in a small town in the south of the Yangtze River.', ref:'There were many other stories like that, which portrayed a valiant young man in a small town in southern China.' },
  { k:'seg_6_决赛_5', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'然而，“江湖中人”的人生经历流入那个平静如水的小城，就显得波澜不惊，平平无奇。他虽然不爱念书，但还是高中顺利毕业了；他虽然想当兵去打仗，但还是听家里安排进了工厂；他人生一大梦想是开拖拉机，但还是开起了轿车；', mt:'However, the life experiences of the "people in the rivers and lakes" flow into that calm and watery small town, which appears calm and unremarkable.Although he didn\'t like studying, he still graduated from high school smoothly; Although he wanted to join the army to fight, he still followed his family\'s arrangement and went to work in a factory; His biggest dream in life was to drive a tractor, but he ended up driving a car;', ref:'However, the life of “swordsman” in that peaceful town seemed dull and mundane. He was not fond of studying, but he managed to finish high school; he wanted to join the army, but he followed his parents’ plan and got a job in a factory; his biggest dream in life was to drive a tractor, but he settled for driving a car;' },
  { k:'seg_6_决赛_6', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'我想他是希望有个儿子能跟随他继续闯荡江湖的，但我是个从小不爱运动的阿囡……20多年后，他拥有了一只英武的黑色小狗，他简直视若己出——这是后话。', mt:'I think he hoped to have a son who could follow him to continue to explore the world, but I am a girl who has never liked sports since childhood… More than 20 years later, he has a brave black dog that he loves like his own - but that\'s another story.', ref:'I think he wished to have a son who could join him and carry on his intrepid adventures, but I was a girl who hated sports since childhood … More than two decades later, he had a brave black dog, which he cherished as his own child -- but that’s another story.' },
  { k:'seg_6_决赛_7', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'就像《流浪地球2》中的那个女孩有一段两分钟的数字人生，我记忆中也有一段可以反复迭代的童年。', mt:'Just like the girl in \'The Wandering Earth 2\' had a two-minute digital life, I also have a childhood memory that can be iterated repeatedly.', ref:'My childhood memory is like a digital clip that plays on repeat, just as the girl in The Wandering Earth II had.' },
  { k:'seg_6_决赛_8', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'那是小城最中心的位置，两条主干道的十字交会处，在20世纪90年代初，仍是一个铺着碎石的大操场。', mt:'That is the most central location in the small town, at the intersection of two main roads. In the early 1990s, it was still a large playground paved with broken stones.', ref:'It takes me back to the heart of a small town, where two main roads crossed. Back in the early 1990s, it was still a vast playground with gravel on the ground.' },
  { k:'seg_6_决赛_9', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'它也许有别的正式名字，但人们都喊它“大操场 ”，简单明了。', mt:'It may have another formal name, but people call it the \'big playground\', simple and clear.', ref:'It might have an official name, but natives simply called it “the big playground”.' },
  { k:'seg_6_决赛_10', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'这儿早已没有了各种集会，于是成为户外运动的好地方，比如，放风筝。', mt:'There are no more gatherings here, so it has become a good place for outdoor activities, such as flying kites.', ref:'It was no longer a place for gatherings, but for outdoor fun, such as kite flying.' },
  { k:'seg_6_决赛_11', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'关于此事的一种记忆是，爸爸每年都兴致勃勃地带我来大操场放风筝，一放就是一下午，我很开心；另一种则是，爸爸每年都带我看他放风筝，全场最嗨的就是他，经常风筝越飞越高，高到我都看不见了，爸爸就索性剪了绳子给它自由。', mt:'One memory about this is that my dad would bring me to the big playground every year to fly kites, and we would spend the whole afternoon there. I was very happy. Another memory is that my dad would bring me to watch him fly kites every year, and he was always the most excited one there. The kite would often fly higher and higher until I couldn\'t see it anymore, and my dad would just cut the string and let it fly freely.', ref:'I remember how my father would eagerly take me there every year to fly a kite. We would fly the kite for the entire afternoon and I was very, very happy. I also remember how he would show off his kite flying skills. He was the most thrilled one on the field. He often sent his kite so high that I couldn’t see it anymore. Then he would just cut the string and let it go.' },
  { k:'seg_6_决赛_12', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'我的童年拥有过很多个风筝，无一例外都随风而去。', mt:'My childhood had many kites, all of which flew away with the wind.', ref:'I had many kites in my childhood, and they all flew away with the wind, one by one.' },
  { k:'seg_6_决赛_13', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'我一直觉得我妈是个文艺女青年，爱看书爱看电影，教我写作文监督我弹琵琶，而我爸的主职是带我瞎玩。', mt:'I have always felt that my mother is a literary and artistic young woman who loves to read books and watch movies, teaches me to write compositions and supervises me to play pipa, while my father\'s main job is to let me play around.', ref:'I always thought my mother was a literary young woman who relished reading books and watching movies. She taught me how to write essays and supervised me playing the pipa, while my father’s main role was to take me out for fun.' },
  { k:'seg_6_决赛_14', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'小学的一个暑假，妈妈给我在少年宫报了书法班，学费都交了，上了两堂课后，只记得那年夏天好热，西瓜好甜，午觉好香，我说我不想去上课了，我爸说他也不想送我——一拍即合 。', mt:'One summer vacation in elementary school, my mother signed me up for a calligraphy class at the Youth Palace. After paying the tuition and attending two classes, I only remember how hot the summer was, how sweet the watermelon was, and how fragrant the nap was.I said I didn\'t want to go to class anymore, and my dad said he didn\'t want to send me either - we agreed on this.', ref:'One summer vacation in elementary school, my mother enrolled me in a calligraphy class at the Children’s Palace. She paid the tuition fee, but after two classes, I only remembered how hot that summer was, how sweet the watermelon was, and how pleasant the nap was. I said I didn’t want to go to the calligraphy class anymore, and my father said he didn’t want to take me either -- we were on the same wavelength!' },
  { k:'seg_6_决赛_15', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'这直接导致我现在的一手字仍停留在小学水平 。', mt:'This directly leads to my current handwriting still being at an elementary school level.', ref:'Quitting the calligraphy class resulted in my handwriting still staying at the elementary school level.' },
  { k:'seg_6_决赛_16', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'本以为“江湖中人”会表里如一地从冲动的青年变成中年，然后我长大，他老去，风采依旧。', mt:'I thought that the \'people in the rivers and lakes\' would be consistent from impulsive youth to middle age, but as I grew up, he aged, and his style remained the same.', ref:'I thought this “swordsman” would naturally turn from an impetuous youth into a calm-minded middle-aged man, and then I grew up, he grew old, but still charming.' },
  { k:'seg_6_决赛_17', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'但有一件事，让我认识到了爸爸的另一面。', mt:'But there is one thing that made me realize another side of my dad.', ref:'But there was one thing that made me realize another aspect of my father.' },
  { k:'seg_6_决赛_18', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'那是小学六年级，我的青春期即将到来。', mt:'That was sixth grade, my adolescence was about to come.', ref:'It was in the sixth grade of elementary school, and my puberty was about to start.' },
  { k:'seg_6_决赛_19', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'在20世纪和21世纪相交的年代，女孩的青春期隐秘而不可言说。', mt:'In the era where the 20th and 21st centuries intersect, the girl\'s adolescence is secretive and unspeakable.', ref:'At the turn of the 21st century, girls’ puberty was secretive and unspeakable.' },
  { k:'seg_6_决赛_20', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'学校开设了生理卫生课，却是男生女生分开上，老师播放了科普视频，再多就语焉不详。', mt:'The school has set up a course on reproductive health, but it is taught separately for boys and girls. The teacher played an educational video, but didn\'t provide much explanation beyond that.', ref:'The school offered a health class, but it was separate for boys and girls. The teacher played a popular science video, and then said nothing more.' },
  { k:'seg_6_决赛_21', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'总之，谁也没放在心上，我也照旧理着短发、 穿着运动服，爬高就低。', mt:'Anyway, no one cared, and I continued to wear my short hair and sportswear, climbing high and low.', ref:'In short, no one cared about it. I still had short hair, wore sportswear, and climbed up and down like a boy.' },
  { k:'seg_6_决赛_22', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'一个下午，我去新华书店，让我爸跟着，毕竟他是名副其实的金主爸爸。', mt:'One afternoon, I went to Xinhua Bookstore and had my dad follow me, after all, he is a real gold daddy..', ref:'One afternoon, I went to the Xinhua Bookstore and asked my father to join me -- after all, he was the one who footed my bills.' },
  { k:'seg_6_决赛_23', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'我想买一套《还珠格格》小说，我爸递过来一套《成长的烦恼》。', mt:'I want to buy a set of \'Huan Zhu Ge Ge\' novels, but my dad handed me a set of \'Growing Pains\'.', ref:'I wanted to buy a set of novels called My Fair Princess , but my father handed me a set of Growing Pains .' },
  { k:'seg_6_决赛_24', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'我很不高兴，我压根儿没烦恼，但金主爸爸坚持给我买了这套书——青春期性教育丛书—— 这是我过了好几天无聊翻阅后才发现的。', mt:'I am very unhappy. I have no worries at all, but my sugar daddy insisted on buying me this set of books - a series on adolescent sex education - which I only discovered after flipping through them for several days out of boredom.', ref:'I was very displeased. I had no “pains” at all, but my daddy insisted on buying me this set of books - - a series of sex education books for puberty -- which I discovered only after flipping through them casually several days later.' },
  { k:'seg_6_决赛_25', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'从初中到高中，这套书我不知道翻了多少遍， 从生理到心理，答疑解惑。', mt:'From junior high school to high school, I don\'t know how many times I have flipped through this set of books, from physiology to psychology, answering questions and solving doubts.', ref:'From junior high school to high school, I don’t know how many times I perused this set of books. From physiology to psychology, they answered my questions and solved my doubts.' },
  { k:'seg_6_决赛_26', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'20多年前，小城的新华书店以教辅为主，名著为辅，天知道我爸是怎么找到的。', mt:'More than 20 years ago, the Xinhua Bookstore in the small town mainly focused on teaching materials, supplemented by classics. God knows how my dad found it.', ref:'Over two decades ago, the Xinhua Bookstore in that small town sold mainly teaching guidebooks and occasionally literary masterpieces.God knows how my father found those books.' },
  { k:'seg_6_决赛_27', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'来，我离家北上念大学，来到一个更大的花花世界，我爸就更操心了。', mt:'Later, when I went to college in the north and entered a bigger world, my dad became even more worried.', ref:'Later, I left home and went north for college in a bigger city. My father became more worried.' },
  { k:'seg_6_决赛_28', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'当年那个目送风筝远去的青年，其实内心是恋恋不舍的吧。', mt:'The young man who watched the kite fly away that year was actually reluctant to part with it.', ref:'The young man who once watched his kite soar into the distance back in the years must harbor a heart filled with reluctance.' },
  { k:'seg_6_决赛_29', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'一个“江湖中人”，原来有颗如此细腻的心。', mt:'A "person in the arena", originally had such a delicate heart.', ref:'The “swordsman” actually had such a subtle sensibility.' },
  { k:'seg_6_决赛_30', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'最近，爸爸在老家宅基地建房，我作为小股东和全场学历最高者，拥有审美方向的最终决定权。', mt:'Recently, my father has been building a house on our ancestral land. As a minor shareholder and the most educated person present, I have the final say in matters of aesthetics.', ref:'Recently, my father built a house on his homestead land in the countryside. As a minor shareholder and the most learned person in the family, I had the final say on the aesthetic vision.' },
  { k:'seg_6_决赛_31', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'众所周知，农村自建房总是丑得各有千秋，我在千里之外，很担忧前方的爸爸被带跑偏。', mt:'As we all know, self-built houses in rural areas are always uniquely ugly. I am worried that my father ahead may have gone astray, even though he is thousands of miles away.', ref:'We all know how rural self-built houses tend to be unsightly in various ways. I was worried that my father would succumb to the influence of others from afar.' },
  { k:'seg_6_决赛_32', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'让我惊讶的是，他再次显示出了惊人的细致度和宽容度，一切出奇顺利。', mt:'I was surprised that he once again showed amazing meticulousness and tolerance, and everything went surprisingly smoothly.', ref:'To my delight, he once again displayed remarkable meticulousness and open-mindedness, and everything went without a hitch.' },
  { k:'seg_6_决赛_33', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'我说喜欢大落地窗，他给我开了个2.4米高的大窗户；经过别人家的窗户，他觉得好看且经我批准后，就记录下布局、尺寸和比例，在几十种方案中反复比对挑选。', mt:'I said I like big floor-to-ceiling windows, and he opened a 2.4-meter-high window for me; when passing by someone else\'s window, he thought it looked good and, with my approval, recorded the layout, size, and proportion, and repeatedly compared and selected among dozens of options.', ref:'I said I fancied large floor-to-ceiling windows, and he made me a grand window that stood 2.4 meters tall! He spotted someone else’s window and liked it. After getting my approval, he noted down the layout, size and proportion, and repeatedly compared and chose among dozens of schemes.' },
  { k:'seg_6_决赛_34', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'我说要白墙黑瓦，他找了多种外墙漆供选择； 趁我回家时，全家去现场挑地砖和墙砖，我坚持要黯淡无光的柔光砖，称这是当下流行，且不要过门石要全屋通铺，他虽然没太明白这好看在哪里，但还是信了我……', mt:'I said I wanted white walls and black tiles, and he found many kinds of exterior paint to choose from. While I was away, the whole family went to the site to choose floor tiles and wall tiles. I insisted on using dim and light soft tiles, calling it a current trend, and I didn\'t want a threshold, I wanted the whole house to be paved. Although he didn\'t quite understand why it looked good, he still believed me...', ref:'I said I wanted white walls and black tiles, and he sourced a variety of exterior wall paints for me to pick from. When I returned home, the whole family went to hand-select floor tiles and wall tiles. I insisted on using matte tiles that were dull and dim, saying that this was the latest trend. And I didn’t want a threshold stone but wanted the whole house to be tiled uniformly. He didn’t quite grasp why this might look good, but he still trusted' },
  { k:'seg_6_决赛_35', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'还记得那只英武的小狗吗？', mt:'Do you remember that brave little dog?', ref:'me Didn’t I mention that my father had a brave little dog?' },
  { k:'seg_6_决赛_36', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'它在今年清明节后不久以13岁高龄去世。', mt:'It passed away at the age of 13 shortly after this year\'s Qingming Festival.', ref:'It died at the age of 13 shortly after this year’s Qingming Festival.' },
  { k:'seg_6_决赛_37', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'小狗的一切衣食住行，包括发型，曾经都是我爸一手打理，小狗也因此拥有全小区最时尚的尾巴。', mt:'All aspects of the dog\'s clothing, food, housing, and transportation, including hairstyle, were once taken care of by my father, and the dog therefore has the most fashionable tail in the entire community.', ref:'My father used to pamper it with everything from its outfits and meals to its shelter and transport. The dog also had the most fashionable tail in the neighborhood.' },
  { k:'seg_6_决赛_38', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'小狗去世后，我爸开车载上它和它所有的玩具和零食，在一条小溪边的竹林里，安葬了它， 并用几块石头堆了一个小标记。', mt:'After the puppy died, my dad drove it with all its toys and snacks to a bamboo forest by a small stream, buried it, and piled a small marker with a few stones.', ref:'After the dog died, my father drove it along with all its playthings and treats. He buried it in a bamboo forest by a creek and piled up a small marker with a few stones.' },
  { k:'seg_6_决赛_39', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'今年五一假期，我回家了，爸爸带我来到那条小溪边，去看望小狗。', mt:'During this year\'s May Day holiday, I went home and my father took me to visit the little dog by the creek.', ref:'This May Day holiday, I went home and my father took me to the creek to pay our respects.' },
  { k:'seg_6_决赛_40', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'他从口袋里掏出了饼干和糖果，又在路边摘了一束白色的小野花。', mt:'He took out cookies and candies from his pocket, and also picked a bunch of white wildflowers on the roadside.', ref:'He pulled out some biscuits and candies from his pocket and picked a bunch of white wildflowers from the roadside.' },
  { k:'seg_6_决赛_41', ed:'6', stage:'决赛', dir:'汉译英', eng:'GPT-3.5-turbo', src:'那天下着江南最常见的蒙蒙细雨，头发已经花白但身材依旧保持良好的爸爸，在如雾一般的水汽中，突然让我看到了细嗅蔷薇的画面。', mt:'That day it was drizzling with the most common misty rain in the south of the Yangtze River. My dad, whose hair had turned white but still maintained a good figure, suddenly showed me a picture of sniffing roses in the misty water vapor.', ref:'It was a drizzly day with the typical rain of the south. My father, whose hair has turned gray but who still keeps a fit figure, stood in the hazy mist, which suddenly reminded me of the verse by Siegfried Sassoon: “In me the tiger sniffs the' },
  { k:'seg_7_决赛_1', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'何园', mt:'He Garden', ref:'Heyuan Garden' },
  { k:'seg_7_决赛_2', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'何园作为一处有意设计的景观，有其明确的立意、构思、 布局，虽历经百余年的沧桑变化，其整体特征至今仍清晰可辨，将其置于中国古典园林体系中审视，仍独具特色。', mt:'As a deliberately designed landscape, He Garden has its clear intentions, concepts, and layout. Despite over a century of changes, its overall characteristics are still clearly discernible. When viewed within the context of the Chinese classical garden system, it remains unique.', ref:'As a designed landscape, Heyuan Garden has its clear concept, design and layout. Although it has been subject to more than one hundred years of change, its overall characteristics are still clearly identifiable. The character of Heyuan Garden demonstrates many innovations in the craft of landscape gardening.' },
  { k:'seg_7_决赛_3', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'由于地处中国南方和北方之间，扬州的园林风格融合了北方园林与江南私家园林的特征，展现出独特的面貌。', mt:'Due to its location between southern and northern China, the garden style of Yangzhou combines the characteristics of northern gardens and private gardens in the Jiangnan region, showcasing a unique appearance.', ref:'Due to its location between southern and northern China, Yangzhou\'s garden style combines the characteristics of northern gardens and private gardens in the Jiangnan area, showing a unique look.' },
  { k:'seg_7_决赛_4', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'著名园林专家陈从周先生指出：“扬州园林综合了南北的特色，自成一格，雄伟中寓明秀，得雅健之致。”', mt:'The famous garden expert Mr. Chen Congzhou pointed out: "The gardens of Yangzhou combine the characteristics of both the north and the south, forming their own unique style. They are majestic yet elegant, achieving a refined and vigorous charm."', ref:'The famous garden expert Chen Congzhou pointed out: "The gardens of Yangzhou combine the characteristics of both the North and the South, forming a unique style of their own. They entail dainty gracefulness in magnificent bodies—or, in literary jargon, write subtle heartthrobs with a robust brush."' },
  { k:'seg_7_决赛_5', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'扬州园林多与住宅很好地结合，大多园林中部建造水池， 水池旁边堆叠假山，厅堂位于水池边的重要位置，周围点缀亭台楼阁等建筑，并以花墙山石、树木花卉形成园林之间的间隔，创造具有层次变化的景色。 清代中叶，扬州园林的主人大多为富商，园林不仅是他们居住的场所，更是展示富有、追求风雅的社交空间，因此在风格、材料和工艺上极为注重奢华，建筑高敞华丽，花木品类丰富，室内外装修精致，叠石筑山的造诣尤其突出 。', mt:'The gardens of Yangzhou are often well integrated with residences, with most gardens featuring a pond in the center. Beside the pond, rockeries are stacked, and halls are located in important positions by the pond. The surroundings are adorned with pavilions, towers, and other buildings, with flower walls, rocks, trees, and flowers creating intervals between the gardens, thus creating scenery with layered variations. In the mid-Qing Dynasty, most of the owners of the gardens in Yangzhou were wealthy merchants. The gardens were not only their residences but also social spaces to showcase their wealth and pursuit of elegance. Therefore, great attention was paid to luxury in terms of style, materials, and craftsmanship. The buildings were tall and magnificent, the variety of flowers and plants was abundant, the interior and exterior decorations were exquisite, and the skill in rockery construction was particularly outstanding.', ref:'Yangzhou gardens are well integrated with residential buildings. Most of the large gardens in Yangzhou feature a pond in the centre with rockwork around it while pavilions become architectural centrepieces. The relationship between ponds and pavilions must be carefully choreographed. The scenery in large gardens is segmented with walls, rockwork and plants to conjure up multi-layered and variegated views. Exotic rocks are erected by the pond, pavilions and belvederes are scattered but ultimately connected by a circuitous walkway. In the mid-Qing Dynasty, most of the owners of Yangzhou gardens were wealthy merchants. The gardens were not only their living spaces but also social venues to showcase their wealth and pursuit of elegance. As a result, great emphasis was placed on luxury in style, materials, craftsmanship. The architecture was grand and ornate, the variety of plants and flowers was abundant, the interior and exterior decorations were exquisite, and the art of rock stacking and mountain building was particularly remarkable.' },
  { k:'seg_7_决赛_6', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'清代中叶，扬州园林的主人大多为富商，园林不仅是他们居住的场所，更是展示富有、追求风雅的社交空间，因此在风格、材料和工艺上极为注重奢华，建筑高敞华丽，花木品类丰富，室内外装修精致，叠石筑山的造诣尤其突出 。', mt:'In the mid-Qing Dynasty, most of the owners of the gardens in Yangzhou were wealthy merchants. The gardens were not only their residences but also social spaces to showcase their wealth and pursuit of elegance. Therefore, great attention was paid to luxury in terms of style, materials, and craftsmanship. The buildings were tall and magnificent, the variety of flowers and plants was abundant, the interior and exterior decorations were exquisite, and the skill in rockery construction', ref:'In the mid-Qing Dynasty, most of the owners of Yangzhou gardens were wealthy merchants. The gardens were not only their living spaces but also social venues to showcase their wealth and pursuit of elegance. As a result, great emphasis was placed on luxury in style, materials, craftsmanship. The architecture was grand and ornate, the variety of plants and flowers was abundant, the interior and exterior decorations were exquisite, and the art of rock stacking and mountain building was' },
  { k:'seg_7_决赛_7', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'清代乾隆年间成书的《扬州画舫录》就有“扬州以名园胜，名园以叠石胜”的评价。', mt:'The "Yangzhou Huafang Lu," written during the Qianlong period of the Qing Dynasty, contains the evaluation "Yangzhou is renowned for its famous gardens, and the famous gardens are renowned for their rockeries."', ref:'Yangzhou Huafang Lu (The record of the painted pleasure boats of Yangzhou) written during the Qianlong reign of the Qing Dynasty, records that, "Yangzhou is renowned for its famous gardens, and these gardens are celebrated for their rock formations."' },
  { k:'seg_7_决赛_8', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'此外，清代的扬州是中国对外贸易的主要商业城市之一， 商业上的交往使得许多西方园林、建筑的做法传入并被吸收到扬州园林之中，形成了私家园林中西合璧的独特风貌 。', mt:'In addition, during the Qing Dynasty, Yangzhou was one of the main commercial cities for foreign trade in China. The commercial interactions led to the introduction and incorporation of many Western garden and architectural practices into Yangzhou gardens, creating a unique blend of Chinese and Western styles in private gardens.', ref:'In addition, during the Qing Dynasty, Yangzhou was one of China\'s major commercial cities for foreign trade. This commercial interaction led to the introduction and assimilation of many Western gardening and architectural practices into the gardens of Yangzhou, resulting in a unique blend of Eastern and Western styles in private gardens.' },
  { k:'seg_7_决赛_9', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'何园作为一处晚清扬州私家住宅园林，具有以下突出特征 。', mt:'He Garden, as a private residential garden in late Qing Dynasty Yangzhou, has the following prominent features.', ref:'Heyuan Garden, as a private residential garden in the late Qing Dynasty Yangzhou, possesses the following prominent characteristics.' },
  { k:'seg_7_决赛_10', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'寄情山水，以小寓', mt:'Finding solace in nature, expressing the grand through the small.', ref:'Idealised miniature landscape and showing the large in the small' },
  { k:'seg_7_决赛_11', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'营造园林意境是中国古典园林审美的最高标准，园林中的山池花木、亭台楼阁，每一处景物都需要传达造园者的情感和精神追求。', mt:'Creating a garden atmosphere is the highest standard of aesthetics in Chinese classical gardens. Every scene in the garden, including mountains, ponds, flowers, trees, pavilions, and towers, needs to convey the emotions and spiritual pursuits of the garden\'s creator.', ref:'To create an artistic conception is the highest standard of Chinese classical garden aesthetics. The artificial mountains, ponds, plants, and buildings need to convey the emotional and spiritual interests of the garden owners.' },
  { k:'seg_7_决赛_12', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'何园的整体构思和园林营建充分体现了中国古典园林的这一特性，园林意境突出、景观象征性丰富。', mt:'The overall design and construction of He Garden fully embody this characteristic of Chinese classical gardens, with a prominent artistic conception and rich symbolic landscapes.', ref:'In this way Chinese gardens are idealised miniature (natural) landscapes. The overall concept and construction of Heyuan Garden fully embodies this characteristic of Chinese classical gardens, with outstanding artistic conception and rich symbolic landscapes.' },
  { k:'seg_7_决赛_13', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'园主何维键在任时目睹清朝衰败屈从外强，辞官卸任后建造园林以寄情山水，并将其命名为“寄啸山庄”以表达对清廷朝政的不满。', mt:'When the garden owner He Weijian witnessed the decline of the Qing Dynasty and its submission to foreign powers, he resigned from his official position and built a garden to find solace in nature. He named it "Jixiao Villa" to express his dissatisfaction with the Qing court\'s governance.', ref:'When He Weijian was in office, he witnessed the decline of the Qing government and its submission to foreign powers. After resigning, he built a garden as a retreat, and named it Whistling Scholar\'s Mountain Retreat to express his dissatisfaction with the government.' },
  { k:'seg_7_决赛_14', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'所谓“山庄”，即是一座以古代“海上仙山”传说为蓝本营建的园林。', mt:'The so-called "mountain villa" is a garden built based on the ancient legend of the "immortal mountains on the sea."', ref:'The so-called "mountain retreat" is a garden built according to the Chinese ancient legend of "sacred mountains in the sea".' },
  { k:'seg_7_决赛_15', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'何园的主花园利用水池象征茫茫大海，池西堆筑湖石假山象征海上仙山，假山突出水岸，山上种植两株高大挺拔的白皮松，增加了神山的意境。', mt:'The main garden of He Garden uses a pond to symbolize the vast ocean. To the west of the pond, a rockery made of lake stones symbolizes the fairy mountain in the sea. The rockery protrudes from the water\'s edge, and two tall and straight white pines are planted on the mountain, enhancing the mystical atmosphere of the mountain.', ref:'The main garden uses the pond to symbolize the sea. The artificial mountain in the west of the pond symbolises the sacred mountains in the sea. The artificial mountain stands out from the waterfront, with two tall white bark pines planted on the mountain, enhancing the atmosphere of the "sacred mountains".' },
  { k:'seg_7_决赛_16', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'水池中心建造方亭，被称为“小方壶”，具有海上神山仙阁的寓意。', mt:'A square pavilion was built in the center of the pool, called "Little Fanghu," symbolizing a fairy pavilion on a mythical mountain in the sea.', ref:'A square pavilion stands in the east of the pond. lt is called "Xiao Fanghu" (the small square pot, and "Fanghu" is said to be the name of a sacred mountain, one of the three sacred mountains of the Bohai Sea in Chinese mythology) in Chinese traditional garden, symbolising the dwelling place for immortals.' },
  { k:'seg_7_决赛_17', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'何园东北部还利用“旱园水作”的手法，即利用卵石的纹理变化铺装园林地面，形成“无水但有水意”的景观，地面上有四面通透的建筑，营造船浮于海的意象，与整个园林海上仙山的境界融为一体。', mt:'The northeastern part of He Garden also uses the technique of "dry garden with water effects," which utilizes the texture changes of pebbles to decorate the garden ground, creating a landscape that is "without water but with the sense of water." There are buildings with open views on all sides on the ground, creating the imagery of a boat floating on the sea, blending seamlessly with the entire garden\'s realm of an immortal mountain on the sea.', ref:'In addition, the northeastern part of Heyuan Garden uses the method of "hanyuan shuizuo" (a water-less garden is made to look like water-bound), which uses pavement texture changes to form an imagination of watery landscape with little or no water. A hall with windows on four sides sits in the court. With the ground at the foot of the hall\'s stairway paved with a mixture of pebbles, broken bricks and tiles in patterns, it aims to create the appearance of a ship floating on the sea.' },
  { k:'seg_7_决赛_18', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'此外，在整个何园中，利用花窗泄景、半壁亭台、贴墙作山、环阁凿池等手法，都是希望创造以小寓大，在有限中创造无限的景观效果。', mt:'In addition, throughout He Garden, techniques such as using flower windows to reveal scenery, half-wall pavilions, building mountains against walls, and digging pools around pavilions are all aimed at creating a grand effect in a small space, creating infinite scenery within limited confines.', ref:'In addition, Heyuan Garden also uses "borrowed- view" lattice windows, half-wall pavilions, wall- mounting mountains, ring-shaped chiseled pools, to create unlimited landscape effects in limited spaces.' },
  { k:'seg_7_决赛_19', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'院落重重，以园环居何园是一处典型的中国古典住宅园林，园林坐北朝南面积约为1.15万平方米，其中建筑面积约为6000平方米，具有清代中后期私家园林建筑密度较高的特征。', mt:'Courtyards upon courtyards, surrounded by gardens. Heyuan is a typical Chinese classical residential garden. The garden faces south and covers an area of approximately 11,500 square meters, with a building area of about 6,000 square meters, characterized by the high density of private garden buildings from the mid to late Qing Dynasty.', ref:'Full of courtyards, gardens surrounding residential spaces Heyuan Garden is a typical Chinese classical residential garden. The garden faces south and covers an area of about 11,500 square metres, including a construction area of about 6,000 square metres. The high density of buildings is a feature of the private gardens in the middle and late Qing dynasty.' },
  { k:'seg_7_决赛_20', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'何园是一处典型的中国古典住宅园林，园林坐北朝南面积约为1.15万平方米，其中建筑面积约为6000平方米，具有清代中后期私家园林建筑密度较高的特征。', mt:'Heyuan is a typical Chinese classical residential garden. The garden faces south and covers an area of approximately 11,500 square meters, with a building area of about 6,000 square meters, characterized by the high density of private garden buildings from the mid to late Qing Dynasty.', ref:'residential garden. The garden faces south and covers an area of about 11,500 square metres, including a construction area of about 6,000 square metres. The high density of buildings is a feature of the private gardens in the middle and late Qing dynasty. The external space of Heyuan Garden is mainly' },
  { k:'seg_7_决赛_21', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'何园主要通过院落来组织空间，利用围墙将园林划分成十余个大小不同的庭院，再通过门洞、长廊、花窗等串连交通和引导视线，借助池山、植物创造景观层次，减弱建筑带来的限定感，营造无限的自然境界。', mt:'Heyuan mainly organizes space through courtyards, using walls to divide the garden into more than ten courtyards of different sizes. It then connects and guides the view through doorways, long corridors, and flower windows, creating landscape layers with ponds, hills, and plants to reduce the sense of limitation brought by buildings and create an infinite natural realm.', ref:'The external space of Heyuan Garden is mainly made up of courtyards. More than ten courtyards of different sizes are created via using walls. Circulation is facilitated through doorways, long covered walkways, lattice windows and other elements to guide the line of sight. Ponds, rockeries and plants are used to soften the sense of enclosure established by the architecture and to create an infinite natural real.' },
  { k:'seg_7_决赛_22', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'整个园林以园居院落为中心，北部布置东、西两座花园， 西南有赏月楼小花园，东南有片石山房花园，形成了居住空间居中、山水游赏空间环绕的整体格局。', mt:'The entire garden is centered around a residential courtyard, with two gardens arranged to the north, one to the east and one to the west. In the southwest, there is a small garden with a moon- viewing pavilion, and in the southeast, there is a garden with a rockery. This creates an overall layout where the living space is in the center, surrounded by scenic areas for enjoying the landscape.', ref:'The residential area is in the centre of the complex, with East and West gardens arranged in the north, Shangyue Building (Moon-Viewing Building) yard in the southwest, and the Small-Rock Mountain Retreat garden in the southeast. This forms the overall pattern of living spaces surrounded by gardens.' },
  { k:'seg_7_决赛_23', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'这极大丰富了住宅园林的景观变化，不但继承了中国传统住宅园林“前宅后园”或“宅旁设园”的基本传统，又具有独特性和创造性。', mt:'This greatly enriched the landscape variation of residential gardens, not only inheriting the basic tradition of Chinese traditional residential gardens with "front residence and back garden" or "garden beside the residence," but also possessing uniqueness and creativity.', ref:'The layout positively enriches the landscape experience of the living spaces. Heyuan Garden not only inherits the basic principles of traditional Chinese residential gardens, such as "front-house- back-garden" or "garden-beside-house" but also has its own unique and creative qualities.' },
  { k:'seg_7_决赛_24', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'立体交通，居游两宜', mt:'Three-dimensional transportation, suitable for both living and traveling', ref:'The three-dimensional walking system providing spaces for both living and sightseeing' },
  { k:'seg_7_决赛_25', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'何园在处理居与游的关系方面具有独到之处，除了“以园环居”的布局特征之外，另一创造便是全园的立体交通。', mt:'Heyuan Garden has unique features in handling the relationship between residence and leisure. In addition to the layout characteristic of "surrounding the residence with the garden," another innovation is the three-dimensional transportation throughout the entire garden.', ref:'Heyuan Garden is unique in dealing with the relationship between residence and recreation. In addition to the "residential-area-surrounded-by- gardens" layout, another creative aspect is the three-dimensional walking system—the Double- Level Covered Walkway.' },
  { k:'seg_7_决赛_26', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'何园在建造之初就设计了复道回廊，解决了园林内部相互联络的问题，串连了园林的主体建筑和花园，同时提供了半室外的遮风避雨的空间，满足居住者在园内的日常行走需要。', mt:'At the time of its construction, He Garden was designed with a double-decked corridor, solving the problem of internal communication within the garden. It connected the main buildings and the garden, while also providing a semi-outdoor space for shelter from wind and rain, meeting the daily walking needs of the residents within the garden.', ref:'When Heyuan Garden was built, the owner designed a double-floored covered walkway to solve the problem of interconnecting different sections. The main buildings and yards were connected via the walkway. The walkway provides a semi-outdoor sheltered space for the residents during their daily movement around the complex.' },
  { k:'seg_7_决赛_27', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'复道回廊不仅平面上曲折迂回，立面上也高低错落，创造了重要的观景线路和视角，形成了独特的景观体验，行走在回廊里仿佛置身中国卷轴画中，景观画面依次展开，引人入胜。', mt:'The covered walkways and corridors not only twist and turn on the horizontal plane but also vary in height on the vertical plane, creating important viewing routes and perspectives. This forms a unique landscape experience, making one feel as if they are walking within a Chinese scroll painting, with the scenic views unfolding one after another, captivating the viewer.', ref:'The walkway not only follows a complex route in plan, but changes in height. The complex spatial arrangement creates varied view lines and perspectives, creating a unique landscape experience. Walking along these pathways, the visitor seems to be in a Chinese scroll painting, with fascinating landscape images unfolding before them.' },
  { k:'seg_7_决赛_28', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'复道回廊本身也是重要的景观界面，西园中的回廊高两层，环抱水池，加以栏杆、花窗的多样变化，营造了精致典雅的园林立面。', mt:'The covered walkways and corridors themselves are also important landscape interfaces. The corridors in the western garden are two stories high, surrounding the pool, with various changes in railings and flower windows, creating an exquisite and elegant garden facade.', ref:'The Double-Level Walkway itself also forms an important landscape interface. The cloister in the West Garden is two storeys high, encircling the pond, with varied railings and lattice windows creating a refined and elegant garden facade.' },
  { k:'seg_7_决赛_29', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'长廊是中国传统园林中的重要元素，而何园在继承传统的同时又有所创新，以复道回廊为核心的立体交通系统在中国传统私家园林中别具一格，是江南园林中的孤例。', mt:'The long corridor is an important element in traditional Chinese gardens, and He Garden, while inheriting tradition, also innovates. Its three- dimensional transportation system, centered on the double-decked corridor, is unique among traditional private gardens in China and stands as a singular example in Jiangnan gardens.', ref:'The covered walkway is an important element in Chinese traditional gardens. Heyuan Garden inherits this tradition while at the same time innovating. The three-dimensional walking system centred on the Double-Level Walkway is unique in traditional Chinese private gardens and is a unique example in Jiangnan gardens.' },
  { k:'seg_7_决赛_30', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'中西合璧，以人为本', mt:'East meets West, people-oriented', ref:'The combination of Chinese and Western styles for a people-oriented design' },
  { k:'seg_7_决赛_31', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'晚清时期，随着中西方文化交流的增多，扬州的园林建筑也受到西方影响。 何园主人何维键曾在海关任职并有与洋人共事的经历，因此他在建造何园的时候引入了许多西洋元素，将其与中国传统园林的形制相互融合，更好地满足居住和游赏的需求 。', mt:'During the late Qing Dynasty, with the increase in cultural exchanges between China and the West, the garden architecture in Yangzhou was also influenced by the West. The owner of He Garden, He Weijian, once worked at customs and had experience working with foreigners. Therefore, when he built He Garden, he introduced many Western elements and integrated them with the traditional Chinese garden style to better meet the needs of living and sightseeing.', ref:'In the late Qing dynasty, with the increase of cultural exchange between China and Western countries, Yangzhou gardens were also influenced by the West. When building Heyuan Garden, He Jianwei, who had once worked in customs, dealing with foreigners, introduced many Western elements, integrating them with the qualities of traditional Chinese gardens to better satisfy living and recreation demands.' },
  { k:'seg_7_决赛_32', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'何园主人何维键曾在海关任职并有与洋人共事的经历，因此他在建造何园的时候引入了许多西洋元素，将其与中国传统园林的形制相互融合，更好地满足居住和游赏的需求 。', mt:'The owner of He Garden, He Weijian, once worked at customs and had experience working with foreigners. Therefore, when he built He Garden, he introduced many Western elements and integrated them with the traditional Chinese garden style to better meet the needs of living and sightseeing.', ref:'When building Heyuan Garden, He Jianwei, who had once worked in customs, dealing with foreigners, introduced many Western elements, integrating them with the qualities of traditional Chinese gardens to better satisfy living and recreation demands.' },
  { k:'seg_7_决赛_33', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'这些西洋元素主要体现在西洋楼、煦春堂等建筑上，比如利用百叶窗、壁炉、地下通风穴道等西式元素优化西洋楼的建筑功能，在煦春堂引入玻璃、金属栏杆等新材料作为园林的装饰，形成了新的建筑美学特征。', mt:'These Western elements are mainly reflected in buildings such as the Western-style buildings and Xuchun Hall. For example, Western elements like shutters, fireplaces, and underground ventilation tunnels are used to optimize the functionality of the Western-style buildings. In Xuchun Hall, new materials such as glass and metal railings are introduced as garden decorations, forming new architectural aesthetic features.', ref:'These Western elements were mainly embodied in the buildings. For example, the use of Western-style elements such as blinds, fireplaces, and underground ventilation spaces improved the function of the Western-Style Building. New materials such as glass and metal railings were also introduced to Xuchun Hall (Cosy-Spring Hall) as decorations, which created a new building aesthetic.' },
  { k:'seg_7_决赛_34', ed:'7', stage:'决赛', dir:'汉译英', eng:'GPT-4o', src:'这些元素虽然与中国传统园林的审美有所不同，但无疑是清代晚期西方风格影响下中国古典园林风格的真实写照， 从园林发展历史的角度看来，何园是一个十分珍贵的样本 。', mt:'Although these elements differ from the aesthetics of traditional Chinese gardens, they undoubtedly reflect the true style of classical Chinese gardens under the influence of Western styles in the late Qing Dynasty. From the perspective of garden development history, He Garden is a very precious example.', ref:'These characteristics may differ from traditional aesthetic standards of Chinese garden design, but, undoubtedly, this approach accurately reflected Chinese classical garden style as influenced by the West in the late Qing dynasty. From the perspective of garden development history, Heyuan Garden is a very precious example.' },
  { k:'seg_7_初赛_1', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'What Does It Really Mean to Learn?', mt:'真正的学习意味着什么？', ref:'学习究竟意味着什么？' },
  { k:'seg_7_初赛_2', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'I read “Middlemarch” for the first time during my sophomore year of college.', mt:'我在大学二年级时第一次读了《米德尔马契》。', ref:'在我大二的那一年，我第一次读了《米德尔马契》。' },
  { k:'seg_7_初赛_3', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'I didn’t get it.', mt:'我没明白。', ref:'但我没读懂。' },
  { k:'seg_7_初赛_4', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Why would Dorothea, a young and intelligent woman, marry that annoying old man?', mt:'为什么多萝西娅，一个年轻聪明的女人，会嫁给那个讨厌的老头？', ref:'为什么多萝西娅又年轻又聪明，却偏要嫁给那个烦人的老头？' },
  { k:'seg_7_初赛_5', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'How could she be so stupid?', mt:'她怎么会这么愚蠢？', ref:'她怎么可以犯傻到如此地步？' },
  { k:'seg_7_初赛_6', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'No one else in the class seemed to get it, either, and this pushed our professor over the edge.', mt:'班上没有其他人似乎明白，这让我们的教授崩溃了。', ref:'全班同学似乎也都不明所以，这几乎令我们的教授抓狂。' },
  { k:'seg_7_初赛_7', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'“Of course you don’t understand,” he roared, swilling a Diet Coke.', mt:'“你当然不明白，”他咆哮着，喝了一口健怡可乐。', ref:'你们现在当然看不懂，”他大声嚷道，灌了一口无糖可乐 。' },
  { k:'seg_7_初赛_8', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'“Trust me, you’ll read this book again when you’re forty, after your first divorce, and you’ll say, ‘Oh, I see!’ ”', mt:'“相信我，当你四十岁，经历了第一次离婚后再读这本书时，你会说，‘哦，我明白了！’”', ref:'“相信我，等你40岁的时候，离了第一次婚，再把这本书读一遍，你会说，‘哦，我明白了！’”' },
  { k:'seg_7_初赛_9', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Arguably, it’s one of the tragedies of humanities education that so much of it occurs between the ages of eighteen and twenty-two.', mt:'可以说，人文学科教育的悲剧之一在于它的大部分发生在十八到二十二岁之间。', ref:'绝大部分的人文教育发生在18至22岁的年龄区间，这可以说是人文教育的悲哀之一。' },
  { k:'seg_7_初赛_10', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'We don’t teach people to drive at twelve, when they’re carless; why should we make them read novels about life’s regrets when they have none?', mt:'我们不会在十二岁时教人开车，因为他们没有车；为什么我们要让他们读关于人生遗憾的小说，而他们却没有遗憾？', ref:'如果说我们不教12岁的孩童如何驾驶，是因为他们还没车，那为何我们要在人们还未有人生遗憾之时，让他们通过阅读小说体味人生的遗憾？' },
  { k:'seg_7_初赛_11', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Yet there’s a theory behind the assignment of “Middlemarch” to sophomores: it’s that knowledge acquired too early gets stored away.', mt:'然而，将《米德尔马契》分配给二年级学生背后有一个理论：那就是过早获得的知识会被储存起来。', ref:'虽然如此，给大二学生布置《米德尔马契》的阅读任务自有其背后的逻辑：早年所获的知识会储藏在那里，以备不时之需。' },
  { k:'seg_7_初赛_12', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Patterns of thinking established now will be retraced later; ideas encountered first in art will prime us for the rest of life.', mt:'现在建立的思维模式将会在以后重现；首先在艺术中遇到的想法将为我们的一生做好准备。', ref:'思维方式一旦建立便可供循环利用；在人文艺术中汲取的养料可滋养我们的余生。' },
  { k:'seg_7_初赛_13', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'This sounds chancy and vague, until you reflect on the fact that knowledge almost never arrives at the moment of its application. You take a class in law school today only to argue a complicated case years later; you learn C.P.R. years before saving a drowning man; you read online about how to deter a charging bear, because you never know.', mt:'这听起来不确定且模糊，直到你反思知识几乎从不会在应用的那一刻到来。 你今天在法学院上课只是为了几年后辩论一个复杂的案件；你在多年之前学习心肺复苏术是为了在未来拯救一个溺水的人；你在网上阅读如何阻止一只冲过来的熊，因为你永远不知道什么时候会用到。', ref:'乍听之下，这一观点不免投机和模糊，但倘若你发现了知识不会在其应用之时突然涌现的真相，你的想法就会改变 。 你现在在法律系学习的课程，要在数年后当你为一个复杂的案子辩护时才有用武之地；你所学的心肺复苏术，要在数年后搭救溺水者时才能派上用场；你上网学习如何阻止一只爆冲的熊，因为你无从知晓哪天是否会用到。' },
  { k:'seg_7_初赛_14', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'You take a class in law school today only to argue a complicated case years later; you learn C.P.R. years before saving a drowning man; you read online about how to deter a charging bear, because you never know.', mt:'你今天在法学院上课只是为了几年后辩论一个复杂的案件；你在多年之前学习心肺复苏术是为了在未来拯救一个溺水的人；你在网上阅读如何阻止一只冲过来的熊，因为你永远不知道什么时候会用到。', ref:'你现在在法律系学习的课程，要在数年后当你为一个复杂的案子辩护时才有用武之地；你所学的心肺复苏术，要在数年后搭救溺水者时才能派上用场；你上网学习如何阻止一只爆冲的熊，因为你无从知晓哪天是否会用到。' },
  { k:'seg_7_初赛_15', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'In the mid-twentieth century, Toyota pioneered a methodology called just-in-time manufacturing, according to which car parts were constructed and delivered as close as possible to the hour of assembly.', mt:'在二十世纪中期，丰田开创了一种称为准时制生产的方法，根据这种方法，汽车零部件尽可能接近装配时间进行制造和交付。', ref:'早在上世纪中叶，丰田便开创了一种可称之为“一切刚好 ”的生产方式。' },
  { k:'seg_7_初赛_16', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'This was maximally efficient because it reduced waste and the cost of storage.', mt:'这非常高效，因为它减少了浪费和存储成本。', ref:'在此方式的指导下，汽车零组件的制造和交付都力图在组装前就位。该方式非常高效，因为它降低了浪费，节约了仓储成本。' },
  { k:'seg_7_初赛_17', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'But the human mind doesn’t work that way.', mt:'但是人类的思维方式并不是那样的。', ref:'但人脑并不按此方法运行。' },
  { k:'seg_7_初赛_18', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Knowledge must often molder in our mental warehouses for decades until we figure out what to do with it.', mt:'知识常常需要在我们的精神仓库中发霉几十年，直到我们弄清楚如何处理它。', ref:'知识要在我们脑海中储藏数年，甚至开始腐坏后，我们才能明白如何运用它。' },
  { k:'seg_7_初赛_19', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Leslie Valiant, an eminent computer scientist who teaches at Harvard, sees this as a strength.', mt:'莱斯利·瓦连特（Leslie Valiant）是哈佛大学的一位杰出计算机科学家，他认为这是一个优势。', ref:'在哈佛大学执教的著名计算机科学家莱斯利·瓦利安特（Leslie Valiant）将此视为一种优势。' },
  { k:'seg_7_初赛_20', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'He calls our ability to learn over the long term “educability,” and in his new book, “The Importance of Being Educable,” he argues that it’s key to our success.', mt:'他称我们长期学习的能力为“可教育性”，并在他的新书 《可教育性的重要性》中指出，这是我们成功的关键。', ref:'他称我们这种历久弥新的学习能力为“通识”（educability）1 ，并在他的新书《触类旁通的重要性》 中将之认定为我们获取成功的关键。' },
  { k:'seg_7_初赛_21', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'When we think about what makes our minds special, we tend to focus on intelligence.', mt:'当我们思考是什么让我们的思想变得特别时，我们往往会关注智力。', ref:'当我们思索大脑的独特性源自何物时，我们通常会将之归因于“智识”。' },
  { k:'seg_7_初赛_22', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'But if we want to grasp reality in all its complexity, Valiant writes, then “cleverness is not enough.”', mt:'但如果我们想要理解现实的复杂性，瓦里安特写道，那么“聪明是不够的。”', ref:'然而，瓦利安特写道，如果我们希望真正把握现实的复杂性，仅有“智识”是远不足够的。' },
  { k:'seg_7_初赛_23', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'We need to build capacious and flexible theories about the world—theories that will serve us in new, unanticipated, and strange circumstances—and we do that by gathering diverse kinds of knowledge, often in a slow, additive, serendipitous way, and knitting them together.', mt:'我们需要建立关于世界的宽广而灵活的理论——这些理论将在新的、未预料到的和奇怪的情况下为我们服务 ——我们通过收集各种各样的知识，通常以一种缓慢、 累积、偶然的方式，并将它们编织在一起。', ref:'我们需要构建起广阔而又灵活的世界观，这些观念能让我们在全新的环境中应对不可预见甚至出乎意料的情况。这种世界观的形成需要我们搜集各种知识，以一种缓慢、叠加、偶然的方式将知识融会贯通。' },
  { k:'seg_7_初赛_24', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Through this process, we acquire systems of beliefs that are broader and richer than the ones we can create through direct personal experience.', mt:'通过这个过程，我们获得了比通过直接个人经验所能创造的更广泛和丰富的信仰体系。', ref:'在此过程中构建的价值体系，相较于以我们个人一手经验为基础而形成的价值体系相比，要更广泛和丰富。' },
  { k:'seg_7_初赛_25', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Valiant won the 2010 Turing Award, his discipline’s version of the Nobel Prize, for developing ideas that underpin artificial intelligence and distributed computation, in which many computers work together to solve problems.', mt:'英勇赢得了2010年的图灵奖，这是他所在领域的诺贝尔奖，因其在人工智能和分布式计算（即多台计算机协同解决问题）方面的发展理念而获奖。', ref:'瓦利安特于2010年获得图灵奖，该奖项是他专业领域内的诺贝尔奖，用以支持人工智能和分布式计算技术的发展，该项技术依靠多台计算机协同合作解决问题。' },
  { k:'seg_7_初赛_26', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'In his book, he contrasts A.I.’s way of learning with ours.', mt:'在他的书中，他对比了人工智能的学习方式和我们的学习方式。', ref:'瓦利安特在书中对比了人工智能和人类的学习方法。' },
  { k:'seg_7_初赛_27', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'An A.I. can be astonishingly smart, and even think intuitively, kind of like a person.', mt:'人工智能可以非常聪明，甚至可以像人一样直觉地思考。', ref:'人工智能可以智能得出奇，甚至能像人类一样凭直觉思考 。' },
  { k:'seg_7_初赛_28', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'But A.I. systems, Valiant argues, are not as flexible as human minds because they are not yet educable.', mt:'但瓦连特认为，人工智能系统不如人类大脑灵活，因为它们还不能被教育。', ref:'虽然如此，瓦利安特认为人工智能系统并无人脑灵活，因为人工智能并不具有触类旁通的能力。' },
  { k:'seg_7_初赛_29', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Even the most state-of-the-art A.I.s learn through a rigid process, in which they are trained, at great expense, and don’t really get any smarter after that, no matter how much new information they ingest.', mt:'即使是最先进的人工智能也是通过一个严格的过程来学习的，在这个过程中，它们经过高成本的训练，并且在那之后无论摄取多少新信息，它们实际上都不会变得更聪明。', ref:'我们用最严苛的方式，付出巨大的代价训练人工智能，使其获得最前沿的知识，但在此之后，无论消化吸收多少新信息，人工智能也并不会变得更智能。' },
  { k:'seg_7_初赛_30', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'It’s as though their minds freeze on graduation day.', mt:'仿佛他们的思维在毕业那天冻结了。', ref:'它们的思维仿佛在训练完成获得“毕业”那一刻便停滞不前了。' },
  { k:'seg_7_初赛_31', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Yet human beings constantly improve their own minds through an unfolding, open-ended process that connects newly acquired facts and ideas to ones collected long ago.', mt:'然而，人类通过一个不断展开、开放的过程，不断改进自己的思维，将新获得的事实和想法与很久以前收集的知识联系起来。', ref:'与之相反，人脑常常进化，能以一种开放渐进的方式将新知与旧识贯通起来。' },
  { k:'seg_7_初赛_32', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'We “combine pieces of knowledge gained years apart” into “theories of considerable complexity that have many and disparate parts.”', mt:'我们“将相隔多年的知识片段结合起来”，形成“包含许多不同部分的复杂理论”。', ref:'我们“能将数年前习得的知识碎片”融汇成“统摄众多复杂组成部分的理论体系”。' },
  { k:'seg_7_初赛_33', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Valiant says that he tries not to use the word “intelligent” to describe people; instead, he is drawn to “valuable abilities that somehow involve learning and are not well captured by conventional notions of IQ.”', mt:'英勇说他尽量不使用“聪明”这个词来形容人；相反，他更倾向于使用“有价值的能力，这些能力在某种程度上涉及学习，并且不容易被传统的智商概念所捕捉。”', ref:'瓦利安特说他尽量不用“聪明”这个词去形容别人（事实上，如果听到别人用这个词，他甚至会不知所措）。瓦利安特更倾向于其它和学习相关的宝贵素质，而这些素质并不能简单化为“智商”。' },
  { k:'seg_7_初赛_34', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'An educable mind, he writes, can learn from books, lectures, conversations, experiences, and Zen koans—from anything, really—and notice when relevant aspects of almost forgotten knowledge reveal themselves. We admire aspects of someone’s educability when we say that they are a quick study, or identify them as “coachable,” but what really makes them educable is that they apply insights “for purposes not foreseen at the time of the study or the coaching”; educability is something like “street smarts”—a term which connotes the “uncanny ability to negotiate the practicalities of life”—and is closely related to having common sense.', mt:'他写道，一个可教育的心灵可以从书籍、讲座、对话、经验和禅宗公案中学习——实际上可以从任何事物中学习 ——并注意到几乎被遗忘的知识的相关方面何时显现出来。 我们在称赞某人的可教育性时，会说他们是一个学习很快的人，或者称他们为“可教导的”，但真正使他们可教育的是他们能够将见解应用于“在学习或指导时未预见的目的”；可教育性有点像“街头智慧”——这个词意味着“非凡的处理生活实际问题的能力”——并且与常识密切相关。', ref:'他写道，这种触类旁通的思维可令人从任何东西中汲取知识，包括书本、讲座、谈话、经历、甚至禅宗的公案，并从几乎已被忘却的知识中寻找共通之处。 当我们评价某人上手很快，或者认定某人“孺子可教 ”时，我们实际上是在称赞他的“通识”能力。究其根本 ，原因在于他们能化用所学的知识，尽管这些知识在被获取的当下并无特定用途。“通识”接近于一种“街头智慧 ”，指代一种能与生存法则斡旋的能力，一种利用“常识 ”的能力。' },
  { k:'seg_7_初赛_35', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'we say that they are a quick study, or identify them as “coachable,” but what really makes them educable is that they apply insights “for purposes not foreseen at the time of the study or the coaching”; educability is something like “street smarts”—a term which connotes the “uncanny ability to negotiate the practicalities of life”—and is closely related to having common sense.', mt:'我们在称赞某人的可教育性时，会说他们是一个学习很快的人，或者称他们为“可教导的”，但真正使他们可教育的是他们能够将见解应用于“在学习或指导时未预见的目的”；可教育性有点像“街头智慧”——这个词意味着“非凡的处理生活实际问题的能力”——并且与常识密切相关。', ref:'当我们评价某人上手很快，或者认定某人“孺子可教 ”时，我们实际上是在称赞他的“通识”能力。究其根本 ，原因在于他们能化用所学的知识，尽管这些知识在被获取的当下并无特定用途。“通识”接近于一种“街头智慧 ”，指代一种能与生存法则斡旋的能力，一种利用“常识 ”的能力。' },
  { k:'seg_7_初赛_36', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'When people strike us as particularly “well- educated,” this might mean that they’ve had lots of school, Valiant writes, but it could also mean that they’re exceptionally educable, with the ability to “take good advantage of whatever educational opportunities arise, whether formal or informal.”', mt:'当人们给我们留下“受过良好教育”的印象时，这可能意味着他们上过很多学，Valiant写道，但这也可能意味着他们特别容易受教育，能够“充分利用任何出现的教育机会，无论是正式的还是非正式的。”', ref:'瓦利安特写道，当我们惊叹某些人的“高知”时，我们或许在称赞他们所接受的众多教育，但也可能在赞叹他们融会贯通知识的出色能力，这种能力“可以助其把握住无论正式与否的任何教育机会”。' },
  { k:'seg_7_初赛_37', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Valiant suggests that we value educability in doctors.', mt:'英勇建议我们重视医生的可教育性。', ref:'瓦利安特还指出，我们也重视医生的“通识”能力。' },
  { k:'seg_7_初赛_38', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Imagine that you feel a pain in your side.', mt:'想象一下你感到侧腹疼痛。', ref:'试想一下，倘若你感到侧腹疼痛，' },
  { k:'seg_7_初赛_39', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Is it appendicitis?', mt:'是阑尾炎吗？', ref:'但这就意味着患上阑尾炎了吗？' },
  { k:'seg_7_初赛_40', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'It would be unwise, he writes, to rely on what you know about the disease, based on what a few people who’ve had it have told you; you’d want to talk to a physician who’s seen a thousand cases.', mt:'他写道，依赖你从几个得过这种病的人那里了解到的情况是不明智的；你应该去咨询一个见过上千病例的医生。', ref:'瓦利安特继续写道，仅依赖曾经的病患分享的信息远非明智之举；你应向一位诊疗过上千个病例的医生问诊。' },
  { k:'seg_7_初赛_41', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'A medical A.I. could also train by looking at thousands of cases; in fact, “if it has seen a million cases, a situation well beyond individual human experience, then it may make predictions that are stunningly better than our intuitions can even comprehend.”', mt:'一个医疗人工智能也可以通过查看成千上万的病例进行训练；事实上，“如果它已经看过一百万个病例，这种情况远远超出个人的经验，那么它可能会做出比我们的直觉甚至无法理解的惊人预测。”', ref:'我们可以让医疗人工智能分析成千上万个病例，以此达到训练的目的；事实上，“如果它分析过上百万个病例，便能积累远超人类个体所能企及的经验，那么它所做的判断可能会比我们所做的好得多，甚至好到我们的智商都无法理解的地步。”' },
  { k:'seg_7_初赛_42', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'And yet “the reason we go to doctors is not just that they have seen a thousand cases of a disease,” Valiant argues.', mt:'然而，瓦利安特认为，“我们去看医生的原因不仅仅是因为他们见过成千上万的病例。”', ref:'然而，“我们向医生求医问诊，并非因为他们诊疗过上千个病人，”瓦利安特认为，' },
  { k:'seg_7_初赛_43', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'“It is that we believe doctors deliver further results.”', mt:'“我们相信医生会带来更多的成果。”', ref:'“而因为我们相信医生能够提供更多的建议”。' },
  { k:'seg_7_初赛_44', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'The basis of that extra value is educability.', mt:'这种额外价值的基础是可教育性。', ref:'这种附加价值的基础便是“通识”。' },
  { k:'seg_7_初赛_45', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Valiant doesn’t get into details, but we can imagine for ourselves the value that a hypothetical doctor’s educability might provide.', mt:'英勇没有详细说明，但我们可以自己想象一个假设的医生的可教育性可能带来的价值。', ref:'瓦利安特并未提供更多细节，但我们大可想象此例中该医生的“通识”能力所能带来的价值。' },
  { k:'seg_7_初赛_46', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Such a doctor might draw on a range of ideas and connections spanning years of learning.', mt:'这样的医生可能会利用多年学习中积累的一系列想法和联系。', ref:'该医生或许会融通多年学习过程中的所思所想。' },
  { k:'seg_7_初赛_47', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'She learned about appendicitis in medical school, of course—and quickly concludes that you don’t have it.', mt:'她在医学院学过阑尾炎，当然——很快得出结论你没有得阑尾炎。', ref:'毋庸置疑，她在医学院学习过诊治阑尾炎，并迅速得出你没得阑尾炎的结论。' },
  { k:'seg_7_初赛_48', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'But maybe her brother happens to be an avid cyclist, and she notices you drinking from a water bottle emblazoned with a logo she recognizes from his bike.', mt:'但也许她的兄弟恰好是一个狂热的骑行者，而她注意到你正在喝水瓶上的标志是她从他自行车上认出来的。', ref:'但也许，她的兄弟是狂热的骑行爱好者，她注意到你喝水瓶子上的标志和他自行车的标志别无二异。' },
  { k:'seg_7_初赛_49', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Wasn’t there an article online about how dangerous the city’s bike lanes have become?', mt:'网上不是有一篇关于城市自行车道变得多么危险的文章吗？', ref:'而且是不是有一篇网传文章，报道了这座城市的自行车道已变得如何危险？' },
  { k:'seg_7_初赛_50', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'More generally, she’s also developed a new theory: she ought to ask more questions about the particulars of her patients’ lives.', mt:'更广泛地说，她还提出了一个新理论：她应该更多地询问患者生活的细节。', ref:'此外，她还发展出一套理论：她应询问患者，获取更多有关其生活的细节。' },
  { k:'seg_7_初赛_51', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'She asks if you’re a cyclist, discovers that you are, and eventually pinpoints the real issue—a bruised rib acquired in a fall, which you’ve not allowed to heal properly.', mt:'她问你是否是骑自行车的人，发现你是，最终找到了真正的问题——在一次摔倒中受伤的肋骨，你没有让它好好愈合。', ref:'她于是询问你是否骑自行车，得知你的确是骑行爱好者的事实后，她终于发现了问题的源头。原来是因为你曾摔倒，并使肋骨受伤过，而受伤的肋骨并未充分康复。' },
  { k:'seg_7_初赛_52', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Being educable, the doctor actually regards your case as an opportunity to learn, and is a better physician for it.', mt:'由于具有可教育性，这位医生实际上将你的病例视为一个学习的机会，并因此成为一名更好的医生。', ref:'作为一位拥有“通识”的医生，她把你的病况视为学习的机会，同时她也成为了更适合诊治你病情的医生。' },
  { k:'seg_7_初赛_53', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'That’s a rather schematic, explicit example of educability.', mt:'这就是一个相当简明、明确的可教育性的例子。', ref:'这个例子清晰明了，是“通识”的代表性例证，但与此同时瓦利安特似乎还在描述一些更为精细且更具力量的东西 。' },
  { k:'seg_7_初赛_54', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'To a degree, the connections, recombinations, and new applications of knowledge involved in being educable are useful precisely because they aren’t obvious.', mt:'在某种程度上，受教育所涉及的知识连接、重组和新应用之所以有用，正是因为它们并不显而易见。', ref:'在某种程度上，知识的连接、重组以及新应用均是“通识 ”的体现，而它们发挥用途的关键所在便是其潜移默化的能力。' },
  { k:'seg_7_初赛_55', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'It’s interesting to see one’s mind through the lens of educability.', mt:'通过可教育性的视角来看待一个人的思想是很有趣的。', ref:'通过“通识”的视角来看待自己的思维是件十分有趣的事情。' },
  { k:'seg_7_初赛_56', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'It makes you wonder what other cross-pollinations have occurred.', mt:'这让你不禁想知道还有哪些其他的交叉授粉发生过。', ref:'这让人不禁想知道还有哪些关联贯通的现象发生过。' },
  { k:'seg_7_初赛_57', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Valiant thinks it might be useful to promote educability as an ideal. We could try to figure out how to measure and teach it in schools, or to encourage it in adults; at a time when accelerating technological change means there’s always more to learn, we might seek to create a more educable society in general.', mt:'英勇认为促进可教育性作为一种理想可能是有用的。 我们可以尝试研究如何在学校中测量和教授它，或者在成年人中鼓励它；在技术变革加速的时代，这意味着总有更多的东西需要学习，我们可能会寻求总体上创造一个更具教育性的社会。', ref:'瓦利安特认为，如果把“通识”当作是一种理念来推行的话，或许大有裨益。 我们可以尝试找出如何在学校衡量和传授“通识”的方法，同时向成年人推广“通识”；在科技发展日新月异的当下，知识的获取永无止境，因此我们更应当寻求创造一个更具通识性的社会。' },
  { k:'seg_7_初赛_58', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'We could try to figure out how to measure and teach it in schools, or to encourage it in adults; at a time when accelerating technological change means there’s always more to learn, we might seek to create a more educable society in general.', mt:'我们可以尝试研究如何在学校中测量和教授它，或者在成年人中鼓励它；在技术变革加速的时代，这意味着总有更多的东西需要学习，我们可能会寻求总体上创造一个更具教育性的社会。', ref:'我们可以尝试找出如何在学校衡量和传授“通识”的方法，同时向成年人推广“通识”；在科技发展日新月异的当下，知识的获取永无止境，因此我们更应当寻求创造一个更具通识性的社会。' },
  { k:'seg_7_初赛_59', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'After reading his book, I thought, on a less exalted scale, about how I might improve my own educability.', mt:'读完他的书后，我想，虽然规模较小，但我如何才能提高自己的可教育性。', ref:'读罢书后，我从一个更务实的角度思考了如何提高我“通识”能力的方式。' },
  { k:'seg_7_初赛_60', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'I concluded that I would seek to learn about a wider range of subjects, and simply try more things, trusting that my mind would someday knit it all together.', mt:'我决定要学习更广泛的学科，并尝试更多的事情，相信我的大脑有一天会把这一切联系起来。', ref:'我的结论是我会寻求学习更广泛的科目，尝试更多的东西，寄希望于我的脑子在某天可以将其融会贯通。' },
  { k:'seg_7_初赛_61', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'I also figured that it couldn’t hurt to remind myself of what I’d already learned.', mt:'我也觉得提醒自己已经学到的东西不会有什么坏处。', ref:'我也明白，我也可以付诸于曾经的所学来提醒自己。' },
  { k:'seg_7_初赛_62', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Down in the basement, a few big bookshelves hold my reading from college and graduate school.', mt:'在地下室里，有几个大书架放着我大学和研究生时期的书 。', ref:'地下室的几个大书架上，放着我大学和研究生阶段所读的书，' },
  { k:'seg_7_初赛_63', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'“Middlemarch” is there, along with many other books that I didn’t understand then but have come to value with the passage of time.', mt:'《米德尔马契》在那里，还有许多其他我当时不理解但随着时间的推移逐渐珍视的书。', ref:'《米德尔马契》便是其中的一本，当然还有其他我当时读不懂的书。但随着时间的流逝，我开始发现了这些书的价值。' },
  { k:'seg_7_初赛_64', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Reading widely about things that don’t seem immediately or practically useful, in the hope that what you learn now may prove meaningful later—that’s pretty much the definition of a liberal-arts education.', mt:'广泛阅读那些看起来没有直接或实际用途的东西，希望你现在学到的东西以后可能会有意义——这几乎就是文科教育的定义。', ref:'广泛阅读那些看似当下并无实际用处的内容，以求在日后发挥用途，这或许便是通识教育的真谛。' },
  { k:'seg_7_初赛_65', ed:'7', stage:'初赛', dir:'英译汉', eng:'GPT-4o', src:'Who knew that one of its best defenders would turn out to be a computer scientist?', mt:'谁知道它最好的捍卫者之一竟然会是一个计算机科学家呢？', ref:'但又有谁能料到这一方式的捍卫者竟是一位计算机科学家呢？' },
  { k:'seg_8_决赛_1', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'近代上海地方建筑特征', mt:'Modern Architectural Features of Shanghai', ref:'The Features of Local Shanghai Architecture' },
  { k:'seg_8_决赛_2', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'上海近代建筑有着强烈的地方特征。', mt:'Modern architecture in Shanghai exhibits strong local characteristics.', ref:'Shanghai’s architecture has distinctive local traits' },
  { k:'seg_8_决赛_3', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'这种地方特征不论是居住在上海的本地人还是来上海的外地人都能感觉到。', mt:'This local characteristic can be felt by both native residents of Shanghai and visitors from other regions.', ref:'that both long-time residents and newly arrived visitors can discern.' },
  { k:'seg_8_决赛_4', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'它建立在上海悠久的历史中形成的地方文化传统的基础之上，更与近代100年里上海特殊的城市经历密不可分，与近代上海人的社会心态、生活方式、行为准则和价值观念紧紧相关，反过来它更是近代上海特殊的城市文化的一个不可缺少的重要组成部分。', mt:'It is rooted in the local cultural traditions shaped by Shanghai\'s long history and is deeply intertwined with the city\'s unique experiences over the past century. Closely linked to the social mentality, lifestyle, behavioral norms, and values of modern Shanghainese, it has, in turn, become an indispensable and vital component of Shanghai\'s distinctive urban culture.', ref:'Built upon the local culture and traditions accumulated over Shanghai’s long history, they are even more intimately tied to the unique century of change the city underwent during the early modern period. These traits are closely related to the people of the city, their mentality, their way of life, their behavioral standards, and their system of values. Conversely, Shanghai’s distinctive local architecture is also an essential component of this unique urban culture.' },
  { k:'seg_8_决赛_5', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'上海近代建筑的地方特征概括起来讲，就是注重功利，追求时尚；中西合璧，兼容并蓄。', mt:'The local characteristics of modern architecture in Shanghai can be summarized as follows: a focus on practicality, a pursuit of trends; a blend of Chinese and Western styles, embracing diversity.', ref:'These distinctive local traits include the dynamic coexistence of both fashion and utility, as well as the open-minded synthesis of Chinese and Western aspects.' },
  { k:'seg_8_决赛_6', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'注重功利，追求时尚', mt:'Focus on utility, pursue trends', ref:'Fashion and Utility' },
  { k:'seg_8_决赛_7', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'注重功利是商品经济社会中人们社会价值观的一个重要表现，它表现在社会文化的各个方面，自然也会通过建筑表现出来。', mt:'The emphasis on utilitarianism is an important manifestation of people\'s social values in a commodity economy society. It is reflected in various aspects of social culture and naturally also expressed through architecture.', ref:'An emphasis on utility is one of the principal social values found in a commodity economy. It is typically expressed throughout the various aspects of a society’s culture, and it is therefore only natural that it should emerge in architecture.' },
  { k:'seg_8_决赛_8', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'早在上海开埠以前，相对于中国其他城市而言，上海的商品经济就已相当发达，并对传统的上海地方文化带来了深刻的影响。', mt:'Long before Shanghai became a trading port, its commodity economy was already quite developed compared to other Chinese cities, profoundly influencing the traditional local culture of Shanghai.', ref:'Compared with China’s other cities, Shanghai’s commodity economy was already fairly well developed even before its opening, a fact that had a profound influence on the city’s traditional local culture.' },
  { k:'seg_8_决赛_9', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'上海开埠后，现代西方资本主义经济进入上海，使上海迅速成为中国近代商品经济最发达的城市，这使得近代上海社会的各个方面都表现出一种以“利益第一”的社会价值观代替中国传统“重义轻利”社会价值观的倾向。', mt:'After Shanghai opened its port, modern Western capitalist economy entered the city, rapidly transforming it into the most developed hub of modern commodity economy in China. This shift led to a noticeable trend in various aspects of Shanghai society, where the traditional Chinese value of "emphasizing righteousness over profit" was gradually replaced by a new social ethos that prioritized "profit first."', ref:'After the opening and the arrival of Western capitalism, Shanghai quickly became the city with the most developed commodity economy in China. Across various aspects of Shanghai’s society, this led to the displacement of traditional Chinese values, which tended to place “principle before profit,” with a new “profit-first” value system.' },
  { k:'seg_8_决赛_10', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'“利，时之大义矣”成为一种社会共识。', mt:'Profit is the supreme principle of the times" has become a social consensus.', ref:'The people of Shanghai came to an understanding that “profit is the new guiding principle of our times.”' },
  { k:'seg_8_决赛_11', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'正是在这样一种社会心态下，以赢利为目的的上海近代建筑业产生了。 建筑作为一种普通的商品被大量地建造起来，为了“利 ”，可以不顾中国官府和外国领事两方都坚持的“华洋分居”原则而建造大量商品住宅吸引华人进入租界；为了“ 利”，可以将租界的煤气管、自来水管、电线电缆接到华界，让“低等”的华人与“高等”的洋人同时享受现代文明；为了“利”，上海才会出现高楼成群，建筑密布的拥挤的城市风貌，反映在建筑设计上，就是一切从实际出发，精打细算，讲求实惠。 追求时尚也是近代上海发达的商品经济社会中又一种突出的社会心态。', mt:'It was under such a social mentality that the profit- driven modern construction industry in Shanghai emerged. Architecture, as a common commodity, was constructed in large quantities. For the sake of "profit," developers disregarded the "separation of Chinese and foreigners" principle upheld by both the Chinese authorities and foreign consulates, building numerous commercial residences to attract Chinese into the concessions. For the sake of "profit," gas pipes, water mains, and electrical cables from the concessions were extended into Chinese districts, allowing "lower-class" Chinese to enjoy modern amenities alongside "upper-class" foreigners. For the sake of "profit," Shanghai developed its crowded urban landscape of towering buildings and dense construction. This pragmatism was reflected in architectural design—everything was based on practicality, meticulous calculation, and a focus on tangible benefits. The pursuit of fashion is another prominent social mentality in the modern, prosperous commodity economy of Shanghai."', ref:'It was precisely this new outlook that produced the city’s profit-driven construction industry, transforming buildings into everyday commodities and leading to their construction in ever-larger numbers. For “profit,” builders ignored the principle of Chinese-foreign separation set down by the Chinese government and foreign consulates in order to build the large quantities of commodity housing that attracted Chinese residents to the concessions. For “profit,” the concessions’ gas, water, and power infrastructure was extended into Chinese district, enabling the “lower class” Chinese and “upper class” foreigners to share the benefits of modern civilization. For “profit,” high-rise and high-density buildings became characteristic of Shanghai’s urban environment. Reflected in the design of the built environment, these features were all calculated to achieve maximum profit from the city’s prevailing circumstances. The pursuit of fashion was another prominent feature of the mentality engendered by Shanghai’s developed commodity economy.' },
  { k:'seg_8_决赛_12', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'建筑作为一种普通的商品被大量地建造起来，为了“利 ”，可以不顾中国官府和外国领事两方都坚持的“华洋分居”原则而建造大量商品住宅吸引华人进入租界；为了“ 利”，可以将租界的煤气管、自来水管、电线电缆接到华界，让“低等”的华人与“高等”的洋人同时享受现代文明；为了“利”，上海才会出现高楼成群，建筑密布的拥挤的城市风貌，反映在建筑设计上，就是一切从实际出发，精打细算，讲求实惠。', mt:'Architecture, as a common commodity, was constructed in large quantities. For the sake of "profit," developers disregarded the "separation of Chinese and foreigners" principle upheld by both the Chinese authorities and foreign consulates, building numerous commercial residences to attract Chinese into the concessions. For the sake of "profit," gas pipes, water mains, and electrical cables from the concessions were extended into Chinese districts, allowing "lower-class" Chinese to enjoy modern amenities alongside "upper-class" foreigners. For the sake of "profit," Shanghai developed its crowded urban landscape of towering buildings and dense construction. This pragmatism was reflected in architectural design—everything was based on practicality, meticulous calculation, and a focus on tangible benefits.', ref:'transforming buildings into everyday commodities and leading to their construction in ever-larger numbers. For “profit,” builders ignored the principle of Chinese-foreign separation set down by the Chinese government and foreign consulates in order to build the large quantities of commodity housing that attracted Chinese residents to the concessions. For “profit,” the concessions’ gas, water, and power infrastructure was extended into Chinese district, enabling the “lower class” Chinese and “upper class” foreigners to share the benefits of modern civilization. For “profit,” high-rise and high-density buildings became characteristic of Shanghai’s urban environment. Reflected in the design of the built environment, these features were all calculated to achieve maximum profit from the city’s prevailing circumstances.' },
  { k:'seg_8_决赛_13', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'追求时尚也是近代上海发达的商品经济社会中又一种突出的社会心态。', mt:'The pursuit of fashion is another prominent social mentality in the modern, prosperous commodity economy of Shanghai."', ref:'The pursuit of fashion was another prominent feature of the mentality engendered by Shanghai’s developed commodity economy.' },
  { k:'seg_8_决赛_14', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'“以新为美”表现在近代社会的各个方面，戏剧、文学、 服装、建筑无不如此。', mt:'The pursuit of novelty as beauty" manifests in every aspect of modern society, be it theater, literature, fashion, or architecture.', ref:'Theater, literature, fashion, and architecture all embodied the city’s new maxim, “new is beautiful.”' },
  { k:'seg_8_决赛_15', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'1876年，当上海修筑了第一条铁路淞沪铁路而遭到清政府的强烈反对，并决定将其赎买及拆毁时，上海的老百姓却都竞相观望、乘坐，以求一睹为快、一坐为快。', mt:'In 1876, when the first railway in Shanghai, the Songhu Railway, was constructed and faced strong opposition from the Qing government, which decided to buy it back and dismantle it, the local residents of Shanghai eagerly flocked to see and ride it, eager to witness and experience the novelty.', ref:'After the construction of China’s first railroad in 1876, the Wusong-Shanghai Line, the Qing government, which was fiercely opposed to the newfangled contraption, decided to buy the line and destroy it. The people of Shanghai, however, flocked to the newly built wonder, vying for a seat or even a glimpse of the train.' },
  { k:'seg_8_决赛_16', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'通车之际,“铁路两旁观者云集，欲搭坐者已繁杂不可计数 ”,“坐车者尽面带喜色，旁观者亦皆喝彩”。', mt:'At the time of the opening, "spectators gathered on both sides of the railway, with countless eager to board,""those on the train wore joyful expressions, while the onlookers cheered."', ref:'While it was operational, “the railroad was crowded with onlookers on both sides, and innumerable passengers crowded the train looking for seats.” As the train moved, “the passengers all sat with looks of delight, and the bystanders raised a cheer.”' },
  { k:'seg_8_决赛_17', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'对于新事物，上海人有一种特别的接受能力，反映在建筑上，就是对“新”的追求始终不断。', mt:'Shanghai people have a unique ability to embrace new things, which is reflected in their architecture through a constant pursuit of the "new."', ref:'The people of Shanghai were uniquely disposed to welcome all that was “new.” As far as architecture was concerned, this outlook expressed itself in the unbridled pursuit of novelty.' },
  { k:'seg_8_决赛_18', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'新材料、新结构、新设备往往会作为一种骄傲而大肆宣传，新式样更是不断出现，不断翻新。', mt:'New materials, new structures, and new equipment are often touted with pride, while new styles constantly emerge and evolve.', ref:'New materials, new structures, and new amenities often became points of pride that made a big splash when they first appeared. To an even greater extent, new architectural styles were continually being discovered and renewed.' },
  { k:'seg_8_决赛_19', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'在一个竞争激烈的商品社会里，不能不断地推陈出新就会有随时被社会淘汰的危险。', mt:'In a fiercely competitive consumer society, failing to continuously innovate and bring forth new ideas carries the risk of being left behind at any moment.', ref:'Amidst the intense competition of a commodity- driven society, those who could not maintain a regime of continuous reinvention risked being weeded out over time.' },
  { k:'seg_8_决赛_20', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'因此，不论是业主还是设计者，都把追求时尚看成是其事业能够继续发展的保证。', mt:'Therefore, both property owners and designers regard pursuing fashion as a guarantee for the continued development of their careers.', ref:'Thus, both developers and designers saw the pursuit of fashion as a guarantee for the continued development of their enterprises.' },
  { k:'seg_8_决赛_21', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'而每一次新式样的出现，每一种新设备、新技术的运用， 也都会引起社会的轰动，都会引起社会的竞相效仿。', mt:'And every time a new style emerges, every new device or application of new technology, it causes a social sensation and sparks widespread imitation.', ref:'Moreover, the first appearance of every new style, amenity, or technology always caused a sensation in Shanghai society, and competitors immediately vied to imitate it.' },
  { k:'seg_8_决赛_22', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'上海近代的建筑也正因为如此，才会呈现出丰富多彩、始终新意不断的发展局面。', mt:'The modern architecture of Shanghai has thus developed into a vibrant and ever-innovative landscape.', ref:'It is for this reason that Shanghai’s architecture is so richly varied and so powerfully invigorated with the continual reinvention of the new.' },
  { k:'seg_8_决赛_23', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'中西合璧，兼容并蓄', mt:'Combining Chinese and Western elements, embracing diversity', ref:'Open-mindedness and Chinese-Western Synthesis' },
  { k:'seg_8_决赛_24', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'由于上海近代建筑是产生在东西方两种异质文化相碰撞的过程中，因而就不可避免地会反映出一种中西合璧的现象 。', mt:'Since modern architecture in Shanghai emerged from the collision of two distinct cultures, East and West, it inevitably reflects a fusion of Chinese and Western elements.', ref:'Given that Shanghai’s modern architectural development has occurred as the result of a collision between the differing cultural values of East and West, it was unavoidable that there should be some resulting synthesis of Chinese and Western elements.' },
  { k:'seg_8_决赛_25', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'上海地方文化中特有的、吸百家之长兼容并蓄的能力使得这种中西合璧现象表现得尤为突出。', mt:'The unique ability of Shanghai\'s local culture to absorb and integrate the strengths of various schools makes this fusion of Chinese and Western elements particularly prominent.', ref:'The special open-mindedness with which the city welcomed the strengths of new arrivals meant that this synthesis became particularly pronounced in Shanghai.' },
  { k:'seg_8_决赛_26', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'事实上，上海近代建筑中“东西合璧”从西方建筑进入上海的第一天就已开始。', mt:'In fact, the "fusion of East and West" in Shanghai\'s modern architecture began the very day Western architecture first arrived in the city.', ref:'In fact, this phenomenon had begun as soon as Western architecture arrived in the city,' },
  { k:'seg_8_决赛_27', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'早期“康白度式”(Compradoric Style)建筑即能说明这一点。', mt:'The early "Compradoric Style" architecture can illustrate this point.', ref:'as is illustrated by the early “Compradoric style.”' },
  { k:'seg_8_决赛_28', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'虽然它在中国人的眼里是“洋房”，但却是中国的工匠用中国的建筑材料，用中国的传统的建造方式建造起来的。', mt:'Although it is considered a "Western-style house" in the eyes of the Chinese, it was actually built by Chinese craftsmen using Chinese construction materials and traditional Chinese building methods.', ref:'Though Compradoric-style buildings were decidedly Western in the eyes of locals, they were actually built by Chinese artisans using Chinese materials and traditional Chinese construction methods.' },
  { k:'seg_8_决赛_29', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'当然，这种早期的不同建筑文化的融合是非主动的、无意识的。', mt:'Certainly, this early fusion of different architectural cultures was passive and unconscious.', ref:'Of course, this early example of architectural assimilation was by no means intentional.' },
  { k:'seg_8_决赛_30', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'以后，随着西方文化的不断涌人，两种不同文化的融合成为一种必然，建筑中开始从设计上主动地表现出这种不同文化的融合。', mt:'In the future, with the continuous influx of Western culture, the fusion of these two distinct cultures became inevitable. Architecture began to actively reflect this cultural integration in its designs.', ref:'With the unchecked tide of Western culture flooding into the city, this intercultural integration became an inevitability, and buildings started to be purposely designed to display this cultural fusion.' },
  { k:'seg_8_决赛_31', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'里弄住宅是数量最大、最典型的例子。', mt:'Lane houses are the most numerous and typical example.', ref:'Lilong residences are the most numerous and typical example.' },
  { k:'seg_8_决赛_32', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'这种近代上海的新型居住建筑，自从产生的第一天起就打上了中西合璧的烙印。 从早期里弄看，它们的形式似乎并未摆脱传统的中国民居，然而它的总体连排式布局却来源于欧洲。', mt:'This new type of residential architecture in modern Shanghai has been marked by a fusion of Chinese and Western styles since its very inception. From the early alleyways, their form does not seem to break away from traditional Chinese residences, yet their overall row-house layout originates from Europe.', ref:'From its very first appearance in the city, this new form of housing epitomized the synthesis of Chinese and Western architecture. While the formal properties of the early lilong still seemed closely related to traditional Chinese dwellings, their overall arrangement in long rows was fully European in origin.' },
  { k:'seg_8_决赛_33', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'从早期里弄看，它们的形式似乎并未摆脱传统的中国民居，然而它的总体连排式布局却来源于欧洲。', mt:'From the early alleyways, their form does not seem to break away from traditional Chinese residences, yet their overall row-house layout originates from Europe.', ref:'While the formal properties of the early lilong still seemed closely related to traditional Chinese dwellings, their overall arrangement in long rows was fully European in origin.' },
  { k:'seg_8_决赛_34', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'早期里弄最有特色的地方——石库门，其门框、黑门板、 铜门环都不无中国传统建筑特征，而门上的三角形或圆弧形的门楣装饰则多为十足的西式图案。', mt:'The most distinctive feature of early alleyway houses—the Shikumen—lies in its door frames, black wooden doors, and brass knockers, all of which embody traditional Chinese architectural elements. Meanwhile, the triangular or arched lintel decorations above the doors often showcase distinctly Western- style patterns.', ref:'Many of the most characteristic features of these early lilong —the shikumen , the doorframe, the black door, and the copper doorknocker—were all typical of traditional Chinese architecture. Yet, the decorative lintel and its triangular or circular form were fully Western.' },
  { k:'seg_8_决赛_35', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'更为重要的是，这种建筑类型本身既非任何一种中国传统的居住建筑，也不是对任何一种西方建筑的模仿。', mt:'More importantly, this type of architecture is neither a traditional Chinese residential building nor an imitation of any Western architectural style.', ref:'Even more importantly, this building type was neither a variety of traditional Chinese residential architecture nor an import of Western architecture.' },
  { k:'seg_8_决赛_36', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'它是一种融合了中西建筑特征而产生的一种上海特有的中西合璧的新建筑。', mt:'It is a new type of architecture unique to Shanghai, blending Chinese and Western architectural features to create a harmonious fusion of both styles.', ref:'Rather, it was a wholly new type of synthetic building, peculiar to Shanghai and produced from the integration of Chinese and Western architectural features.' },
  { k:'seg_8_决赛_37', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'当然，上海近代建筑中西合璧现象远不止于里弄住宅。', mt:'Of course, the fusion of Chinese and Western elements in Shanghai\'s modern architecture extends far beyond the alleyway residences.', ref:'Shanghai’s architectural synthesis of China and the West certainly did not stop at the lilong .' },
  { k:'seg_8_决赛_38', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'在教堂、学校、医院及小住宅、办公楼、电影院等各种建筑类型，都普遍存在着这种现象。', mt:'This phenomenon is commonly found in various types of buildings, including churches, schools, hospitals, small residences, office buildings, and movie theaters.', ref:'Every type of architecture built in Shanghai—including churches, schools, hospitals, villas, office buildings, and cinemas—all of them exhibited this phenomenon.' },
  { k:'seg_8_决赛_39', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'这种中西合璧现象取决于近代上海整个社会意识形态中东西方两种文化从对立逐步走向认同。', mt:'This phenomenon of blending Chinese and Western elements stems from the gradual shift from opposition to mutual recognition between Eastern and Western cultures in the ideological landscape of modern Shanghai.', ref:'This synthesis depended on a larger ideological transformation that gradually took place in Shanghai, from cultural antagonism between China and the West toward mutual understanding.' },
  { k:'seg_8_决赛_40', ed:'8', stage:'决赛', dir:'汉译英', eng:'DeepSeek-V3', src:'事实上，上海建筑中的不中不西、半中半西、又中又西的不纯性存在于近代上海社会和文化中的各个方面，正是这样一种特有的中西合璧形成了上海近代建筑的最大特征。', mt:'In fact, the hybrid nature of Shanghai\'s architecture—neither purely Chinese nor purely Western, but a blend of both—permeates every aspect of modern Shanghai society and culture. It is precisely this unique fusion of East and West that defines the most distinctive feature of Shanghai\'s modern architecture.', ref:'In reality, the impure nature of Shanghai’s architecture—neither Western nor Chinese, half- Western and half-Chinese, both Western and Chinese—was characteristic of all aspects of the city’s social and cultural existence. This peculiar synthesis of China and the West is indeed the most unique feature of Shanghai’s architectural history.' },
  { k:'seg_8_初赛_1', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'E-Taste Technology: The Taste Revolution in the Digital Age', mt:'味觉科技：数字时代的味觉革命', ref:'电子味觉技术：数字时代的味觉革命' },
  { k:'seg_8_初赛_2', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'In the rapidly evolving landscape of sensory technology, one innovation stands poised to transform our relationship with food and flavor: e- taste.', mt:'在快速发展的感官技术领域，一项创新有望改变我们与食物和风味的关系：电子味觉。', ref:'感官技术发展日新月异，有项新技术正蓄势待发，或将彻底改变我们与食物和味道之间的关系，这便是“电子味觉”。' },
  { k:'seg_8_初赛_3', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Short for “electronic taste”, e-taste technology represents a groundbreaking fusion of neuroscience, artificial intelligence, and digital engineering, aimed at simulating, enhancing, and even creating entirely new taste experiences through electronic devices.', mt:'“电子味觉”的缩写，电子味觉技术代表了神经科学、 人工智能和数字工程的突破性融合，旨在通过电子设备模拟、增强甚至创造全新的味觉体验。', ref:'电子味觉（e-taste）是“electronic taste”的简称，代表着神经科学、人工智能与数字工程的突破性融合，旨在通过电子设备模拟、增强，甚至创造全新的味觉体验 。' },
  { k:'seg_8_初赛_4', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'As we venture further into the digital age, e-taste is not just a futuristic concept—it is becoming a tangible reality with profound implications for industries ranging from food and beverage to healthcare and entertainment.', mt:'随着我们进一步进入数字时代，电子味觉不仅仅是一个未来概念——它正在成为一个具有深远影响的现实，涉及从食品饮料到医疗保健和娱乐等多个行业。', ref:'随着我们迈入数字时代，电子味觉不再只是未来想象， 而正成为切实可行的现实，且对餐饮、医疗乃至娱乐等多个行业带来深远影响。' },
  { k:'seg_8_初赛_5', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'At its core, e-taste technology seeks to replicate the complex process of human taste perception.', mt:'电子味觉技术的核心是复制人类味觉感知的复杂过程。', ref:'电子味觉技术的核心目标是再现人类复杂的味觉感知过程。' },
  { k:'seg_8_初赛_6', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Taste, as we know it, is a multifaceted sensory experience involving the detection of five primary flavors—sweet, sour, salty, bitter, and umami—by taste buds on the tongue.', mt:'我们所知的味觉是一种多方面的感官体验，涉及舌头上的味蕾对五种基本味道的检测——甜、酸、咸、苦和鲜味。', ref:'我们所说的“味道”是一个多维度的感官体验，涉及舌尖上的味蕾对五种基本味道——甜、酸、咸、苦、鲜的感知。' },
  { k:'seg_8_初赛_7', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'However, the full experience of flavor also incorporates smell, texture, temperature, and even visual cues, making it a highly intricate phenomenon to replicate artificially.', mt:'然而，完整的风味体验还包括气味、质地、温度甚至视觉线索，这使得人工复制成为一个高度复杂的现象。', ref:'然而，完整的味道体验还包括嗅觉、口感、温度，甚至视觉线索，这导致人工再现变得异常复杂。' },
  { k:'seg_8_初赛_8', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'E-taste technology addresses this challenge by employing a combination of electrochemical sensors, neural interfaces, and machine learning algorithms to decode and simulate taste signals.', mt:'电子味觉技术通过结合电化学传感器、神经接口和机器学习算法来解码和模拟味觉信号，从而应对这一挑战。', ref:'为应对这一挑战，电子味觉技术结合了电化学传感器、 神经接口和机器学习算法来解析并模拟味觉信号。' },
  { k:'seg_8_初赛_9', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'The journey of e-taste began in the early 2000s, when researchers first experimented with “electronic tongues”—devices designed to mimic the human taste system for industrial applications, such as quality control in food production.', mt:'电子味觉的旅程始于21世纪初，当时研究人员首次尝试“电子舌头”——一种旨在模仿人类味觉系统的设备， 用于食品生产中的质量控制等工业应用。', ref:'21世纪初，研究人员开始研究电子味觉，并首次尝试开发“电子舌头”这类装置，通过模拟人类味觉系统，应用于工业场景，例如食品生产中的质量控制。' },
  { k:'seg_8_初赛_10', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'These early systems used arrays of chemical sensors to detect and analyze the composition of liquids, providing a rudimentary form of taste profiling. However, they lacked the ability to translate these detections into a human-like taste experience.', mt:'这些早期系统使用化学传感器阵列来检测和分析液体的成分，提供了一种初步的味觉分析。然而，它们无法将这些检测结果转化为类似人类的味觉体验。', ref:'这些早期系统利用化学传感器阵列对液体成分进行检测和分析，从而实现了初步的味觉分析，但却无法将检测结果转化为人类可感知的味觉体验。' },
  { k:'seg_8_初赛_11', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'It wasn’t until advancements in neural decoding and brain-computer interfaces (BCIs) emerged that the possibility of directly stimulating the brain’s taste centers became feasible.', mt:'直到神经解码和脑机接口（BCI）技术的进步出现，直接刺激大脑味觉中心的可能性才变得可行。', ref:'直到神经解码与脑机接口技术取得突破，直接刺激大脑味觉中枢才有可能实现。' },
  { k:'seg_8_初赛_12', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Today’s e-taste devices operate on the principle of neural modulation.', mt:'如今的电子味觉设备基于神经调制的原理运作。', ref:'当今，电子味觉设备基于神经调控原理运作。' },
  { k:'seg_8_初赛_13', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'By using non-invasive methods such as transcranial magnetic stimulation (TMS) or invasive techniques like implanted electrodes, these devices can activate specific neural pathways associated with taste perception. For instance, a user might wear a headset that delivers precise magnetic pulses to the gustatory cortex, the brain region responsible for processing taste.', mt:'通过使用非侵入性方法，如经颅磁刺激（TMS），或侵入性技术，如植入电极，这些设备可以激活与味觉感知相关的特定神经通路。 例如，用户可能会佩戴一个向负责处理味觉的大脑区域 ——味觉皮层——传递精确磁脉冲的头戴设备。', ref:'这些设备通过“非侵入性技术”，如经颅磁刺激（TMS），或是“侵入性技术”，如植入电极，便可激活与味觉感知相关的大脑神经通路。 例如，用户可以佩戴一种头戴装置，向大脑负责处理味觉信号的“味觉皮层”释放精准的磁脉冲。' },
  { k:'seg_8_初赛_14', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'For instance, a user might wear a headset that delivers precise magnetic pulses to the gustatory cortex, the brain region responsible for processing taste.', mt:'例如，用户可能会佩戴一个向负责处理味觉的大脑区域 ——味觉皮层——传递精确磁脉冲的头戴设备。', ref:'例如，用户可以佩戴一种头戴装置，向大脑负责处理味觉信号的“味觉皮层”释放精准的磁脉冲。' },
  { k:'seg_8_初赛_15', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'When calibrated correctly, these pulses can evoke sensations of sweetness, saltiness, or other flavors without any physical ingestion.', mt:'当正确校准时，这些脉冲可以在没有任何物理摄入的情况下唤起甜味、咸味或其他风味的感觉。', ref:'经校准设备后，这些脉冲可以在人类不摄入任何食物的前提下，引发“甜”“咸”等各种味觉感受。' },
  { k:'seg_8_初赛_16', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'This technology, while still in its nascent stages, has already shown promise in controlled laboratory settings.', mt:'这项技术虽然仍处于起步阶段，但已经在受控的实验室环境中显示出前景。', ref:'这项技术虽仍处于早期开发阶段，但在实验室环境中已初见成效。' },
  { k:'seg_8_初赛_17', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Beyond mere simulation, e-taste technology is also being integrated with artificial intelligence to create personalized taste experiences.', mt:'除了模拟之外，电子味觉技术还与人工智能结合，以创造个性化的味觉体验。', ref:'电子味觉技术不仅可以模拟味觉，同时也在与人工智能融合，进而打造个性化的味觉体验。' },
  { k:'seg_8_初赛_18', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Imagine a scenario where an AI-powered e-taste device learns your flavor preferences over time, adjusting its stimulations to enhance your enjoyment of certain foods or even to help you explore new tastes.', mt:'想象一下，一个由人工智能驱动的电子味觉设备随着时间的推移学习你的口味偏好，调整其刺激以增强你对某些食物的享受，甚至帮助你探索新的味道。', ref:'设想以下场景：AI驱动的电子味觉设备能随着时间了解你的口味偏好，并相应调整刺激参数，以增强你对特定食物的喜好，甚至引导你尝试新口味。' },
  { k:'seg_8_初赛_19', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Such applications could revolutionize the culinary world, allowing chefs to craft “digital recipes” that users can experience without the need for physical ingredients.', mt:'这样的应用可能会彻底改变烹饪世界，允许厨师制作“ 数字食谱”，用户无需物理食材即可体验。', ref:'这类设备有望彻底变革烹饪艺术，助力厨师创作出“数字食谱”，用户则无需品尝真实食材即可体验相应菜品的风味。' },
  { k:'seg_8_初赛_20', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Moreover, e-taste could play a pivotal role in addressing global food challenges, such as reducing sugar or salt intake by providing the perception of these flavors without their actual consumption, thereby promoting healthier diets.', mt:'此外，电子味觉可以在应对全球食品挑战中发挥关键作用，例如通过提供这些风味的感知而不实际摄入，从而减少糖或盐的摄入，促进更健康的饮食。', ref:'此外，电子味觉还可能在应对全球饮食挑战中发挥关键作用，例如，可通过模拟甜味或咸味，让人无需实际摄入过多糖分或盐分便可获得相应味觉体验，从而推动更健康的饮食习惯。' },
  { k:'seg_8_初赛_21', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'The potential applications of e-taste extend far beyond the dining table.', mt:'电子味觉的潜在应用远远超出了餐桌。', ref:'电子味觉的应用潜力远不止于餐饮。' },
  { k:'seg_8_初赛_22', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'In the medical field, e-taste technology holds promise for patients suffering from taste disorders, such as ageusia (loss of taste) or dysgeusia (distorted taste).', mt:'在医学领域，电子味觉技术为患有味觉障碍的患者，如味觉丧失（味觉缺失）或味觉扭曲（味觉障碍），带来了希望。', ref:'在医学领域，它对患有味觉丧失、味觉紊乱等味觉障碍的患者具有治疗前景。' },
  { k:'seg_8_初赛_23', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'By directly stimulating the brain’s taste centers, e- taste devices could help restore or compensate for impaired taste functions, improving the quality of life for individuals affected by these conditions.', mt:'通过直接刺激大脑的味觉中心，电子味觉设备可以帮助恢复或补偿受损的味觉功能，从而改善受这些病症影响的个体的生活质量。', ref:'电子味觉设备通过直接刺激大脑味觉中枢，有望恢复或弥补受损的味觉功能，提升患者的生活质量。' },
  { k:'seg_8_初赛_24', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Additionally, e-taste could be used in conjunction with virtual reality (VR) to create immersive multisensory experiences.', mt:'此外，电子味觉可以与虚拟现实（VR）结合使用，创造沉浸式的多感官体验。', ref:'此外，它还可以与虚拟现实结合，打造沉浸式的多感官体验。' },
  { k:'seg_8_初赛_25', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'For example, in a VR game, players might not only see and hear their environment but also taste virtual foods, adding a new layer of realism to digital worlds.', mt:'例如，在VR游戏中，玩家不仅可以看见和听见周围环境，还可以品尝虚拟食物，为数字世界增添了一层新的真实感。', ref:'例如，在一款虚拟现实游戏中，玩家不仅可以“看到”并“听到”虚拟世界，还能“尝到”其中的美食，为数字场景增添味觉层面的真实感。' },
  { k:'seg_8_初赛_26', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'However, the path to widespread adoption of e- taste technology is fraught with challenges.', mt:'然而，电子味觉技术的广泛应用之路充满了挑战。', ref:'然而，广泛应用电子味觉技术仍然存在诸多挑战。' },
  { k:'seg_8_初赛_27', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'One of the primary technical hurdles is achieving precise and consistent taste simulation.', mt:'主要的技术障碍之一是实现精确且一致的味觉模拟。', ref:'技术上最主要的难题之一是实现精确、一致的味觉模拟 。' },
  { k:'seg_8_初赛_28', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'The human taste system is incredibly nuanced, with individual differences in taste perception influenced by genetics, culture, and even mood.', mt:'人类的味觉系统极其复杂，个体之间的味觉感知差异受到遗传、文化甚至情绪的影响。', ref:'人类味觉系统极其细腻，不同个体之间的味觉感知受基因、文化乃至情绪影响而存在巨大差异。' },
  { k:'seg_8_初赛_29', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Replicating this variability in a controlled manner requires sophisticated algorithms and a deep understanding of neurobiology.', mt:'以可控的方式复制这种变异性需要复杂的算法和对神经生物学的深入理解。', ref:'要在可控条件下再现这种差异性，需要极其复杂的算法以及对神经生物学的深入理解。' },
  { k:'seg_8_初赛_30', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Furthermore, ensuring the safety and comfort of neural stimulation methods is paramount, as improper use could lead to adverse effects such as headaches, dizziness, or even long-term neural damage.', mt:'此外，确保神经刺激方法的安全性和舒适性至关重要， 因为使用不当可能导致头痛、头晕甚至长期的神经损伤等不良反应。', ref:'此外，确保神经刺激方式的安全性与舒适性至关重要， 操作不当可能引发头痛、眩晕，甚至长期神经损伤。' },
  { k:'seg_8_初赛_31', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Ethical considerations also loom large in the development of e-taste technology.', mt:'伦理问题在电子味觉技术的发展中也显得尤为重要。', ref:'与此同时，在电子味觉技术的发展过程中，伦理问题也日益突出。' },
  { k:'seg_8_初赛_32', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'The ability to manipulate taste perception raises questions about consent and autonomy, particularly in scenarios where e-taste might be used to alter food preferences or consumption habits without the user’s full understanding. Privacy concerns are another issue, as e-taste devices could potentially collect sensitive data about users’ eating habits, preferences, and even health conditions. Ensuring that this data is handled responsibly and transparently will be crucial to building public trust in the technology.', mt:'操纵味觉感知的能力引发了关于同意和自主性的问题， 特别是在电子味觉可能被用于在用户不完全理解的情况下改变食物偏好或消费习惯的场景中。 隐私问题是另一个问题，因为电子味觉设备可能会收集有关用户饮食习惯、偏好甚至健康状况的敏感数据。 确保这些数据以负责任和透明的方式处理，对于建立公众对该技术的信任至关重要。', ref:'操控味觉感知的能力引发了有关知情同意和个人自主权的问题，尤其在用户未充分了解的情况下改变其食物偏好或饮食习惯时，这一问题尤为突出。 隐私问题也备受关注，因为电子味觉设备可能收集关于用户饮食习惯、口味偏好乃至健康状况的敏感数据。 因此，数据处理的透明度和安全性或将成为赢得公众信任的关键。' },
  { k:'seg_8_初赛_33', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Privacy concerns are another issue, as e-taste devices could potentially collect sensitive data about users’ eating habits, preferences, and even health conditions.', mt:'隐私问题是另一个问题，因为电子味觉设备可能会收集有关用户饮食习惯、偏好甚至健康状况的敏感数据。', ref:'隐私问题也备受关注，因为电子味觉设备可能收集关于用户饮食习惯、口味偏好乃至健康状况的敏感数据。' },
  { k:'seg_8_初赛_34', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Ensuring that this data is handled responsibly and transparently will be crucial to building public trust in the technology.', mt:'确保这些数据以负责任和透明的方式处理，对于建立公众对该技术的信任至关重要。', ref:'因此，数据处理的透明度和安全性或将成为赢得公众信任的关键。' },
  { k:'seg_8_初赛_35', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Moreover, there is the risk of over-reliance on artificial taste experiences, which could diminish the appreciation for natural flavors and traditional culinary practices.', mt:'此外，还存在过度依赖人工味觉体验的风险，这可能会削弱对天然风味和传统烹饪实践的欣赏。', ref:'此外，过度依赖人工味觉体验也可能削弱人们对自然风味和传统烹饪的欣赏。' },
  { k:'seg_8_初赛_36', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'As e-taste becomes more sophisticated, it may blur the lines between real and artificial, leading to philosophical debates about the authenticity of sensory experiences.', mt:'随着电子味觉变得更加复杂，它可能会模糊真实与人工之间的界限，从而引发关于感官体验真实性的哲学辩论 。', ref:'随着电子味觉日益先进，真实与人工之间的界限可能会日渐模糊，进而引发关于感官体验真实性的哲学争论。' },
  { k:'seg_8_初赛_37', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Will a digitally simulated taste ever truly match the richness of a naturally grown ingredient?', mt:'数字模拟的味觉是否真的能与天然食材的丰富性相媲美？', ref:'数字模拟出的味道是否真能与天然食材的丰富性相媲美？' },
  { k:'seg_8_初赛_38', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'And if it does, what does that mean for the future of food production and consumption?', mt:'如果能够做到，这对未来的食品生产和消费意味着什么？', ref:'如果可以，那我们未来的食物生产和消费方式又将何去何从？' },
  { k:'seg_8_初赛_39', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Despite these challenges, the momentum behind e- taste technology is undeniable.', mt:'尽管存在这些挑战，电子味觉技术的势头不可否认。', ref:'尽管面临这些挑战，电子味觉技术的发展势头不可小觑 。' },
  { k:'seg_8_初赛_40', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Major tech companies and startups alike are investing heavily in research and development, with some prototypes already entering the consumer market.', mt:'型科技公司和初创企业都在大力投资研发，一些原型已经进入消费市场。', ref:'多家大型科技公司与初创企业正积极投入研发，部分原型产品已进入消费市场。' },
  { k:'seg_8_初赛_41', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'For instance, a Japanese company recently unveiled a “taste display” that uses ion electrophoresis to stimulate the tongue, creating basic taste sensations.', mt:'例如，一家日本公司最近推出了一种“味觉显示器”， 它使用离子电泳来刺激舌头，产生基本的味觉感受。', ref:'例如，一家日本公司最近发布了一款“味觉显示器”， 通过离子电泳刺激舌头，营造基础味觉感受。' },
  { k:'seg_8_初赛_42', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'While still rudimentary, such innovations signal a growing interest in bringing e-taste to the masses.', mt:'虽然仍处于初级阶段，但此类创新表明人们对将电子味觉推向大众的兴趣日益增长。', ref:'虽然目前仍较为原始，但这些技术创新表明，电子味觉正逐步走向大众市场。' },
  { k:'seg_8_初赛_43', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Looking ahead, the future of e-taste is likely to be shaped by its integration with other emerging technologies.', mt:'展望未来，电子味觉的发展可能会受到其与其他新兴技术整合的影响。', ref:'展望未来，电子味觉技术可能将与其他新兴技术深度融合。' },
  { k:'seg_8_初赛_44', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'The convergence of e-taste with augmented reality (AR), for example, could lead to “augmented dining” experiences, where digital overlays enhance the flavor of physical foods in real time.', mt:'例如，电子味觉与增强现实（AR）的结合可能会带来“ 增强用餐”体验，其中数字叠加实时增强物理食物的风味。', ref:'例如，将电子味觉与增强现实（AR）融合，可实现“增强用餐”体验，即通过数字风味实时叠加于真实食物上，提升味觉感受。' },
  { k:'seg_8_初赛_45', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Similarly, pairing e-taste with generative AI could enable the creation of entirely new flavors that have never been experienced before, pushing the boundaries of culinary creativity.', mt:'同样，将电子味觉与生成式AI结合，可能会创造出前所未有的全新风味，推动烹饪创意的边界。', ref:'再如，与生成式人工智能配对，甚至可能创造出前所未有的全新风味，突破传统烹饪创意的边界。' },
  { k:'seg_8_初赛_46', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'As we stand on the brink of this taste revolution, it is clear that e-taste technology has the potential to redefine our relationship with food and flavor.', mt:'当我们站在这场味觉革命的门槛上时，很明显，电子味觉技术有潜力重新定义我们与食物和风味的关系。', ref:'面对当下这场味觉革命，电子味觉显然有望重塑人类与食物、与味道之间的关系。' },
  { k:'seg_8_初赛_47', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'Whether it will be embraced as a tool for enhancing human experience or viewed with skepticism remains to be seen.', mt:'它是否会被视为增强人类体验的工具，还是会受到怀疑，仍有待观察。', ref:'它究竟会成为增强人类感官体验的利器，还是被公众质疑的科技手段？' },
  { k:'seg_8_初赛_48', ed:'8', stage:'初赛', dir:'英译汉', eng:'DeepSeek-V3', src:'What is certain, however, is that e-taste is not just a fleeting trend—it is a glimpse into the future of sensory technology, where the digital and the physical converge in ways previously unimaginable.', mt:'然而，可以肯定的是，电子味觉不仅仅是一个短暂的趋势——它是对未来感官技术的一瞥，在这个未来中，数字与物理以前所未有的方式融合。', ref:'答案尚未可知。但可以肯定的是，电子味觉绝非昙花一现，而是感官科技未来的预演，在数字与现实之间搭建起前所未有的桥梁。' }
];
